ll solve(const vector<ll>& v, int flg){
  ll ret = 0;

  ll a = 0, b = v.size()-1;

  ll l, r;
  if(flg == 0){
    l = v[a];
    r = v[a];
    a++;
    flg = 1;
  }else{
    l = v[b];
    r = v[b];
    b--;
    flg = 0;
  }

  while(a <= b){
    if(flg == 0){
      bool which = false;
      if(a<=b) {
        if(abs(l-v[a]) > abs(r-v[a])){
          ret += abs(l-v[a]);
          l = v[a];
          which = false;
        }else{
          ret += abs(r-v[a]);
          r = v[a];
          which = true;
        }
        a++;
      }
      if(a<=b) {
        if(which){
          ret += abs(l-v[a]);
          l = v[a];
        }else{
          ret += abs(r-v[a]);
          r = v[a];
        }
        a++;
      }
      flg = 1;
    }else{
      bool which = false;
      if(a<=b) {
        if(abs(l-v[b]) > abs(r-v[b])){
          ret += abs(l-v[b]);
          l = v[b];
          which = false;
        }else{
          ret += abs(r-v[b]);
          r = v[b];
          which = true;
        }
        b--;
      }
      if(a<=b) {
        if(which){
          ret += abs(l-v[b]);
          l = v[b];
        }else{
          ret += abs(r-v[b]);
          r = v[b];
        }
        b--;
      }
      flg = 0;
    }
  }

  return ret;
}


