ll solve(ll n, deque<ll> b) {
    sort(all(b));
    deque<ll> tmp;
    tmp.pb(b[0]);
    b.pop_front();
    ll ret = 0;
    while (b.size()) {
        ll ii, jj;
        ll cost = -INF;
        rep(i, 2) rep(j, 2) {
            ll x = -1;
            if (i == 0) {
                x = tmp.back();
            } else {
                x = tmp.front();
            }

            ll y = -1;
            if (j == 0) {
                y = b.back();
            } else {
                y = b.front();
            }

            if (abs(x - y) > cost) {
                ii = i;
                jj = j;
                cost = abs(x - y);
            }
        }
        ll y;
        if (jj == 0) {
            y = b.back();
            b.pop_back();
        } else {
            y = b.front();
            b.pop_front();
        }

        if (ii == 0) {
            tmp.pb(y);
        } else {
            tmp.push_front(y);
        }


        ret += cost;
    }

//    cout << tmp << endl;
    return ret;
}

