#define REP(i, a, n) for (ll i = ((ll) a); i < ((ll) n); i++)
using namespace std;
typedef long long ll;

ll solve(ll N, vector<ll> &A, bool w) {
  deque<ll> q;
  bool t = true;
  ll i = 0, j = N - 1;
  while (i <= j) {
    if (i == j) {
      if (w) {
        q.push_front(A[i]);
      } else {
        q.push_back(A[i]);
      }
      break;
    }
    if (t) {
      q.push_front(A[i++]);
      if (i <= j) q.push_back(A[j--]);
    } else {
      q.push_back(A[i++]);
      if (i <= j) q.push_front(A[j--]);
    }
    t = !t;
  }

  vector<ll> a(N);
  REP(i, 0, N) {
    a[i] = q.front();
    q.pop_front();
  }

  ll ans = 0;
  REP(i, 0, N - 1) ans += abs(a[i] - a[i + 1]);
  return ans;
}

int main(void) {
  ll N;
  cin >> N;
  vector<ll> A(N);
  REP(i, 0, N) cin >> A[i];
  sort(A.begin(), A.end());

  cout << max(solve(N, A, false), solve(N, A, true)) << endl;
}

