ll solve(vector<ll>& a){
    ll n = a.size();

    ll i = 0;
    ll j = n-1;

    ll left = a[i];
    ll right = a[i];
    i++;

    ll sum = 0;
    ll cnt = 1;
    while(i <= j){
        if(0 <= j){
            sum += abs(left-a[j]);
            left = a[j];
            cnt++;
        }
        j--;
        if(cnt == n) break;

        if(0 <= j){
            sum += abs(right-a[j]);
            right = a[j];
            cnt++;
        }
        j--;
        if(cnt == n) break;

        if(i < n){
            sum += abs(left-a[i]);
            left = a[i];
            cnt++;
        }
        i++;
        if(cnt == n) break;

        if(i < n){
            sum += abs(right-a[i]);
            right = a[i];
            cnt++;
        }
        i++;
        if(cnt == n) break;
    }

    return sum;
}

