	for (int i = 0; i < n; i++) {
		int tmp; cin >> tmp;
		V.push_back(tmp);
	}

	sort(V.begin(), V.end());

	ll ans = 0;
	if (n % 2 == 0) {
		for (int i = 0; i < n / 2 - 1; i++) ans -= 2 * V[i];
		ans -= V[n / 2 - 1];
		ans += V[n / 2];
		for (int i = n / 2 + 1; i < V.size(); i++) ans += 2 * V[i];
