const ll MOD = 1000000007;
const ll INF = (ll)1e15;

//! 昇順にソートした配列
ll Min[100005];
//! 降順にソートした配列
ll Max[100005];

int main()
{
	int N;
	cin >> N;
	REP(i, N)
	{
		cin >> Min[i];
		Max[i] = Min[i];
	}
	sort(Min, Min + N);
	sort(Max, Max + N, [](ll a, ll b) {return a > b; });

	//! 配列の初期要素は最も小さい値としておく
	ll edge[2] = { Min[0],Min[0] };
	//! 挿入候補のIndex(Min,Maxの配列それぞれについて用意)
	int minIndex = 1, maxIndex = 0;

	ll ans = 0;
	//! 挿入要素がN個になるまでループ
	while (minIndex + maxIndex < N)
	{
		//! 挿入候補を取得
		ll min = Min[minIndex], max = Max[maxIndex];
		//! minを挿入したときに差が最大となる端点
		ll &minEdge = abs(min - edge[0]) > abs(min - edge[1]) ? edge[0] : edge[1];
		//! maxを挿入したときに差が最大となる端点
		ll &maxEdge = abs(max - edge[0]) > abs(max - edge[1]) ? edge[0] : edge[1];

		ll diffMin = abs(min - minEdge), diffMax = abs(max - maxEdge);
		if (diffMin > diffMax)
		{
			//! 最小値を挿入したほうが大きい値が得られる
			minEdge = Min[minIndex++];
		}
		else
		{
			//! 最大値を挿入したほうが大きい値が得られる
			maxEdge = Max[maxIndex++];
		}
		ans += std::max(diffMin, diffMax);

	}
	cout << ans << endl;
	return 0;
}

