			que.pop_front();
		}
		else{
			b[i] = que.back();
			que.pop_back();
		}
		flg = !flg;
	}
	ll sum = 0;
	for(int i = 0; i < n - 2; ++i){
		sum += abs(b[i] - b[i + 1]);
	}
	sum += max(abs(b[0] - b[n - 1]), abs(b[1] - b[n - 1]));

	cout << sum << "\n";

