intmax_t diffmax(std::deque<intmax_t> a) {
  size_t n=a.size();
  std::vector<intmax_t> b;

  std::vector<intmax_t> mae, ush;
  while (!a.empty()) {
    mae.push_back(a.front());
    a.pop_front();
    if (a.empty()) break;
    ush.push_back(a.back());
    a.pop_back();
  }
  b.push_back(mae.back());
  mae.pop_back();
  std::reverse(mae.begin(), mae.end());
  std::reverse(ush.begin(), ush.end());

  while (!mae.empty() && !ush.empty()) {
    b.push_back(ush.back());
    ush.pop_back();
    b.push_back(mae.back());
    mae.pop_back();
  }
  if (!ush.empty())
    b.push_back(ush.back());
  if (!mae.empty())
    b.push_back(mae.back());

  for (size_t i=0; i<n; ++i)
    fprintf(stderr, "%jd%c", b[i], i+1<n? ' ':'\n');

  intmax_t res=0;
  for (size_t i=1; i<n; ++i) {
    intmax_t d=b[i]-b[i-1];
    res += (d>0? d:-d);
  }
  return res;
}

int main() {
  size_t N;
  scanf("%zu", &N);

  std::deque<intmax_t> A(N);
  for (size_t i=0; i<N; ++i)
    scanf("%jd", &A[i]);

  std::sort(A.begin(), A.end());

  intmax_t res=0;
  res = diffmax(A);
  std::reverse(A.begin(), A.end());
  res = std::max(res, diffmax(A));
  printf("%jd\n", res);
}

