int main() {
  int N;
  while (cin >> N) {
    vector<ll> A(N);
    for (int i = 0; i < N; i++) cin >> A[i];
    sort(A.begin(), A.end());
    deque<ll> B;
    int l = 0, r = N - 1;
    while (l <= r) {
      if (l != r) {
        if (B.empty()) {
          B.push_back(A[l]);
          B.push_back(A[r]);
        } else {
          ll a = abs(A[l] - B.front()) + abs(A[r] - B.back());
          ll b = abs(A[r] - B.front()) + abs(A[l] - B.back());
          if (a > b) {
            B.push_front(A[l]);
            B.push_back(A[r]);
          } else {
            B.push_front(A[r]);
            B.push_back(A[l]);
          }
        }
      } else {
        ll a = abs(A[l] - B.front());
        ll b = abs(A[l] - B.back());
        if (a > b) {
          B.push_front(A[l]);
        } else {
          B.push_back(A[l]);
        }
      }
      ++l;
      --r;
    }
    ll res = 0;
    for (int i = 1; i < N; i++) res += abs(B[i] - B[i - 1]);
    cout << res << endl;
  }
  return 0;
}

