void solve(){
	int n = 0, m = 0, cnt = 0, sum = 0, mx = -1e18, mn = 1e18, k = 0, ans = 0;
    cin >> n;
    int a[n+1];
    fr(i, 1, n+1) cin >> a[i];
    sort(a+1, a+n+1);
    if(n % 2 == 0){
        for(int i=n; i>=1; i--){
            if(i == n/2 + 1) ans += a[i];
            else if(i == n/2) ans -= a[i];
            else if(i > n/2) ans += a[i]*2;
            else ans -= a[i]*2;
        }
    }
    else{

        for(int i=n; i>=1; i--){
            if(i == n/2 + 1) ans -= a[i];
            else if(i == n/2) ans -= a[i];
            else if(i > n/2) ans += a[i]*2;
            else ans -= a[i]*2;
        }
        int s1 = 0;
        for(int i = n/2; i > 0; i--){
            s1 += a[i];
        }
        s1 *= 2;
        int s2 = a[n/2+1]+a[n/2+2];
        for(int i = n/2+3; i <= n; i++){
            s2 += 2*a[i];
        }
        s2 = s2 - s1;
        ans = max(ans, s2);

    }
    cout << ans;
}

