	data.pop_front();
	int sum = 0;
	while (data.size()>0){
		// maxを前に入れる場合
		int m1 = abs(q.front() -  data.back());
		// maxを後ろに入れる場合
		int m2 = abs(q.back() - data.back());
		// minを前に入れる場合
		int m3 = abs(q.front() - data.front());
		// minを後ろに入れる場合
		int m4 = abs(q.back() - data.front());

		int best = max(m1, max(m2, max(m3, m4)));
		sum += best;
		if (best == m1){
			q.push_front(data.back()); data.pop_back();
		}
		else if (best == m2){
			q.push_back(data.back()); data.pop_back();
		}
		else if (best == m3){
			q.push_front(data.front()); data.pop_front();
		}
		else{
			q.push_back(data.front()); data.pop_front();
		}
	}

	cout << sum << endl;

	return 0;
}

