        v.push_back(tmp);
    }

    std::vector<std::vector<long>> vs;
    vs.resize(fact(n));
    for (auto v : vs){
        v.resize(n);
    }
    std::sort(v.begin(),v.end());
    int ct = 0;
    do {
        for (auto k : v) {
            vs[ct].push_back(k);
        }
