    long prev = 0;
    for (auto x : vs) {
        prev = t = 0;
        for (auto i : x) {
            if (prev != 0) {
                t += std::abs(i-prev);
            }
            prev = i;
        }
        ans = std::max(ans, t);
    }

    std::cout << ans << '\n';
}

