ll func(int n,vector<ll> x){
  int front=0,back=n-1;
  deque<ll> res;
  bool is_front = false;
  int cnt = 0;
  res.push_front(x[0]);
  front++;
  while(front<=back){
    if(is_front){
      if(cnt == 0){
        res.push_front(x[front]);
        cnt++;
        front++;
      }else if(cnt == 1){
        res.push_back(x[front]);
        front++;
        is_front = false;
        cnt = 0;
      }
    }else{
      if(cnt == 0){
        res.push_front(x[back]);
        cnt++;
        back--;
      }else if(cnt == 1){
        res.push_back(x[back]);
        back--;
        is_front = true;
        cnt = 0;
      }
    }
  }
  vector<ll> ress;
  ll ans = 0;
  for(auto itr = res.begin(); itr != res.end(); ++itr){
    ress.push_back(*itr);
  }
  for(int i = 1; i < n; i++){
    ans += abs(ress[i]-ress[i-1]);
  }

  return ans;
}

