void solve(long long n, vector<long long> a){
	assert(n%2==0);
	srand(19260817);
	sort(a.begin(),a.end());
	/*for(auto i:a) {
		cout<<i<<' ';
	}
	cout<<endl;*/
	LL ans1=0;
	LL l=a[0],r=a[0];
	for(int i=2; i<=n; ++i) {
		LL now;
		if (i%2==0) {
			now=a[n-i/2];
		} else {
			now=a[i/2];
		}
		if (abs(now-l)>abs(now-r) || (abs(now-l)==abs(now-r) && rand()%2==0)) {
			ans1+=abs(now-l);
			l=now;
		} else {
			ans1+=abs(now-r);
			r=now;
		}
	}
	LL ans2=0;
	l=a[n-1];
	r=a[n-1];
	deque<int> x;
	x.push_back(l);
	for(int i=2; i<=n; ++i) {
		LL now;
		if (i%2==0) {
			now=a[i/2-1];
		} else {
			now=a[n-i/2-1];
		}
		if (abs(now-l)>abs(now-r) || (abs(now-l)==abs(now-r) && rand()%2==0)) {
			x.push_front(now);
			ans2+=abs(now-l);
			l=now;
		} else {
			ans2+=abs(now-r);
			x.push_back(now);
			r=now;
		}
	}
	/*for(auto i:x) {
		cout<<i<<' ';
	}
	cout<<endl;*/
	debug(ans1,ans2);
	cout<<max(ans1,ans2)<<endl;
}

