    REP(i,n) dq.push_back(a[i]);

    ll t = dq.front(); dq.pop_front();
    ll b = dq.back(); dq.pop_back();

    ans.push_front(t);
    ans.push_back(b);
    bool last_one = false;

    while (dq.size() > 1) {
        t = dq.front(); dq.pop_front();
        b = dq.back(); dq.pop_back();
        ll at = ans.front(); ll ab = ans.back();
        ll tmp1 = abs(t-at)+abs(b-ab);
        ll tmp2 = abs(t-ab)+abs(b-at);
        if (tmp1 < tmp2) {
            swap(t,b);
        }
        ans.push_front(t);
        ans.push_back(b);
    }

    if (dq.size() == 1) {
        ll one = dq.front(); dq.pop_front();
        ll at = ans.front(); ll ab = ans.back();
        ll tmp1 = abs(one-at); ll tmp2 = abs(one-ab);
        if (tmp1 > tmp2) ans.push_front(one);
        else ans.push_back(one);
    }

    ll cnt = 0ll;
    ll x = ans.front(); ans.pop_front();
    while (!ans.empty()) {
        ll y = ans.front(); ans.pop_front();
        cnt += abs(x-y);
        x = y;
    }

    cout << cnt << endl;

    return 0;
}

