		if (y<0){
			y=-y;
		}		
		if (x>=y){
			vit=B.begin();
			B.insert(vit,A[start]);
		}else{
			B.push_back(A[start]);
		}
		if (start>=end){
			break;
		}
		x=A[end]-B[0];
		if (x<0){
			x=-x;
		}
		y=A[end]-B[B.size()-1];
