ll calc(vector<ll> a, vector<ll> b, int n){
  vector<ll> c(n);

  if (n % 2 == 0){
    for(int i=0, j=0, k=0; i<n/2; i++){
      c[n-2*i-2] = a[j++];
      c[n-2*i-1] = b[k++];
    }
  }
  else{
    if(a.size() < b.size()) swap(a, b);

    swap(a[0], a[n/2-1]);

    for(int i=0, j=0, k=0; i<n; i++){
      if(i % 2){
        c[i] = b[j++];
      }
      else{
        c[i] = a[k++];
      }
    }
  }

  ll ans = 0;
  REP(i, n-1) ans += abs(c[i+1]-c[i]);

  return ans;
}

