ll calc(int large_index, int small_index, int left, int right, bool isNextLarge) {
  ll result = 0;
  if (isNextLarge) {
    large_index--;
    if (large_index <= small_index || large_index < 0) {
      // printf("1: large_index = %d, small_index = %d, left = %d, right = %d, isNextLarge = %d\n", large_index, small_index, left, right, (int)isNextLarge);
      return result;
