    large_index--;
    if (large_index <= small_index || large_index < 0) {
      // printf("2: large_index = %d, small_index = %d, left = %d, right = %d, isNextLarge = %d\n", large_index, small_index, left, right, (int)isNextLarge);
      return result;
    }

    result += abs(right - a[large_index]);
    // printf("6: result[%lld] = abs(%d - %d)\n", result, right, a[large_index]);
    right = a[large_index];
  }
  else {
    small_index++;
    if (small_index >= large_index || small_index >= n) {
      // printf("3: large_index = %d, small_index = %d, left = %d, right = %d, isNextLarge = %d\n", large_index, small_index, left, right, (int)isNextLarge);
      return result;
    }

    result += abs(left - a[small_index]);
    // printf("7: result[%lld] = abs(%d - %d)\n", result, left, a[small_index]);
    left = a[small_index];

    small_index++;
    if (small_index >= large_index || small_index >= n) {
      // printf("4: large_index = %d, small_index = %d, left = %d, right = %d, isNextLarge = %d\n", large_index, small_index, left, right, (int)isNextLarge);
      return result;
    }

    result += abs(right - a[small_index]);
    // printf("8: result[%lld] = abs(%d - %d)\n", result, right, a[small_index]);
    right = a[small_index];
  }

  return result + calc(large_index, small_index, left, right, !isNextLarge);

}

