int main() {
	int N;
	std::cin >> N;

	std::vector<int> a(N);
	for(int i = 0; i < N; i++) {
		std::cin >> a[i];
	}

	std::sort(a.begin(), a.end());

	const int centerIndex = (N - 1) / 2;
	int center = a[centerIndex];
	a.erase(a.begin() + centerIndex);

	std::deque<int> queue(a.begin(), a.end());
	if(std::abs(center - a.front()) > std::abs(center - a.back())) {
		std::reverse(queue.begin(), queue.end());
	}

	int left = 0;
	int right = center;
	long long answer = 0;
	while(!queue.empty()) {
		left = right;
		right = queue.back();
		queue.pop_back();
		answer += std::abs(left - right);
		if(queue.empty()) {
			break;
		}
		left = right;
		right = queue.front();
		queue.pop_front();
		answer += std::abs(left - right);
		if(queue.empty()) {
			break;
		}
	}

	std::cout << answer << std::endl;

	return 0;
}

