using ll = long long;

ll solve(vector<int> a){
	const int n = a.size();
	sort(a.begin(), a.end());
	const int m = n / 2, k = n - m;
	vector<int> lo(a.begin(), a.begin() + k);
	vector<int> hi(a.begin() + k, a.end());
	ll answer = 0;
	for(const int x : hi){ answer += x * 2; }
	if(k == m){ answer -= hi[0]; }
	for(const int x : lo){ answer -= x * 2; }
	if(k == m){
		answer += lo[k - 1];
	}else{
		answer += lo[k - 1] + lo[k - 2];
	}
	return answer;
}

