ll solve() {
    sort(a, a + N);

    ll ans = 0;
    if (N % 2 == 0) {
        // -2, -2, ..., -1, 1, 2, 2, ..., 2
        for (int i = 0; i < N / 2 - 1; i++) {
            ans += -2 * a[i] + 2 * a[N - i - 1];
        }
        ans += -a[N / 2 - 1] + a[N / 2];
    } else {
        ll ans1 = 0, ans2 = 0;
        // -2, -2, ..., -2, -1, -1, 2, 2, ..., 2
        for (int i = 0; i < N / 2; i++) {
            ans1 += -2 * a[i] + 2 * a[N - i - 1];
        }
