        // -2, -2, ..., -2, 1, 1, 2, 2, ..., 2
        for (int i = 0; i < N / 2; i++) {
            ans2 += -2 * a[i] + 2 * a[N - i - 1];
        }
        ans2 += a[N / 2] - a[N / 2 + 1];

        ans = max(ans1, ans2);
    }
    return ans;
}

