		scanf("%d", &a[i]);
	}
	QSort(a, 0, n-1, 1);
	ll ans = 0;
	int now;
	int sd = (n - 1) / 2;
	int su = n / 2;
	int d = 1;
	int flag;
	while (1) {
		if (su + d == n) {
			flag = 1;
			now = sd;
			break;
		}
		if (a[su + d] != a[su]) {
			flag = 1;
			now = sd;
			break;
		}
		if (a[sd - d] != a[sd]) {
			flag = 0;
			now = su;
			break;
		}
		d++;
	}
	d = 0;
	int next;
	int start = now;
	int cnt = 0;
	while (1)
	{
		if (flag) {
			next = n - 1 - d;
		}
		else {
			next = d;
		}
		if (next >= n || n < 0)break;
		if (next == start)break;
		ans += abs(a[now] - a[next]);
		if (cnt)d++;
		cnt = 1 - cnt;
		flag = 1 - flag;
		now = next;
		//PRINTL(ans);
	}
