#include <bits/stdc++.h>

long long fact(long long n) {
    long val = 1;
    for (long i = 1; i <= n; i++) {
        val *= i;
    }
    return val;
}

int main()
{
    long n = 0;
    long tmp = 0;
    std::cin >> n;
    std::vector<long> v;

    for (int i = 0; i < n; i++) {
        std::cin >> tmp;
        v.push_back(tmp);
    }

    std::vector<std::vector<long>> vs;
    vs.resize(fact(n));
    for (auto v : vs){
        v.resize(n);
    }
    std::sort(v.begin(),v.end());
    long ct = 0;
    do {
        for (auto k : v) {
            vs[ct].push_back(k);
        }
        ct++;
    }while(std::next_permutation(v.begin(), v.end()));

    long ans = 0;
    long t = 0;
    long prev = 0;
    for (auto x : vs) {
        prev = t = 0;
        for (auto i : x) {
            if (prev != 0) {
                t += std::abs(i-prev);
            }
            prev = i;
        }
        ans = std::max(ans, t);
    }

    std::cout << ans << std::endl;
    return 0;
}

