ll solve(int N, vi& a) {
    sort(ALL(a));

    int D = N-1;
    vll d(D); rep(i,D) d[i] = a[i+1] - a[i];
    vll e(D);
    for (int i=0,j=D-1,v=2; i<=j; ++i,--j,v+=2){
        e[i] = e[j] = v;
        // last
        if (i==j) e[i]--;
        else if (i+1==j){
            if (d[i] < d[j]) e[i]--;
            else e[j]--;
        }
    }
    ll ans = 0;
    rep(i,D) ans += d[i] * e[i];
    return ans;
}

