long long solve() {
  long long ans = 0, now = 0;
  if(n == 3)
    return max(2 * a[2] - a[0] - a[1],
               a[2] + a[1] - 2 * a[0]);
  ;
  if(n % 2 == 0) {
    for(int i = 0; i < n / 2; ++i) {
      ans += 2 * (a[n - 1 - i] - a[i]);
      if(i == n / 2 - 1) ans -= a[n - 1 - i] - a[i];
    }
  }
  else {
    for(int i = 0; i < n / 2 - 1; ++i)
      ans += 2 * a[n - 1 - i];
    for(int i = 0; i < n / 2; ++i) ans -= 2 * a[i];
    ans += a[n - 2 - n / 2] + a[n - n / 2 - 1];
    for(int i = 0; i < n / 2; ++i) now += 2 * a[n - 1 - i];
    for(int i = 0; i < n / 2 - 1; ++i) now -= 2 * a[i];
    now -= a[n / 2 - 1] + a[n / 2];
    ans = max(now, ans);
  }
  return ans;
}

