const int maxN = 1e5 + 10; 
int a[maxN];
int n;
vector<pii> w;
int main()
{
	scanf("%d",&n);
	for(int i=1;i<=n;i++)
	{
		scanf("%d",&a[i]);
	}
	sort(a+1,a+1+n);
	int pos = 0;

	int right = n;
	int left = 2;
	w.push_back(pii(pos,a[1]));
	int r,l;
	r = l = a[1];
	int len = 1;
	while(left < right)
	{
		if(abs(a[right] - r) + abs(a[right-1] - l) < abs(a[right] - l) + abs(a[right-1] - r))
		{
			l = a[right];
			w.push_back(pii(pos-len,a[right]));
			r = a[right - 1];
			w.push_back(pii(pos+len,a[right-1]));
		}
		else
		{
			r = a[right];
			w.push_back(pii(pos+len,a[right]));
			l = a[right - 1];
			w.push_back(pii(pos-len,a[right-1]));
		}
		right -= 2;
		len += 1;
		if(left >= right) break;
		if(abs(a[left] - r) + abs(a[left+1] - l) < abs(a[left] - l) + abs(a[left+1] - r))
		{
			l = a[left];
			w.push_back(pii(pos-len,a[left]));
			r = a[left + 1];
			w.push_back(pii(pos+len,a[left+1]));
		}
		else
		{
			r = a[left];
			w.push_back(pii(pos+len,a[left]));
			l = a[left + 1];
			w.push_back(pii(pos-len,a[left+1]));
		}
		left += 2;
		len += 1;
	}
	if(left == right)
	{
		if(abs(a[left] - l) > abs(a[left] - r))
		{
			l = a[left];
			w.push_back(pii(pos-len,a[left]));
		}
		else
		{
			r = a[left];
			w.push_back(pii(pos+len,a[left]));
		}
	}
	sort(w.begin(),w.end());
	ll ans = 0;
	for(int i=1;i<w.size();i++)
	{
		ans += (ll)abs(w[i].second - w[i-1].second);
	}
	printf("%d\n",ans);
    return 0;
}

