long long go(int X, int Y, VI V) {
	int N = V.size();
	int DC = N-1;
	long long t = 0;
	for (int i = 0; i < X; ++i) {
		if (DC >= 2 && DC-2 >= X-i-1) {
			t -= 2 * V[i];
			DC -= 2;
		} else {
			t -= V[i];
			DC -= 1;
		}
	}
	DC = N - 1;
	reverse(V.begin(), V.end());
	for (int i = 0; i < Y; ++i) {
		if (DC >= 2 && DC-2 >= Y-i-1) {
			t += 2 * V[i];
			DC -= 2;
		} else {
			t += V[i];
			DC -= 1;
		}
	}
	return t;
}

