vec<int> getCoef(int n, int sign) {
   vec<int> res(n);
   rep (i, n) {
      int c = (i == 0 || i == n-1) ? 1 : 2;
      c *= (i & 1) ? sign : -sign;
      res[i] = c;
   }
   return res;
}

