  bool bl=true;
  while(a.size()){
    if(bl){
      l.push_back(a[a.size()-1]);
      a.erase(a.end()-1);
      if(a.size()==0) break;
      r.push_back(a[a.size()-1]);
      a.erase(a.end()-1);
    }else{
      l.push_back(a[0]);
      a.erase(a.begin());
      if(a.size()==0) break;
      r.push_back(a[0]);
      a.erase(a.begin());
    }
    bl = !bl;
  }

  LL ret=0;
  REP(i,l.size()-1){
    ret+=abs(l[i]-l[i+1]);
  }
  if(r.size()>0){
    ret+=abs(l[0]-r[0]);
    REP(i,r.size()-1){
      ret+=abs(r[i]-r[i+1]);
    }
  }
  cout<<ret<<endl;
