    int rpos = n - 1;
    while (lpos <= rpos) {
        if (lpos <= rpos) {
            ans += abs(rnum - a[rpos]);
            rnum = a[rpos];
            rpos--;
        }
        if (lpos <= rpos) {
            ans += abs(rnum - a[lpos]);
            rnum = a[lpos];
            lpos++;
        }
        if (lpos <= rpos) {
            ans += abs(lnum - a[rpos]);
            lnum = a[rpos];
            rpos--;
        }
        if (lpos <= rpos) {
            ans += abs(lnum - a[lpos]);
            lnum = a[lpos];
            lpos++;
        }
    }
    return ans;
}

long long solve2()
{
    sort(a, a + n);
    long long ans = a[n - 1] - a[0];
    pair<int, int> lnum, rnum;
    lnum = make_pair(a[0], 1);
    rnum = make_pair(a[n - 1], 0);
    int lpos = 1;
    int rpos = n - 2;
    while (lpos <= rpos) {
        if (lpos <= rpos) {
            int num = a[lpos];
            lpos++;

            int ltmp = -1;
            int rtmp = -1;

            if (lnum.second == 0)
                ltmp = abs(lnum.first - num);
            if (rnum.second == 0)
                rtmp = abs(rnum.first - num);

            if (ltmp > rtmp) {
                ans += ltmp;
                lnum = make_pair(num, 1);
                //printf("%d to left\n", num);
            } else {
                ans += rtmp;
                rnum = make_pair(num, 1);
                //printf("%d to right\n", num);
            }
        }
        if (lpos <= rpos) {
            int num = a[rpos];
            rpos--;

            int ltmp = -1;
            int rtmp = -1;

            if (lnum.second == 1)
                ltmp = abs(lnum.first - num);
            if (rnum.second == 1)
                rtmp = abs(rnum.first - num);

            if (ltmp > rtmp) {
                ans += ltmp;
                lnum = make_pair(num, 0);
                //printf("%d to left\n", num);
            } else {
                ans += rtmp;
                rnum = make_pair(num, 0);
                //printf("%d to right\n", num);
            }
        }
    }
    return ans;
}


