void solve() {
    i64 N = RD();
    auto A = RD_VEC(N);

    ALL(sort, A);

    i64 ans = 0;
    i64 head = A[0];
    i64 tail = A[0];
    i64 l = 1;
    i64 r = N-1;
    while(l <= r) {
        array<i64,4> ds {
            abs(A[l] - head),
            abs(A[l] - tail),
            abs(A[r] - head),
            abs(A[r] - tail),
        };
        i64 i = distance(begin(ds), ALL(max_element,ds));
        if(i == 0) {
            head = A[l];
            ++l;
        }
        else if(i == 1) {
            tail = A[l];
            ++l;
        }
        else if(i == 2) {
            head = A[r];
            --r;
        }
        else if(i == 3) {
            tail = A[r];
            --r;
        }
        else {
            ASSERT(false);
        }
        ans += ds[i];
    }

    PRINTLN(ans);
}

