    subl = abs(a.front() -  a.back()) + abs(a.front() - a[a.size() - 2]);
    subr = abs(a.back() -  a.front()) + abs(a.back() - a[1]);
    if (subl <= subr){
        res += subr;
        tl = a[0]; tr = a[1];
        a.erase(a.begin(), a.begin() + 2);
        a.pop_back();
    }
    else{
        res += subl;
        tl = a[a.size() - 1]; tr = a[a.size() - 2];
        a.pop_back();
        a.pop_back();
        a.erase(a.begin());
    }
    while(a.size() > 0){
        x = abs(tl - a.front()); y = abs(tl - a.back());
        z = abs(tr - a.front()); w = abs(tr - a.back());
        if (max(x, y) < max(z, w)){
            res += z <= w ? w : z;
            if (z <= w){
                tr = a.back();
                a.pop_back();
            }
            else{
                tr = a.front();
                a.erase(a.begin());
            }

        } else{
            res += x <= y ? y : x;
            if (x <= y){
                tl = a.back();
                a.pop_back();
            }
            else{
                tl = a.front();
                a.erase(a.begin());
            }
        }
    }

    cout << res << endl;
    return 0;
}

