long long solve() {
  long long ans = 0, cnt = 0, now, nl, nr;
  nl = a[0];
  nr = a[n - 1];
  ans += nr - nl;
  for(int i = 2; i < n; ++i) {
    long long l, r, now;
    if(i % 2 == 1)
      now = a[n - 1 - i / 2];
    else
      now = a[i / 2];
    l = max(nl - now, now - nl);
    r = max(nr - now, now - nr);
    if(l > r) {
      ans += l;
      nl = now;
    }
    else if(l < r) {
      ans += r;
      nr = now;
    }
    else {
      ans += l;
      if(i % 2 == 1) {
        if(nr > nl)
          nl = now;
        else
          nr = now;
      }
      if(i % 2 == 0) {
        if(nr > nl)
          nr = now;
        else
          nl = now;
      }
    }
  }
  return ans;
}

