    for (int order = 0; order < 2; ++order) {
        int64_t tmp = 0;
        int A = a[orders[order][0]], B = a[orders[order][0]];
        for (int i = 1; i < n; ++i) {
            int next = a[orders[order][i]];
            if (abs(A - next) > abs(B - next)) {
                tmp += abs(A - next);
                A = next;
            } else {
                tmp += abs(B - next);
                B = next;
            }
        }
        result = max(result, tmp);
    }

    cout << result << endl;
