const ll MOD = 1000000007;

ll solve(vector<ll>& a){
    int lv = a[0], rv = a[0];
    int l = 1, r = a.size() - 1;
    int side = 0;
    ll ret = 0;
    while(l <= r){
        if(side == 0){
            ret += abs(lv - a[r]);
            lv = a[r];
            r--;
            if(l <= r){
                ret += abs(lv - a[l]);
                lv = a[l];
                l++;
            }
        }else{
            ret += abs(rv - a[r]);
            rv = a[r];
            r--;
            if(l <= r){
                ret += abs(rv - a[l]);
                rv = a[l];
                l++;
            }
        }
        side = side ^ 1;
    }
    return ret;
}

