    if(n%2==1)
    {
        tot-=1LL*min(a[m]-a[m-1],a[m+1]-a[m]);
    }
    if(n%2==0)
    {
        for(i=1;i<=n;i++)
            v[i]=max(a[m]-a[i],a[i]-a[m]);
        sort(v+1,v+n+1);
        tot-=(v[1]+v[2]);
    }
    cout<<tot;
    return 0;
}

