using namespace std;

int N;

int solve1(vector<int> A) {
    vector<int> ans(N);
    ans[N / 2] = A[0];
    int l = 1;
    int r = N - 1;
    int center = N / 2;
    int cur = 1;
    while (center - cur >= 0) {
        if (center + cur > N - 1) {
            ans[center - cur] = cur % 2 == 1 ? A[r] : A[l];
            break;
        }
        if (cur % 2 == 1) {
            ans[center - cur] = A[r];
            ans[center + cur] = A[r - 1];
            r -= 2;
        } else {
            ans[center - cur] = A[l];
            ans[center + cur] = A[l + 1];
            l -= 2;
        }
        cur++;
    }

    int res = 0;
    REP(i, N - 1) {
        res += abs(ans[i + 1] - ans[i]);
    }

    return res;
}

int solve2(vector<int> A) {
    vector<int> ans(N);
    ans[N / 2] = A[N - 1];
    int l = 0;
    int r = N - 2;
    int center = N / 2;
    int cur = 1;
    while (center - cur >= 0) {
        if (center + cur > N - 1) {
            ans[center - cur] = cur % 2 == 0 ? A[r] : A[l];
            break;
        }
        if (cur % 2 == 0) {
            ans[center - cur] = A[r];
            ans[center + cur] = A[r - 1];
            r -= 2;
        } else {
            ans[center - cur] = A[l];
            ans[center + cur] = A[l + 1];
            l -= 2;
        }
        cur++;
    }

    int res = 0;
    REP(i, N - 1) {
        res += abs(ans[i + 1] - ans[i]);
    }

    return res;
}

signed main() {
