void Solve() {
	int n; cin >> n;
	vi a(n, 0);
	for(int i = 0; i < n; i++) cin >> a[i];
	sort(a.begin(), a.end());

	ll ans = 0;
	if(n % 2 == 0) {
		for(int i = 0; i < n / 2 - 1; i++) ans -= 2 * a[i];
		ans -= a[n / 2 - 1];
		ans += a[n/2];
		for(int i = n / 2 + 1; i < n; i++) ans += 2 * a[i];
	} else {
		ll ans1 = 0;
		for(int i = 0; i < n / 2 - 1; i++) ans1 -= 2 * a[i];
		ans1 -= a[n/2-1] + a[n/2];
