LL solve(vector<int> values)
{
    int n = values.size();
    sort(values.begin() , values.end());
    vector<int> fin(values.size());
    int idx = (n - 1) / 2;
    int cnt = (n + 1) / 2;
    int from = 0;
    while(cnt--)
    {
        fin[from] = values[idx];
        idx--;
        from += 2;
    }
    cnt = n / 2;
    idx = n - 1;
    from = 1;
    while(cnt--)
    {
        fin[from] = values[idx];
        idx--;
        from += 2;
    }
    if(n > 1 && n % 2)
    {
        swap(fin[2] , fin[n - 1]);
    }
    LL ans = 0;
    for(int i = 0; i < fin.size() - 1; i++)
        ans += abs(fin[i] - fin[i + 1]);
    return ans;
}
