using namespace std;
const int maxn = 100100;
int arr[maxn];
long long solve(int lst, int l, int r){
  long long ans = 0;
  int pl = lst, pr = lst;
  while(l <= r){
    int pt0 = abs(pl - arr[l]);
    int pt1 = abs(pl - arr[r]);
    int pt2 = abs(pr - arr[l]);
    int pt3 = abs(pr - arr[r]);
    int mx = max({pt0, pt1, pt2, pt3});
    ans += mx;
    if(mx == pt0){
      pl = arr[l++];
    } else if(mx == pt1){
      pl = arr[r--];
    } else if(mx == pt2){
      pr = arr[l++];
    } else {
      pr = arr[r--];
    }
  }
  return ans;
}
int main(){
  int n;
  cin >> n;
  for(int e = 0;  e < n; e++) cin >> arr[e];
  sort(arr, arr + n);
  long long ans = 0;
  ans = max(ans, solve(arr[0], 1, n - 1));
  ans = max(ans, solve(arr[n - 1], 0, n - 2));
  cout << ans << endl;
  return 0;
}

