ll solve(const vector<ll>& A, ll sign) {
  const int N = A.size();
  vector<ll> B(N, 2);
  B[0] = B[N - 1] = 1;
  for (int i = 0; i < N; i++) B[i] *= sign, sign = -sign;
  sort(B.begin(), B.end());
  ll res = 0;
  for (int i = 0; i < N; i++) res += B[i] * A[i];
  return res;
}

int main() {
