	ll s = 1,e=n-1;
	bool toggle=1;
	q1.pb(b[0]);
	while(s<=e){
		if(toggle){
			q1.pb(b[e--]);
			if(s>e) break;
			q1.pf(b[e--]);
		}else{
			q1.pb(b[s++]);
			if(s>e) break;
			q1.pf(b[s++]);
		}
		toggle = !toggle;
	}

	s = 0,e=n-2;
	q2.pb(b[n-1]);
	toggle=1; 
	while(s<=e){
		if(toggle){
			q2.pb(b[s++]);
			if(s>e) break;
			q2.pf(b[s++]);
		}else{
			q2.pb(b[e--]);
			if(s>e) break;
			q2.pf(b[e--]);
		}
		toggle = !toggle;
	}
	vector<ll> ans1,ans2;
	deque <ll> :: iterator it; 
    for (it = q1.begin(); it != q1.end(); ++it) ans1.pb(*it);
    for (it = q2.begin(); it != q2.end(); ++it) ans2.pb(*it);

    ll a1 = 0,a2=0;
	For(i,1,n){a1 += abs(ans1[i]-ans1[i-1]);}
	For(i,1,n){a2 += abs(ans2[i]-ans2[i-1]);}

	cout<<max(a1,a2)<<endl;

}

