#define RALL(x) (x).rbegin(), (x).rend()


long long compute(std::deque<int> deque)
{
  long long s = 0;

  int l, r, dl, dr;

  l = r = deque.front(); deque.pop_front();

  std::deque<int> a;

  a.push_back(l);

  while (! deque.empty()) {
    int m = deque.front(), p = deque.back(), d, dp = 0, ip = 0;

    if ((d = std::abs(l - m)) > dp) {
      dp = d;
      ip = 0;
    }
    if ((d = std::abs(l - p)) > dp) {
      dp = d;
      ip = 1;
    }
    if ((d = std::abs(r - m)) > dp) {
      dp = d;
      ip = 2;
    }
    if ((d = std::abs(r - p)) > dp) {
      dp = d;
      ip = 3;
    }

    s += dp;

    if (ip % 2 == 0) {
      deque.pop_front();

      if (ip < 2) {
        l = m;
        a.push_front(m);
      }
      else {
        r = m;
        a.push_back(m);
      }
    }
    else {
      deque.pop_back();

      if (ip < 2) {
        l = p;
        a.push_front(p);
      }
      else {
        r = p;
        a.push_back(p);
      }
    }
  }

  return s;
}


