using namespace std;
typedef long long ll;

void create_set(int k){
    int out[k+1][k];

    int cnt = 1;

    REP(i, k){
        REP(j, k){
            if (j >= i){
                out[i][j] = cnt;
                cnt++;
            }

        }
    }

    cnt = 1;

    REP(j, k){
        RREP(i, 1, k+1){
            if (i >= j+1){
                out[i][j] = cnt;
                cnt++;
            }
        }
    }

    REP(i, k+1){
        cout << k << " ";
        REP(j, k){
            cout << out[i][j] << " ";
        }
        cout << endl;
    }
}

