using namespace std;
template<class T, class T2> inline int chkmax(T &x, const T2 &y) { return x < y ? x = y, 1 : 0; }
template<class T, class T2> inline int chkmin(T &x, const T2 &y) { return x > y ? x = y, 1 : 0; }
const int MAXN = (1 << 20);

int n;
int a[MAXN];

void read()
{
	cin >> n;
	for(int i = 0; i < n; i++)
		cin >> a[i];
}

int p[MAXN];

void solve()
{
	if(n == 2)
	{
		cout << abs(a[0] - a[1]) << endl;
		return;
	}

	sort(a, a + n);

	for(int i = n / 2 - 2, v = 1; i >= 0; i -= 2, v += 2) p[i] = v;
	for(int i = n / 2 + 2, v = 2; i < n; i += 2, v += 2) p[i] = v;
	for(int i = n / 2 - 1, v = n - 1; i >= 0; i -= 2, v -= 2) p[i] = v;
	for(int i = n / 2 + 1, v = n - 2; i < n; i += 2, v -= 2) p[i] = v;

	int64_t answer = 0;
	for(int i = 0; i + 1< n; i++)
		answer += abs(a[p[i]] - a[p[(i + 1) % n]]);

	for(int tms = 0; tms < 20; tms++)
	{
		random_shuffle(a, a + n);

		int64_t curr = 0;
		for(int i = 0; i + 1< n; i++)
			curr += abs(a[p[i]] - a[p[(i + 1) % n]]);

		chkmax(answer, curr);
	}

	cout << answer << endl;
}

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	read();
	solve();
	return 0;
}

