			V.push_back(que.front());
			que.pop_front();
		}else{
			V.push_back(que2.front());
			que2.pop_front();
		}
		for(int i=0;i<N-1;i++){
			ans+=abs(V[i]-V[i+1]);
		}
	}else{
		long long a=0;
		for(int i=0;i<N/2;i++){
			a+=A[i];
		}
		long long b=0;
		for(int i=N/2;i<N;i++){
			b+=A[i];
		}
		ans+=2*abs(a-b);
		ans-=abs(A[N/2]-A[N/2-1]);
	}
	cout<<ans<<endl;
	return 0;
}

