void exec(){
  int n, tmp;
  VI a;
  cin >> n;
  for (int i = 0; i < n; i++){
    scanf("%d", &tmp);
    a.push_back(tmp);
  }

  sort(a.begin(), a.end());
  int min_idx = 1, max_idx = n-2;
  bool is_min = true;

  deque<int> d;
  d.push_front(a[0]);
  d.push_back(a[n-1]);
  n -= 2;

  while (n > 0){
    int efront = d.front();
    int eback = d.back();
    if (is_min){
      int e = a[min_idx];

      int efrontdiff = abs(efront - e);
      int ebackdiff = abs(eback - e);

      if (efrontdiff == ebackdiff){
        if (efront > eback){

          d.push_front(e);
        }
        else{
          d.push_back(e);

        }
      }
      else if (efrontdiff > ebackdiff){
        d.push_front(e);
      }
      else {
        d.push_back(e);
      }

      min_idx++;
    }
    else {
      int e = a[max_idx];

      int efrontdiff = abs(efront - e);
      int ebackdiff = abs(eback - e);

      if (efrontdiff == ebackdiff){
        if (efront < eback){
          d.push_front(e);
        }
        else{
          d.push_back(e);
        }
      }
      else if (efrontdiff > ebackdiff){
        d.push_front(e);
      }
      else {
        d.push_back(e);
      }

      max_idx--;
    }
    n--;
    is_min = !is_min;
  }

  ll ans = 0;
  for(auto itr = d.begin(); itr != d.end(); ++itr) {
    if (false){
      cout << (*itr) << endl;
    }
    if (itr != d.begin()){
      int diff = abs(*itr - *(itr - 1));
      ans += diff;
    }
  }

  cout << ans << endl;

}

