namespace adaptor = boost::adaptors;

void Main()
{
	int N;
	in::read(N);
	auto vec = in::read_vector<int>(N);
	boost::sort(vec);
	auto ite = vec.begin();
	auto rite = vec.rbegin();
	auto iterate = [&](auto it, auto rit)
	{
		std::vector<int> vec0(N / 2), vec1(N - N / 2);
		for (int i : boost::irange(0, N / 2))
		{
			vec0[i] = i % 2 == 0 ? rit[i] : it[i];
		}
		for (int i : boost::irange(0, N - N / 2))
		{
			vec1[i] = i % 2 != 0 ? rit[i] : it[i];
		}
		int sum = std::abs(vec0[0] - vec1[0]);
		int prev = vec0[0];
		for (int i : boost::irange(1, N / 2))
		{
			sum += std::abs(prev - vec0[i]);
			prev = vec0[i];
		}
		prev = vec1[0];
		for (int i : boost::irange(1, N - N / 2))
		{
			sum += std::abs(prev - vec1[i]);
			prev = vec1[i];
		}
		return sum;
	};
	out::write_line(std::max(iterate(ite, rite), iterate(rite, ite)));
}

int main()
{
	std::cin.tie(nullptr);
	std::cin.sync_with_stdio(false);
	std::cout << std::fixed << std::setprecision(15);
	Main();
}

