void solve(){
	ll n; cin >> n;
	ll a[n]; rep(i, n) cin >> a[i];
	sort(a, a + n);
	if(n % 2 == 0){
		ll k = n/2;
		ll hiku = 0;
		rep(i, k-1){ hiku += 2 * a[i]; }
		hiku += a[k-1];
