	deque<ll> a;
	for (int i = 0; i < n; i++) {
		ll c; cin >> c;
		a.push_back(c);
	}
	sort(a.begin(), a.end());
	deque<ll> r;
	r.push_back(a.front());
	a.pop_front();
	bool flag = false;
	while (!a.empty()) {
		if (flag) {
			ll c = a.front();
			a.pop_front();
			if (abs(r.front() - c) >= abs(r.back() - c)) {
				r.push_front(c);
			}
			else {
				r.push_back(c);
			}
		}
		else {
			ll c = a.back();
			a.pop_back();
			if (abs(r.front() - c) >= abs(r.back() - c)) {
				r.push_front(c);
			}
			else {
				r.push_back(c);
			}
		}
		flag = !flag;
	}
	ll ans = 0;
	for (int i = 0; i < n - 1; i++) {
		ans += abs(r[i] - r[i + 1]);
	}
	cout << ans << endl;
	return 0;
}

