using namespace std;

#define repeat(i, x) for (int64_t i = 0; (i) < (int64_t)(x); (i)++)

int64_t calcCost(vector<int>& a) {
    int64_t cost = 0;
    repeat (i, a.size() - 1) {
        cost += abs(a[i + 1] - a[i]);
    }
    return cost;
}

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int n;
    cin >> n;

    vector<int> a(n);
    repeat (i, n) {
        cin >> a[i];
    }

    sort(a.begin(), a.end());

    if (n == 2) {
        cout << abs(a[0] - a[1]) << endl;
        return 0;
    }

    if (n == 3) {
        cout << max({
                        abs(a[0] - a[1]) + abs(a[1] - a[2]),
                        abs(a[0] - a[2]) + abs(a[1] - a[0]),
                        abs(a[1] - a[2]) + abs(a[0] - a[2])}) << endl;
        return 0;
    }

    int64_t ans = 0;

    if (n % 2 == 0) {
        {
            vector<int> seq;
            seq.push_back(a[n / 2 - 1]);
            int idxl = 0, idxr = n - 1;
            while (idxl < n / 2 - 1) {
                seq.push_back(a[idxr--]);
                seq.push_back(a[idxl++]);
            }
            seq.push_back(a[n / 2]);

            ans = max(ans, calcCost(seq));
        }
    } else {
        {
            vector<int> seq;
            seq.push_back(a[n / 2 - 1]);
            int idxl = 0, idxr = n - 1;
            while (idxl < n / 2 - 1) {
                seq.push_back(a[idxr--]);
                seq.push_back(a[idxl++]);
            }
            seq.push_back(a[idxr--]);
            seq.push_back(a[idxr--]);

            ans = max(ans, calcCost(seq));
        }
        {
            vector<int> seq;
            seq.push_back(a[n / 2 + 1]);
            int idxl = 0, idxr = n - 1;
            while (idxr > n / 2 + 1) {
                seq.push_back(a[idxl++]);
                seq.push_back(a[idxr--]);
            }
            seq.push_back(a[idxl++]);
            seq.push_back(a[idxl++]);

            ans = max(ans, calcCost(seq));
        }
    }

    cout << ans << endl;

    return 0;
}

