			B[2 * i+2] = A[i];
		}
		rep(i, 0, n) {
			B[2 * i + 1] = A[n+i+1];
		}
		//pattern 2
		C[0] = A[n];
		C[N - 1] = A[n + 1];
		rep(i, 0, n - 1) {
			C[2 * i + 2] = A[n+ i + 2];
		}
		rep(i, 0, n) {
			C[2 * i + 1] = A[i];
		}

	}
	auto calc=[&](vll B) {
		ll res = 0;
		rep(i, 0, N-1) {
			res += abs(B[i + 1] - B[i]);
		}
		return res;
	};
	ll b = calc(B);
	ll c = calc(C);
	cout << max(b, c);
	return 0;
}

