ll solve1(vector<ll> a, int n) {
  deque<ll> dq;
  dq.push_back(a[0]);
  int s=1;
  int e=n-1;
  for(int k=0; k<(n-1)/2; k++) {
    if(k%2==0) {
      ll f = dq.front();
      ll b = dq.back();
      ll t1 = abs(a[e]-f)+abs(a[e-1]-b);
      ll t2 = abs(a[e]-b)+abs(a[e-1]-f);
      if(t1<t2) {
        dq.push_back(a[e]);
        dq.push_front(a[e-1]);
      } else {
        dq.push_front(a[e]);
        dq.push_back(a[e-1]);
      }
      e-=2;
    } else {
      ll f = dq.front();
      ll b = dq.back();
      ll t1 = abs(a[s]-f)+abs(a[s+1]-b);
      ll t2 = abs(a[s]-b)+abs(a[s+1]-f);
      if(t1<t2) {
        dq.push_back(a[s]);
        dq.push_front(a[s+1]);
      } else {
        dq.push_front(a[s]);
        dq.push_back(a[s+1]);
      }
      s+=2;
    }
  }
  if(n%2==0) {
    if(abs(dq.front()-a[s])>abs(dq.back()-a[s])) {
      dq.push_front(a[s]);
    } else {
      dq.push_back(a[s]);
    }
  }
  // for(auto x : dq) cout << x << " ";
  // cout << endl;
  ll prev = dq.front();
  dq.pop_front();
  ll ans=0;
  for(auto x : dq) {
    ans+=abs(x-prev);
    prev=x;
  }
  return ans;
}

