ll solve1(int n, vi a) {
    int h = n >> 1;
    int h2 = n - h;
    sort(RALL(a));
    vi b;
    vi tmp;
    for (int i = 0; i < n; ++i) if (i < h) b.push_back(a[i]);
        else tmp.push_back(a[i]);
    a = tmp;
    vi res(n);

    res[0] = a[0];
    if (a.size() >= 2) res[n - 1] = a[1];
    int i = 0;
    int j = 2;
    for (int k = 1; k < n; ++k) {
        if (k & 1) res[k] = b[i++];
        else res[k] = a[j++];
    }
    ll dif = 0;
    for (int i = 1; i < n; ++i) dif += abs(res[i] - res[i - 1]);
    watch(res);
    return dif;
}

