			next = fir;
		}
		else
		{
			s.erase((--s.end()));
			next = sec;
		}
		if (abs(next - le) > abs(next - ri))
		{
			res += abs(next - le);
			le = next;
		}
		else
		{
			res += abs(next - ri);
			ri = next;
		}
	}
	cout << res;
	return 0;
}

