    deque<int> A(N);

    for (auto& e: A) cin >> e;

    sort(A.begin(), A.end());

    int first = A.front();
    int last = A.front();
    A.pop_front();

    long long int ans = 0;
    while (!A.empty()) {
        int dff = abs(A.front() - first);
        int dbf = abs(A.back() - first);
        int dfl = abs(A.front() - last);
        int dbl = abs(A.back() - last);

        int tf = max(dff, dbf);
        int tl = max(dfl, dbl);
        if (tf > tl) {
            if (dff > dbf) {
                ans += dff;
                first = A.front();
                A.pop_front();
            } else {
                ans += dbf;
                first = A.back();
                A.pop_back();
            }
        } else {
            if (dfl > dbl) {
                ans += dfl;
                last = A.front();
                A.pop_front();
            } else {
                ans += dbl;
                last = A.back();
                A.pop_back();
            }

        }
    }

    cout << ans << endl;


