const int MAXN = 120000;

int n;
int a[MAXN];

ll solve() {
	if (n == 1)
		return 0;
	sort(a, a + n);
	if (n % 2 == 0) {
		ll ans = 0;
		int k = n / 2;
		for (int i = 0; i < k - 1; ++i)
			ans -= 2 * a[i];
		ans -= a[k - 1];
		ans += a[k];
		for (int i = k + 1; i < n; ++i)
			ans += 2 * a[i];
		return ans;
	}
	else {
		ll ans = 0;
		int k = n / 2 + 1;
		for (int i = 0; i < k - 2; ++i)
			ans -= 2 * a[i];
		ans -= a[k - 1];
		ans -= a[k - 2];
		for (int i = k; i < n; ++i)
			ans += 2 * a[i];
		return ans;
	}
}

