std::vector<int> getCoef(int n, int sign) {
	std::vector<int> res(n);
	REP(i, n) {
		int c = (i == 0 || i == n - 1) ? 1 : 2;
		c *= (i & 1) ? sign : -sign;
		res[i] = c;
	}
	return res;
}

signed main() {
	INIT;

	VAR(int, n);
	VEC(int, a, n);

	std::sort(ALL(a));

	int ans = 0;
	for (int sign = -1; sign <= 1; sign += 2) {
		auto c(getCoef(n, sign));
		std::sort(ALL(c));

		int sum = 0;
		REP(i, n) sum += a[i] * c[i];

		CHMAX(ans, sum);
	}

	OUT(ans)BR;
	return 0;
}

