lli count(int n)
{
    int l=0, r=n-1;
    lli res = 0;
    int pre = a[(n-1)/2];
    while(l!=r)
    {
        res += abs(a[r]-pre), pre = a[r], --r;
        if( l==r ) break;
        res += abs(a[l]-pre), pre = a[l], ++l;
    }
    return res;
}

