void solve(long long n, vector<long long> a){
	sort(a.begin(),a.end());
	LL ans1=0;
	LL l=a[0],r=a[0];
	for(int i=2; i<=n; ++i) {
		LL now;
		if (i%2==0) {
			now=a[n-i/2];
		} else {
			now=a[i/2];
		}
		if (abs(now-l)>abs(now-r)) {
			ans1+=abs(now-l);
			l=now;
		} else {
			ans1+=abs(now-r);
			r=now;
		}
	}
	LL ans2=0;
	l=a[n-1];
	r=a[n-1];
	for(int i=2; i<=n; ++i) {
		LL now;
		if (i%2==0) {
			now=a[i/2-1];
		} else {
			now=a[n-i/2-1];
		}
		if (abs(now-l)>abs(now-r)) {
			ans2+=abs(now-l);
			l=now;
		} else {
			ans2+=abs(now-r);
			r=now;
		}
	}
	cout<<max(ans1,ans2)<<endl;
}

