ll comb(ll a, ll b, ll mod) {
	ll mul = 1;
	ll div = 1;
	rep(i, b) {
		mul *= (a - (ll)i);
		mul %= mod;
		div *= ((ll)i + 1);
		div %= mod;
	}

	mul *= mod_pow(div, mod - 2,mod);
	return mul%mod;
}


