	int m = n / 2;
	vector<long long> a(n), b(n - m), c(m);
	for(int i = 0; i < n; i++){
		cin >> a[i];
	}
	if(n == 2){
		cout << abs(a[0] - a[1]) << endl;
		return 0;
	}
	sort(a.begin(), a.end());
	for(int i = 0; i < n - m; i++){
		b[i] = a[i];
	}
	for(int i = n - m; i < n; i++){
		c[i - n + m] = a[i];
	}
	sort(b.begin(), b.end(), greater<long long>());
	sort(c.begin(), c.end(), greater<long long>());
	for(int i = 0; i < n; i++){
		if(i % 2){
			a[i] = c[i / 2];
		}else{
			a[i] = b[i / 2];
		}
	}
	if(n == 3){
		swap(a[1], a[n - 1]);
	}else if(n % 2 == 1){
		swap(a[2], a[n - 1]);
	}
	for(int i = 1; i < n; i++){
		ans += abs(a[i] - a[i - 1]);
	}
