Int N;
vector<Int> A;

void solve(){
	if(N==2){
		fout<<abs(A[0]-A[1])<<endl;
		return;
	}
	Int ans = 0;
	sort(ALL(A));
	if(N%2==0){
		vector<Int> B(A.begin(),A.begin()+N/2);
		vector<Int> C(A.begin()+N/2,A.begin()+N);

		Int Bsum = accumulate(ALL(B),0ll);
		Int Csum = accumulate(ALL(C),0ll);
		Int s = 2*(Csum - Bsum);
		s+=B.back();s-=C.front();
		ans = max(ans,s);
	}else{
		{
			vector<Int> B(A.begin(),A.begin()+N/2+1);
			vector<Int> C(A.begin()+N/2+1,A.begin()+N);
			Int Bsum = accumulate(ALL(B),0ll);
			Int Csum = accumulate(ALL(C),0ll);
			Int s = 2*(Csum - Bsum);
			s+=B[B.size()-1];s+=B[B.size()-2];
			ans = max(ans,s);
		}
		{
			vector<Int> B(A.begin(),A.begin()+N/2);
			vector<Int> C(A.begin()+N/2,A.begin()+N);
			Int Bsum = accumulate(ALL(B),0ll);
			Int Csum = accumulate(ALL(C),0ll);
			Int s = 2*(Csum - Bsum);
			s-=C[0];s-=C[1];
			ans = max(ans,s);
		}
	}
	fout<<ans<<endl;
}

