    }
    for(int i=1;i<n/2;i++){
        sum1+=abs(array[n-i]-array[i-1])+abs(array[n-i]-array[i]);
        sum2+=abs(array[n-i]-array[i-1])+abs(array[n-i-1]-array[i-1]);
    }

