#include "bits/stdc++.h"
using namespace std;

long long solve(deque <int> v) {
	int last = v.front();
	int take = 0;
	int first = last;
	long long ans = 0;
	while(v.size() > 1) {
		if(take == 0) {
			ans += abs(v.front() - last);
			last = v.front();
			v.pop_front();
		} else {
			ans += abs(v.back() - last);
			last = v.back();
			v.pop_back();
		}
		take ^= 1;
	}
	ans += abs(first - v.back());
	return ans;
}

int main(int argc, char const *argv[])
{
