		scanf("%d", &x);
		v.push_back(x);
	}
	sort(v.begin(), v.end());
	long long ans = solve(v);
	reverse(v.begin(), v.end());
	ans = max(ans, solve(v));
	printf("%lld\n", ans);
	return 0;
}

