long long come_and_go(int *a, int n) {

    long long ans = 0;
    int c = n/2;

    for (int i = 0; i < n; i++) {
        if (i != c) ans += (long long)abs(a[i] - a[c]);
    }
    ans *= 2ll;

    if (n & 1) {
        ans -= abs(a[c-1] - a[c]);
    } else {
        ans -= min(abs(a[c-1] - a[c]), abs(a[c+1] - a[c]))
    }

    return ans;
}

