ll calc_sum(bool b){
    int fi,bi;
    ll res;

    if(b){
        res += a[n-1]+a[n-2]-2*a[0];
        fi = 1;
        bi = n-1;
    }else{
        res += 2*a[n-1]-(a[0]+a[1]);
        fi = 0;
        bi = n-2;
    }
    for(int i = 0;i < (n-3)/2;i ++){
        res += a[bi]+a[bi-1] - (a[fi]+a[fi+1]);
        if(i%2) fi += 2;
        else bi -= 2;
    }
    if(n%2==0) res += a[bi] - a[fi];
    return res;
}

