using namespace std;
template<class t, class u> bool chmax(t &a, u b){if(a<b){a=b;return true;}return false;}
template<class t, class u> bool chmin(t &a, u b){if(a>b){a=b;return true;}return false;}

LL modpow(LL x, LL b){
	LL res = 1;
	while(b){
		if(b&1)res = res * x % MOD;
		x = x * x % MOD;
		b>>=1;
	}
	return res;
}

LL modinv(LL x){
	return modpow(x, MOD-2);
}

int main(){
	int n;
	cin >> n;
	vector<LL> line(n);
	foreach(i, line)cin>>i;
	sort(ALL(line));
	auto func = [&](LL e){
		multiset<LL> s;
		foreach(i, line)s.insert(i);
		LL bnum = e;
		s.erase(s.find(e));
		LL res = 0;
		while(s.size()){
			if(*s.rbegin() - bnum > bnum - *s.begin()){
				res += *s.rbegin() - bnum;
				bnum = *s.rbegin();
				s.erase(s.find(bnum));
			}else{
				res += bnum - *s.begin();
				bnum = *s.begin();
				s.erase(s.find(bnum));
			}
		}
		return res;
	};

	cout << max({func(line[n/2]), func(line[n/2+1]), func(line[n/2-1])}) << endl;

	return 0;

}

