void solve() {
    int n;
    cin >> n;
    VI a(n), b(n);
    REP(i,0,n) cin >> a[i];
    sort(all(a));
    LL sum = 0;
    if (n % 2 == 0) {
        b[0] = a[n/2-1];
        b[n-1] = a[n/2];
        REP(i,0,n/2-1) b[(i+1)*2] = a[i];
        REP(i,0,n/2-1) b[i*2+1] = a[i+n/2+1];
        //REP(i,0,n) cout << b[i] << endl;
        REP(i,0,n-1) sum += abs(b[i] - b[i+1]);
    } else {
        b[0] = a[n/2];
        {
            LL tmp = 0;
            b[n-1] = a[n/2-1];
            REP(i,0,n/2-1) b[(i+1)*2] = a[i];
            REP(i,0,n/2) b[i*2+1] = a[i+n/2+1];
            //REP(i,0,n) cout << b[i] << endl;
            REP(i,0,n-1) tmp += abs(b[i] - b[i+1]);
            sum = max(sum, tmp);
        }
        {
            LL tmp = 0;
            b[n-1] = a[n/2+1];
            REP(i,0,n/2-1) b[(i+1)*2] = a[n-1-i];
            REP(i,0,n/2) b[i*2+1] = a[n-1-(i+n/2+1)];
            //REP(i,0,n) cout << b[i] << endl;
            REP(i,0,n-1) tmp += abs(b[i] - b[i+1]);
            sum = max(sum, tmp);
        }
    }
    cout << sum << endl;
}

int main() {
    solve();

    return 0;
}

