void Add(int x, int* sum){
	int tmp = 0;
	int i = 0;
	while(x > 0){
		int p = tmp;
		tmp = (tmp + sum[i] + x%10)/10;
		sum[i] = (p + sum[i] + x%10)%10;
		x /= 10;
		i++; 
	}
	while(tmp != 0){
		int p = tmp;
		tmp = (tmp + sum[i])/10;
		sum[i] = (p + sum[i])%10;
		tmp /= 10;
		i++;
	}
}
