/*
真ん中に極端なのおくのかな
68123
38162
小さいのを真ん中におくか、大きいのを真ん中におくかでわかれる？

31826=2,7,6,4=19
28163=6,7,5,3=21
31524

1234
 3142=232 
 2413=232

11224
 14122=331
 24121=2311
*/
int main(){
  ll N,ans=0; cin>>N;
  vector<ll> A(N+1,0),H(200000,0),L(200000,0);
  for(ll i=1; i<=N; i++) cin>>A[i];
  sort(A.begin(), A.end());
  //小さいの中心
  for(ll i=1; i<=N; i++){
    ll n=i/2;
    //小さくて左
    if(n%2==0 && i%2==0) L[100000-n]=A[n];//4
    //小さくて右
    else if(n%2==0 && i%2==1) L[100000+n]=A[n+1];//1,5
    //大きくて左
    else if(n%2==1 && i%2==0) L[100000-n]=A[N+1-n];//2
    //大きくて右
    else if(n%2==1 && i%2==1) L[100000+n]=A[N-n];//3
  }
  //大きいの中心
  for(ll i=1; i<=N; i++){
    ll n=i/2;
    //大左
    if(n%2==0 && i%2==0) H[100000-n]=A[N+1-n];//4
    //大右
    else if(n%2==0 && i%2==1) H[100000+n]=A[N-n];//1,5
    //小左
    else if(n%2==1 && i%2==0) H[100000-n]=A[n];//2
    //小右
    else if(n%2==1 && i%2==1) H[100000+n]=A[n+1];//3
  }
  ll s=100000-N/2-10, g=100000+N/2+10, tmp=0;
  for(ll i=s; i<=g; i++){
    if(L[i]==0 || L[i+1]==0) continue;
    tmp+=abs(L[i+1]-L[i]);
  }
  ans=max(tmp,ans);
  tmp=0;
  for(ll i=s; i<=g; i++){
    if(H[i]==0 || H[i+1]==0) continue;
    tmp+=abs(H[i+1]-H[i]);
  }
  ans=max(tmp,ans);
  cout<<ans<<endl;
}

