ll calc_sum(bool b){
    int fi,bi;
    ll res;

    if(b){
        res += a[n-1]+a[n-2]-2*a[0];
        fi = 1;
        bi = n-1;
    }else{
        res += 2*a[n-1]-(a[0]+a[1]);
        fi = 0;
        bi = n-2;
    }
    int cnt = b;
    while(fi+1<bi-1){
        res += a[bi]+a[bi-1] - (a[fi]+a[fi+1]);
        if(cnt%2==0) fi += 2;
        else bi -= 2;
        cnt ++;
    }
    if(n%2==0) res += a[bi] - a[fi];
    return res;
}

