	ll c[n];
	c[n / 2] = a[n - 1];
	mode = true;
	max_index = n - 2;
	min_index = 0;
	cnt = 0;
	rep(i, n) {
		if (mode) { // min
			c[n / 2 - (i + 1)] = a[min_index];
			min_index++;
			cnt++;
			if (cnt == n - 1) break;
			c[n / 2 + (i + 1)] = a[min_index];
			min_index++;
			cnt++;
			mode = false;
		} else {
			c[n / 2 - (i + 1)] = a[max_index];
			max_index--;
			cnt++;
			if (cnt == n - 1) break;
			c[n / 2 + (i + 1)] = a[max_index];
			max_index--;
			cnt++;
			mode = false;
		}
		if (cnt == n - 1) break;
	}

	ll sum2 = 0;
	rep(i, n - 1) {
		sum2 += abs(c[i + 1] - c[i]);
	}

