	for (i=0;i<N;i++){
		cin>>A[i];
	}
	sort(A.begin(),A.end());
	vector<LL> B;
	LL aSize=A.size();
	B.push_back(A[0]);
	B.push_back(A[aSize-1]);
	LL start=1;
	LL end=aSize-2;
	vector<LL>::iterator vit;
	while(true){
		LL x=A[start]-B[0];
		if (x<0){
			x=-x;
		}
		LL y=A[start]-B[B.size()-1];
		if (y<0){
			y=-y;
		}		
		if (x>=y){
			vit=B.begin();
			B.insert(vit,A[start]);
		}else{
			B.push_back(A[start]);
		}
		if (start>=end){
			break;
		}
		x=A[end]-B[0];
		if (x<0){
			x=-x;
		}
		y=A[end]-B[B.size()-1];
		if (y<0){
			y=-y;
		}
		if (x>=y){
			vit=B.begin();
			B.insert(vit,A[end]);
		}else{
			B.push_back(A[end]);
		}
		start++;
		end--;
		if (start>end){
			break;
		}
	}
	LL ans=0;
	for (i=0;i<N-1;i++){
		LL X=B[i]-B[i+1];
		if (X<0){
			X=-X;
		}
		ans+=X;
	}
	cout<<ans<<endl;
	return 0;
}

