ll solve(std::vector<ll> arr) {
    std::sort(arr.begin(), arr.end());
    std::deque<ll> items;
    for (auto& it : arr) {
        items.push_back(it);
    }
    std::deque<ll> deque;
    deque.push_back(items.front());
    items.pop_front();
    while (!items.empty()) {
        if (items.size() >= 1u) {
            auto item = items.back();
            items.pop_back();
            auto diff1 = std::abs(deque.front()-item);
            auto diff2 = std::abs(deque.back()-item);
            if (diff1 >= diff2) {
                deque.push_front(item);
            } else {
                deque.push_back(item);
            }
        }
        if (items.size() >= 1u) {
            auto item = items.front();
            items.pop_front();
            auto diff1 = std::abs(deque.front()-item);
            auto diff2 = std::abs(deque.back()-item);
            if (diff1 >= diff2) {
                deque.push_front(item);
            } else {
                deque.push_back(item);
            }
        }
    }
    ll prev = deque.front();
    ll answ = 0;
    for (auto& it : deque) {
        answ += std::abs(prev-it);
        prev = it;
    }
    return answ;
}

