        v.push_back(tmp);
    }

    std::vector<std::vector<long>> vs;
    vs.resize(fact(n+2));
    std::sort(v.begin(),v.end());
    long ct = 0;
    do {
        for (auto k : v) {
            vs[ct].push_back(k);
        }
        ct++;
    }while(std::next_permutation(v.begin(), v.end()));

    long ans = 0;
    long t = 0;
    long prev = 0;
    for (auto x : vs) {
        prev = t = 0;
        for (auto i : x) {
            if (prev != 0) {
                t += std::abs(i-prev);
            }
            prev = i;
        }
        ans = std::max(ans, t);
    }

    std::cout << ans << std::endl;
    return 0;
}

