long long n;
vector<long long> a;

long long solve();

int main() {
  cin >> n;
  for(int i = 0; i < n; ++i) {
    long long x;
    cin >> x;
    a.push_back(x);
  }
  sort(a.begin(), a.end());
  cout << solve() << endl;
  return 0;
}

long long solve() {
  long long ans = 0, lst, l, m, r;
  if(n % 2 == 0) {
    for(int i = 0; i < n / 2; ++i) {
      ans += 2 * (a[n - 1 - i] - a[i]);
      if(i == n / 2 - 1) ans -= a[n - 1 - i] - a[i];
    }
  }
  else {
    lst = (n - 3) / 2;
    for(int i = 0; i < lst; ++i)
      ans += 2 * (a[n - 1 - i] - a[i]);
    l = a[lst];
    m = a[lst + 1];
    r = a[lst + 2];
    ans += max(2 * r - m - l, r + m - 2 * l);
  }
  return ans;
}

