ll minim() {
	ll l = 1, r = n - 3;
	bool e = true;
	a.pb(vec[0]);
	a.pb(vec[n - 1]);
	b.pb(vec[n - 2]);
	while (l <= r)
	{
		ll y = vec[r];
		ll q, w;
		bool aa, bb;
		if (abs(a[a.size() - 1] - y) > abs(b[b.size() - 1] - y))
		{
			q = abs(a[a.size() - 1] - y);
			aa = true;
		}
		else
		{
			q = abs(b[b.size() - 1] - y);
			aa = false;
		}

		ll u = vec[l];
		if (abs(a[a.size() - 1] - u) > abs(b[b.size() - 1] - u))
		{
			w = abs(a[a.size() - 1] - u);
			bb = true;
		}
		else
		{
			w = abs(b[b.size() - 1] - u);
			bb = false;
		}
		if (w > q)
		{
			l++;
			if (bb)
			{
				a.pb(u);
			}
			else
			{
				b.pb(u);
			}
		}
		else
