lli fn(vector<lli> a)
{
  deque<lli> p, q;
  each (i, a) p.push_back(i);

  int cnt = 0;
  while (1 < p.size()) {
    if (q.empty()) {
      q.push_back(p.front());
      p.pop_front();
    } else {
      lli x, y;
      if (cnt % 2) {
        x = p.back();
        p.pop_back();
        y = p.back();
        p.pop_back();
      } else {
        x = p.front();
        p.pop_front();
        y = p.front();
        p.pop_front();
      }
      q.push_back(x);
      q.push_front(y);
    }
    ++cnt;
  }

  if (p.size()) {
    if (abs(q.front() - p.front()) < abs(q.back() - p.front())) {
      q.push_back(p.front());
      p.pop_front();
    } else {
      q.push_front(p.front());
      p.pop_front();
    }
  }

  vector<lli> b;
  while (q.size()) {
    b.push_back(q.front());
    q.pop_front();
  }

  // cout << b << endl;
  lli sum = 0;
  for (int i = 0; i + 1 < b.size(); ++i) {
    sum += abs(b[i] - b[i + 1]);
  }
  return sum;
}

