typedef long long int64;
typedef pair<int, int> ii;
const int INF = 1 << 29;
const int MOD = 1e9 + 7;

int64 solve(const vector<int>& a) {
  int n = a.size();
  vector<int> b(n);
  int ll, rr, d;
  ll = rr = (n - 1) / 2; d = 1;
  // trace(ll, rr, d);
  for (int i = 0; ; ++i) {
    if (d > 0) {
      if (ll < 0) break;
      b[ll] = a[i];
      rr += 2;
    } else {
      if (rr >= n) break;
      b[rr] = a[i];
      ll -= 2;
    }
    d = -d;
  }
  // trace(ll, rr, d);
  ll = rr = (n + 1) / 2; d = -1;
  for (int i = n - 1; ; --i) {
    if (d > 0) {
      if (ll < 0) break;
      b[ll] = a[i];
      rr += 2;
    } else {
      if (rr >= n) break;
      b[rr] = a[i];
      ll -= 2;
    }
    d = -d;
  }
  // for (int i = 0; i < n; ++i) {
  //   cout << b[i] << " ";
  // }
  // cout << endl;
  int64 ret = 0;
  for (int i = 1; i < n; ++i) {
    ret += abs(b[i] - b[i - 1]);
  }
  return ret;
}

int main() {
  int n;
  scanf("%d", &n);
  vector<int> a(n);
  for (int i = 0; i < n; ++i) {
    scanf("%d", &a[i]);
  }
  sort(a.begin(), a.end());
  int64 ret = solve(a);
  reverse(a.begin(), a.end());
  ret = max(ret, solve(a));
  printf("%lld\n", ret);
  return 0;
}

