const int MaxN = 100000;

/*
1 3 2 4 = 5

1 4 2 3 = 6

3 1 4 2 = 7

1 2 3 4 5

1 5 2 4 3  = 4 + 3 + 2 + 1 = 10

1 5 3 2 4  = 4 + 2 + 1 + 2 = 9

1 2 3 4 5 6
3 5 1 6 2 4
*/

int n;
deque <LL> d;
LL a[MaxN + 5], b[MaxN + 5];

void Solve() {
	int t = 0;
	for(int i = 1; i <= n / 2; i++) {
		if(t == 0) {
			d.push_front(a[i]);
			d.push_back(a[n - i + 1]);
		}
		else {
			d.push_front(a[n - i + 1]);
			d.push_back(a[i]);
		}
		t = t ^ 1;
	}
	int tot = 0;
	while(!d.empty()) {
		b[++tot] = d.front();
		d.pop_front();
	}
	LL ans = 0LL;
	for(int i = 1; i < tot; i++) ans += abs(b[i] - b[i + 1]);
	if(n & 1) ans += max(abs(a[(n + 1) / 2] - b[1]), abs(a[(n + 1) / 2] - b[tot]));
	printf("%lld\n", ans);
}

