    for (unsigned i = 0; i < hi.size(); ++i) {
        order.push_back(hi[i]);
        if (i != lo.size()) order.push_back(lo[i]);
    }

    if (D(order[N - 2], order[N - 1]) < D(order[0], order[N - 1])) {
        t = order[N - 1];
        order.pop_back();
