long long fact(long long n) {
    long long val = 1;
    for (long long i = 1; i <= n; i++) {
        val *= i;
    }
    return val;
}

int main()
{
    long long n = 0;
    long long tmp = 0;
    std::cin >> n;

    std::vector<long long> v;
    for (long long i = 0; i < n; i++) {
        std::cin >> tmp;
        v.push_back(tmp);
    }

    std::vector<std::vector<long long>> vs;
    long long k = fact(n);
    vs.resize(k+10);
    std::sort(v.begin(),v.end());

    long long ct = 0;
    do {
        for (long long k : v) {
            vs.at(ct).push_back(k);
        }
        ct++;
    }while(std::next_permutation(v.begin(), v.end()));

    long long ans = 0;
    long long t = 0;
    long long prev = 0;
    for (std::vector<long long> x : vs) {
        prev = t = 0;
        for (long long i : x) {
            if (prev != 0) {
                t += std::abs(i - prev);
            }
            prev = i;
        }
        ans = ans > t ? ans : t;
    }

    std::cout << ans << std::endl;
    return 0;
}

