        }
        else if(nxt){
            if(que.front()>que.back()){
                que.push_back(a[cur2]);
            }else{
                que.push_front(a[cur2]);
            }
            nxt=false;
            cur2--;
        }else{
            if(que.front()>que.back()){
                que.push_front(a[cur1]);
            }else{
                que.push_back(a[cur1]);
            }
            nxt=true;
            cur1++;
        }
    }
    ll res=0;
    ll prev = que.front();
    while(!que.empty()){
        res += abs(que.front()-prev);
        prev = que.front();
        que.pop_front();
    }
    cout << res << endl;
