int lmao() {
    int cnt = 2, id = n;
    while(cnt <= n) {
        b[cnt] = a[id];
        id -= 1;
        cnt += 2;
    }
    id = 1;
    cnt = 3;
    while(cnt <= n) {
        b[cnt] = a[id];
        cnt += 2;
        id++;
    }
    b[1] = a[id];
    long long sum = 0;
    for(int i = 1; i < n; i++)
        sum += abs(b[i] - b[i + 1]);
    return sum;
}
