        id++;
        cnt += 2;
    }
    b[n] = a[id]; id++;
    cnt = 1;
    while(cnt < n) {
        b[cnt] = a[id];
        id++;
        cnt += 2;
    }
    long long sum = 0;
    for(int i = 1; i < n; i++)
        sum += abs(b[i] - b[i + 1]);
