typedef long long ll;
const int MAX = 1e6 + 5;
ll N, A[MAX];

int main(){
    scanf("%lld" ,&N);
    for(int i = 1; i <= N; i++){
        scanf("%lld", A + i);
    }
    sort(A + 1, A + N + 1);
    deque<ll> dq;
    int l = 2, r = N - 1;
    dq.push_back(A[1]); dq.push_back(A[N]);
    while(l <= r){
        priority_queue<pair<ll, ll>> pq;
        pq.push({abs(dq.front() - A[l]), 0});
        pq.push({abs(dq.front() - A[r]), 1});
        pq.push({abs(dq.back() - A[l]), 2});
        pq.push({abs(dq.back() - A[r]), 3});
        if(pq.top().second == 0){
            dq.push_front(A[l]);
            l++;
        }
        else if(pq.top().second == 1){
            dq.push_front(A[r]);
            r--;
        }
        else if(pq.top().second == 2){
            dq.push_back(A[l]);
            l++;
        }
        else{
            dq.push_back(A[r]);
            r--;
        }
    }
    vector<ll> vt;
    while(!dq.empty()){
        vt.push_back(dq.back());
        dq.pop_back();
    }
    ll ans = 0;
    for(int i = 1; i < N; i++){
        ans += abs(vt[i] - vt[i - 1]);
    }
    printf("%lld\n" ,ans);
    return 0;
}

