	std::vector<int> A;
	A.resize(N);
	for(int i = 0; i < N; ++i)
		std::cin >> A[i];
	std::sort(A.begin(), A.end());

	int best = 0;
	std::vector<int> diffs(A.size());
	do{
		std::adjacent_difference(A.cbegin(), A.cend(), diffs.begin());
		for(int i=0; i<diffs.size(); ++i){
			if(diffs[i]<0) diffs[i] *= -1;
		}
		best = std::max(best, std::accumulate(diffs.begin(), diffs.end(), 0) - diffs[0]);
	}while(std::next_permutation(A.begin(), A.end()));

	std::cout << best << std::endl;

	return 0;
}

