    }
    if(abs(b - v[front])==num){
      sum += abs(b - v[front]);
      b = v[front];
      front++;
      continue;
    }
    if(abs(b - v[back])==num){
      sum += abs(b - v[back]);
      b = v[back];
      back--;
      continue;
    }
  }
  cout << sum << endl;
}

