class SolutionAlign {
public:
    int64_t test(int n, std::vector<int> values, std::vector<int> order) {
        std::vector<int> result(n);

        for (int i = 0; i < n; i++)
            result[order[i]] = values[i];

        int64_t ans = 0;
        for (int i = 1; i < n; i++)
            ans += std::abs(result[i] - result[i - 1]);
        return ans;
    }

    void solve(std::istream& in, std::ostream& out) {
        int n;
        in >> n;
        std::vector<int> values(n);
        for (int& v : values)
            in >> v;
        std::sort(values.begin(), values.end());

        std::vector<int> order;
        for (int i = 1; i < n; i += 2) {
            order.push_back(i);
        }
        order.push_back(0);
        if (n % 2 != 0)
            order.push_back(n - 1);
        for (int i = 2; i < n - 1; i += 2) {
            order.push_back(i);
        }
        auto ans = test(n, values, order);
        std::reverse(values.begin(), values.end());
        ans = std::max(ans, test(n, values, order));

        out << ans << std::endl;
    }
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    using Solution = SolutionAlign;

    int tests = 1;
//    std::cin >> tests;
    for (int test = 0; test < tests; ++test) {
        Solution solution;
        solution.solve(std::cin, std::cout);
    }

    return 0;
}

