			w.push_back(pii(pos+len,a[left]));
			l = a[left + 1];
			w.push_back(pii(pos-len,a[left+1]));
		}
		left += 2;
		len += 1;
	}
	if(abs(a[left] - l) > abs(a[left] - r))
	{
		l = a[left];
		w.push_back(pii(pos-len,a[left]));
	}
	else
	{
		r = a[left];
		w.push_back(pii(pos+len,a[left]));
	}
	sort(w.begin(),w.end());
	int ans = 0;
	for(int i=1;i<w.size();i++)
	{
		ans += abs(w[i].second - w[i-1].second);
	}
	printf("%d\n",ans);
    return 0;
}

