        for (int i = n/2 - 1 - (1 - n/2 % 2); i >= 0; i -= 2) b[index++] = a[i];
        for (int i = 1; i < n/2; i+= 2) b[index++] = a[i];
        index = 0;
        for (int i = n/2 - 1 - n/2 % 2; i >= 0; i -= 2) c[index++] = a[n-1-i];
