            for (int i = 0; i < (n-1)/2; i+= 2) c[index++] = a[n-1-i];
            //REP(i,0,(n+1)/2) cout << b[i] << endl;
            //REP(i,0,(n-1)/2) cout << c[i] << endl;
            REP(i,0,n/2) tmp += abs(b[i] - c[i]);
            REP(i,0,n/2) tmp += abs(b[i+1] - c[i]);
            sum = max(sum, tmp);           
        }
        {
            int tmp = 0;
            int index = 0;
            for (int i = (n-1)/2 - 1 - (1 - (n-1)/2 % 2); i >= 0; i -= 2) b[index++] = a[i];
            for (int i = 1; i < (n-1)/2; i+= 2) b[index++] = a[i];
            index = 0;
            for (int i = (n+1)/2 - 1 - (n+1)/2 % 2; i >= 0; i -= 2) c[index++] = a[n-1-i];
