void solve() {
	int n; cin >> n;
    vector<int> a(n);
    rep(i, n) {
        cin >> a[i];
    }
    sort(all(a));
    reverse(all(a));
    int ans = 0;
    if(n % 2 == 0) {
        rep(i, n) {
            if(i < (n - 2) / 2) ans += 2 * a[i];
            else if(i == (n - 2) / 2) ans += a[i];
            else if(i == (n - 2) / 2 + 1) ans -= a[i];
            else ans -= 2 * a[i];
        }
    } else {
        int res1 = 0, res2 = 0;
        rep(i, n) {
            if(i < (n - 1) / 2) res1 += 2 * a[i];
            else if(i == (n - 1) / 2 || i == (n - 1) / 2 + 1) res1 -= a[i];
            else res1 -= 2 * a[i];
        }
        rep(i, n) {
            if(i < (n - 3) / 2) res2 += 2 * a[i];
            else if(i == (n - 3) / 2 || i == (n - 3) / 2 + 1) res2 += a[i];
            else res2 -= 2 * a[i];
        }
        ans = max(res1, res2);
    }
    cout << ans << endl;
}

