// ------------>8------------------------------------->8------------

// Σc[i]a[i]の各係数のベクトルcを求める
//    n : cのサイズ
// sign : ジグザグの初めの符号
std::vector<int> getCoef(int n, int sign) {

	std::vector<int> c(n);

	REP(i, n) {
		// 最初か最後は隣接する数が1つだけなので1
		if (i == 0 || i == n - 1) {
			c[i] = 1;
		}
		else { // それ以外は隣接するものが2つあるので2
			c[i] = 2;
		}

		// ----------8<----------8<----------

		// signが+1 : 偶数番目は+c, 奇数番目は-c
		// signが-1 : 偶数番目は-c, 奇数番目は+c
		// →つまり，偶数番目はc * sign，奇数番目はc * (-sign)
		if (i % 2 == 0) {
			c[i] *= sign;
		}
		else {
			c[i] *= -sign;
		}

		// ----------8<----------8<----------
	}

	return c;
}

signed main() {
	INIT;

	VAR(int, n);
	VEC(int, a, n);

	// aは小さい順にソートしておく
	std::sort(ALL(a));

	int ans = 0;
	for (int sign : {-1, +1}) {
		// ジグザグの最初の符号をsignにしたときの係数を用意する
		auto c(getCoef(n, sign));

		// cも小さい順にソートしておく
		std::sort(ALL(c));

		// Σc[i]a[i]を計算して
		int sum = 0;
		REP(i, n) sum += a[i] * c[i];

		// 答えを更新
		CHMAX(ans, sum);
	}

	OUT(ans)BR;
	return 0;
}

