            l = a[left];
            left++;
        }
        else if((x>=w&&x>=y)&&x>=z){
            sum+=x;
            r = a[left];
            left++;
        }
        else if((y>=x&&y>=x)&&y>=z){
            sum+=y;
            l = a[right];
            right--;
        }
        else if((z>=w&&z>=x)&&z>=y){
            sum+=z;
            r = a[right];
            right--;
        }
    }
    W(sum)
    return 0;
}

