        while( !s.empty() ) {
                if( q.empty() ) {
                        auto it = s.begin();
                        q.push_back( *it );
                        s.erase(it);
                        continue;
                }
                auto L = s.begin();
                auto R = s.end(); R--;

                int st = q.front();
                int ed = q.back();

                ans += max( max( abs(*L - st), abs(*L - ed) ), max( abs(*R - st), abs(*R - ed) ) );
                if( max( abs(*L - st), abs(*L - ed) ) > max( abs(*R - st), abs(*R - ed) ) ) {
                        if( abs(*L - st) > abs(*L - ed) ) {
                                q.push_front(*L);
                                s.erase(L);
                        } else {
                                q.push_back(*L);
                                s.erase(L);
                        }
                } else {
                        if( abs(*R - st) > abs(*R - ed) ) {
                                q.push_front(*R);
                                s.erase(R);
                        } else {
                                q.push_back(*R);
