        d.push_front(mi);
        l++;
      } else {
        d.push_back(mx);
        r--;
      }
    } else {
      if (abs(f - mx) >= abs(b - mi)) {
        d.push_front(mx);
        r--;
      } else {
        d.push_back(mi);
        l++;
      }
    }
  }
  //cout << endl << d.size() << endl;
  int before = d.front();
  d.pop_front();
  //cout << before << endl;
  long long ans = 0;
  while (!d.empty()) {
    int next = d.front();
    //cout << next << endl;
    d.pop_front();
    ans += abs(before - next);
    before = next;
  }
  cout << ans << endl;
