		copy(a.begin(), a.begin()+n/2+1, back_inserter(smaller1));
		copy(a.begin()+n/2+1, a.end(), back_inserter(bigger1));
		reverse(smaller0.begin(), smaller0.end());
		reverse(smaller1.begin(), smaller1.end());
