typedef long long ll;

ll solve(std::vector<ll> arr) {
    std::sort(arr.begin(), arr.end());
    std::deque<ll> items;
    for (auto& it : arr) {
        items.push_back(it);
    }
    std::deque<ll> deque;
    deque.push_back(items.front());
    items.pop_front();
    while (!items.empty()) {
        if (items.size() >= 1u) {
            deque.push_back(items.back());
            items.pop_back();
        }
        if (items.size() >= 1u) {
            deque.push_front(items.back());
            items.pop_back();
        }
        if (items.size() >= 1u) {
            deque.push_back(items.front());
            items.pop_front();
        }
        if (items.size() >= 1u) {
            deque.push_front(items.front());
            items.pop_front();
        }
    }
    ll prev = deque.front();
    ll answ = 0;
    for (auto& it : deque) {
        answ += std::abs(prev-it);
        prev = it;
    }
    return answ;
}

