			last1 = v[0];
			last2 = v[0];
		}
		if (s == e) {
			res += max(abs(v[s] - last1), abs(v[s] - last2));
			break;
		}
		if (flag) {
			e -= 2;
			res += abs(last1 - v[e+2]) + abs(last2 - v[e+1]);
			last2 = v[e+2];
			last1 = v[e+1];
			flag = 0;
		}
		else {
			s += 2;
			res += abs(last1 - v[s-2]) + abs(last2 - v[s-1]);
			last1 = v[s-2];
			last2 = v[s-1];
			flag = 1;
		}
	}
	return res;
}

