using namespace std;

long long n;
vector<long long> a;

long long solve(int s, int g, int x);

int main() {
  cin >> n;
  for(int i = 0; i < n; ++i) {
    long long x;
    cin >> x;
    a.push_back(x);
  }
  sort(a.begin(), a.end());
  if(n == 2)
    cout << a[1] - a[0] << endl;
  else
    cout << solve(a[0], a[n - 1], 2) << endl;
  return 0;
}

long long solve(int s, int g, int x) {
  long long ans = 0, nl, nr, dummy[2] = {0};
  nl = s;
  nr = g;
  ans += nr - nl;
  if(ans == 0) return ans;
  for(int i = x; i < n; ++i) {
    long long l, r, now;
    if(i % 2 == 1)
      now = a[n - 1 - i / 2];
    else
      now = a[i / 2];
    l = max(nl - now, now - nl);
    r = max(nr - now, now - nr);
    if(l > r) {
      ans += l;
      nl = now;
    }
    else if(l < r) {
      ans += r;
      nr = now;
    }
    else {
      long long bf = nl;
      ans += l;
      nl = now;
      dummy[0] = solve(nl, nr, i + 1) - nr + nl;
      nl = bf;
      nr = now;
      dummy[1] = solve(nl, nr, i + 1) - nr + nl;
      return ans + max(dummy[0], dummy[1]);
    }
  }

  return ans;
}

