	{
		diffs[0] = abs(a[l] - lNum);
		diffs[1] = abs(a[l] - rNum);

		diffs[2] = abs(a[r] - lNum);
		diffs[3] = abs(a[r] - rNum);

		long long mDiff = -1;
		int maxI;
		for (int i = 0 ; i < 4 ; i++)
			if (diffs[i] > mDiff)
			{
				mDiff = diffs[i];
				maxI = i;
			}

		totalDiff = totalDiff + mDiff;	

		switch (maxI)
		{
		case 0:
			lNum = a[l];
			l++;
			break;
		case 1:
			rNum = a[l];
			l++;
			break;
		case 2:
			lNum = a[r];
			r--;
			break;
		case 3:
			rNum = a[r];
			r--;
			break;
		}
	}

	return totalDiff;
}

