        B[i] = A[ptr--];

    B[1] = A[ptr--];

    if(N % 2)
        B[N] = A[ptr--];

    for(int i=3; i<=N-1; i+= 2)
        B[i] = A[ptr--];

    long long ans = 0;

    for(int i=2; i<=N; i++)
        ans += abs(B[i] - B[i-1]);

    return ans;
