long long solve2(int N)
{
    int ptr = N;

    for(int i=1; i<=N; i+= 2)
        B[i] = A[ptr--];

    for(int i=2; i<=N; i+= 2)
        B[i] = A[ptr--];

    long long ans = 0;

    for(int i=2; i<=N; i++)
        ans += abs(B[i] - B[i-1]);

    return ans;
