int calc(std::vector<int> a, int t) {
	int n = a.size();
	std::vector<int> b;
	while (a.size() > b.size() + t) {
		b.emplace_back(a.back());
		a.pop_back();
	}

	int sum = 0;
	REP(i, a.size()) sum -= a[i] * 2;
	REP(i, b.size()) sum += b[i] * 2;
	if (n % 2 == 0) {
		sum += a[a.size() - 1];
		sum -= b[b.size() - 1];
	}
	else {
		if (t == 1) {
			sum += a[a.size() - 1];
			sum += a[a.size() - 2];
		}
		else {
			sum -= b[b.size() - 1];
			sum -= b[b.size() - 2];
		}
	}
	return sum;
}

