void solve(long long N, vector<long long> A){
	sort(ALL(A));

	if (N % 2 == 0) {
		int a = 0, b = 0;
		for(int i = 0; i < N / 2; ++i) {
			a += A[i];
		}
		for(int i = N / 2; i < N; ++i) {
			b += A[i];
		}
		cout << 2 * (b - a) + A[N / 2 - 1] - A[N / 2] << endl;
	} else {
		int a = 0, b = 0;
		for(int i = 0; i < N / 2; ++i) {
			a += A[i];
		}
		for(int i = N / 2; i < N; ++i) {
			b += A[i];
		}
		int res = 2 * (b - a) - A[N / 2] - A[N / 2 + 1];
		a = b = 0;
		for(int i = 0; i <= N / 2; ++i) {
			a += A[i];
		}
		for(int i = N / 2 + 1; i < N; ++i) {
			b += A[i];
		}
		res = max(res, 2 * (b - a) + A[N / 2] + A[N / 2 - 1]);
		cout << res << endl;
	}
}

