                step = 1;
                a.pop_front();
                break;
        }
    }

    ll diffsum = 0;
    for(int i = 1; i < N; ++i) {
        diffsum += abs(ret[i] - ret[i-1]);
    }

    step = 1;
    ret2.push_back(b.front());
    b.pop_front();
    while(b.size() != 0) {
        switch (step) {
