		          (getsum(n / 2 + 3, n) - getsum(1, n / 2)) * 2 + a[n / 2 + 1] + a[n / 2 + 2]);
	}
	else ans = (getsum(n / 2 + 2, n) - getsum(1, n / 2 - 1)) * 2 + a[n / 2 + 1] - a[n / 2];
	return printf("%lld\n", ans), 0;
