#define ALL(x) std::begin(x), std::end(x)
#define RALL(x) (x).rbegin(), (x).rend()


long long compute(std::deque<int> deque)
{
  long long s = 0;

  int l, r, dl, dr;

  l = r = deque.front(); deque.pop_front();

  while (1) {
    if (deque.empty())
      break;

    int x = deque.back(); deque.pop_back();

    if ((dl = std::abs(l - x)) > (dr = std::abs(r - x))) {
      s += dl;
      l  = x;
    }
    else {
      s += dr;
      r  = x;
    }

    if (deque.empty())
      break;

    x = deque.front(); deque.pop_front();

    if ((dl = std::abs(l - x)) > (dr = std::abs(r - x))) {
      s += dl;
      l  = x;
    }
    else {
      s += dr;
      r  = x;
    }
  }

  return s;
}


