                if (t1.back() > t2.back()) {
                    t1.push_back(nums[r--]);
                } else {
                    t2.push_back(nums[r--]);
                }
            } else {
                t1.push_back(nums[r--]);
                t2.push_back(nums[r--]);
            }
            right = false;
        } else {
