                if (t1.back() < t2.back()) {
                    t1.push_back(nums[l++]);
                } else {
                    t2.push_back(nums[l++]);
                }
            } else {
                t1.push_back(nums[l++]);
                t2.push_back(nums[l++]);
            }
            right = true;
        }
    }
    for (int i = 0; i < t1.size() - 1; ++i) {
        ans1 += abs(t1[i] - t1[i + 1]);
    }
    for (int i = 0; i < t2.size() - 1; ++i) {
        ans1 += abs(t2[i] - t2[i + 1]);
    }
    ans = max(ans, ans1);
    cout << ans << endl;
    return 0;

