	ans+=a[r]-a[r-2];
	r--;
      }
      else{
	ans+=a[r]-a[l-1];
	ans+=a[r-1]-a[l-2];
	r-=2;
      }

    }
  }
  else{
    f=a[n-1];
    if(n>=3){
      ans+=f-a[0];
      ans+=f-a[1];
    }
    else if(n==2) ans=a[1]-a[0];
    l=2;r=n-2;
     while(1){
        if(r<l) break;
      else if(r<l+1){
	ans+=a[r]-a[r-2];
	r--;
      }
      else{
	ans+=a[r]-a[l-1];
	ans+=a[r-1]-a[l-2];
	r-=2;
      }
      if(r<l) break;
      else if(r<l+1){
	ans+=a[l+2]-a[l];
	l++;
      }
      else{
	ans+=a[r+1]-a[l];
	ans+=a[r+2]-a[l+1];
	l+=2;
      }

    }
  }
  cout<<ans<<endl;
  return 0;
}

