int N, K;
int A[300000];
int B[300000];
int C[300001];
bool ap[300001];

void pre() {
	deque<int> Q;
	REP(i, 0, N + K - 1) {
		int p = A[i % N];
		while (!Q.empty() && A[Q.back() % N] <= p) {
			Q.pop_back();
		}
		Q.push_back(i);
		if (Q.front() == i - K) Q.pop_front();
		if (i >= K - 1) B[i - (K - 1)] = A[Q.front() % N];
	}

	REP(i, 0, N) {
		++C[B[i]];
		ap[A[i]] = true;
	}

	REP(i, 2, N + 1) {
		C[i] += C[i - 1];
	}
}

int times() {
	int no = 0;
	while (no < N && A[no] == 1) {
		++no;
	}
	if (no == N) return N;

	int st = no;
	while (st < N && A[st] != 1) {
		++st;
	}
	if (st == N) return no;

	int di = 0;
	while (di < N && A[(st + di) % N] == 1) {
		++di;
	}

	int cnt = 0;
	REP(i, 0, N) {
		if (A[i] == 1) ++cnt;
	}
	if (cnt != di) return -1;
	return di;
}

MInt sub() {
	K = times();
	if (K == -1) return 0;
	pre();

	MInt ans = 1;
	int cnt = 0;
	REP(i, 1, N + 1) {
		if (ap[i]) continue;
		ans *= C[i] - (i - 1);
	}

	return ans;
}

int main() {
	cin >> N;
	REP(i, 0, N) {
		cin >> A[i];
	}
	cout << sub() << endl;
	return 0;
}

