int main()
{
    scanf("%d", &n);
    for(int i=1;i<=n;i++)
    {
        scanf("%lld", &a[i]);
    }
    sort(a+1, a+n+1);
    if(n==2)
    {
        printf("%lld\n" , a[2]-a[1]);
        return 0;
    }
    int l=2, r=n-2;
    ll sum=a[n]-a[1]+a[n-1]-a[1];
    ll left=a[n-1];
    ll right=a[n];
    int cnt=0;
    while(l<=r)
    {
        if(cnt==1)
        {
            sum += _abs(left-a[l]);
            left=a[l];
            ++cnt;
            ++l;
        }
        else if(cnt==0)
        {
            sum += _abs(right-a[l]);
            right = a[l];
            ++l;
            ++cnt;
        }
        else if(cnt==3)
        {
            sum += _abs(left-a[r]);
            left=a[r];
            --r;
            ++cnt;
        }
        else if(cnt==2)
        {
            sum += _abs(right-a[r]);
            right=a[r];
            --r;
            ++cnt;
        }
        cnt%=4;
    }
    ll ans = 0;
    left=a[n], right=a[n];
    l=1, r=n-1;
    while(l<=r)
    {
        if(cnt==0)
        {
            ans += _abs(right-a[l]);
            right=a[l];
            l++;
            cnt++;
        }
        else if(cnt==1)
        {
            ans += _abs(left-a[l]);
            left=a[l];
            l++;
            cnt++;
        }
        else if(cnt==2)
        {
            ans += _abs(right-a[r]);
            right=a[r];
            --r;
            cnt++;
        }
        else if(cnt==3)
        {
            ans += _abs(left-a[r]);
            left=a[r];
            --r;
            cnt++;
        }
        cnt%=4;
    }
    printf("%lld\n", max(sum , ans));
    return 0;

}

