inline int read() {
	char ch = getchar(); int u = 0, f = 1;
	while(!isdigit(ch)) { if(ch == '-') f = -1; ch = getchar(); }
	while(isdigit(ch))  { u = u * 10 + ch - 48; ch = getchar(); } return u * f;
}

inline ll Solve(int L, int R, int k, int t, ll rnt = 0) {
	int l = n, r = n; b[n] = k;
	while(R - L + 1 >= 2) {
		if(t & 1) {
			rnt += a[R] + a[R - 1] - b[l] - b[r];
			b[++r] = a[R--]; b[--l] = a[R--];
		} else {
			rnt += b[l] + b[r] - a[L] - a[L + 1];
			b[++r] = a[L++]; b[--l] = a[L++];
		} t ^= 1;
	}
	if(R - L + 1 >= 1) rnt += max(abs(b[r] - a[R]), abs(b[l] - a[R]));
	return rnt;
}

int main() {
	n = read();
	rep(i, 1, n) a[i] = read();
	sort(a + 1, a + 1 + n);
	cout << max(Solve(2, n, a[1], 1), Solve(1, n - 1, a[n], 0));
	return 0;
}

