      right.push_back(x);
      ind_l++;
    }else if(maxabs==y1){
      left.push_back(y);
      ind_r--;
    }else if(maxabs==y2){
      right.push_back(y);
      ind_r--;
    }
    ans += maxabs;
  }
  cout << ans << endl;
  return 0;
}

