		ll sltl = abs(sl-tl);
		ll sltr = abs(sl-tr);
		ll srtl = abs(sr-tl);
		ll srtr = abs(sr-tr);
		ll mx = max({sltl,sltr,srtl,srtr});
		if(mx==sltl){
			T.push_front(sl);
			S.pop_front();
		}else if(mx==sltr){
			T.push_back(sl);
			S.pop_front();
		}else if(mx==srtl){
			T.push_front(sr);
			S.pop_back();
		}else{
			T.push_back(sr);
			S.pop_back();
		}
	}
	ll ans = 0;
	ll u = T.front();
	T.pop_front();
	while(!T.empty()){
		ll t = T.front();
		ans += abs(u-t);
		u = t;
		T.pop_front();
	}
	cout << ans << endl;

	return 0;
}

