long long solve() {
  long long ans = 0, nl, nr, lcnt = 1, rcnt = 1;
  nl = a[0];
  nr = a[n - 1];
  ans += nr - nl;
  for(int i = 2; i < n; ++i) {
    long long now;
    if(i == n - 1) {
      if(i % 2 == 1)
        now = a[n - 1 - i / 2];
      else
        now = a[i / 2];
      ans +=
          max(now - a[lcnt / 2], a[n - 1 - rcnt / 2] - now);
    }
    else if(i % 2 == 1) {
      now = a[n - 1 - i / 2];
      ans += now - a[lcnt / 2];
      ++lcnt;
    }
    else {
      now = a[i / 2];
      ans += a[n - 1 - rcnt / 2] - now;
      ++rcnt;
    }
  }
  return ans;
}

