    ll N; cin >> N;
    vector<ll> A(N); for(auto& in:A) cin >> in;
    sort(A.begin(),A.end());

    deque<ll> deq(A.begin(),A.end());
    deque<ll> T;

    T.push_back(deq.back()); deq.pop_back();
    ll cnt = 0;
    while(deq.size()){
        ll L = T.front(),R = T.back();
        ll V;
        if(cnt%2==0){
            V = deq.front(); deq.pop_front();
        }else{
            V = deq.back(); deq.pop_back();
        }
        cnt++;
        if(abs(L-V) > abs(R-V)){
            T.push_front(V);
        }else{
            T.push_back(V);
        }
    }
    ll now = T.front(); T.pop_front();
    while(T.size()){
        res += abs(T.front() - now);
        now = T.front(); T.pop_front();
    }

    return res;
}
