#define reps(i, a, b) for (int i = a; i < b; i++)
#define rep(i, a) reps(i, 0, a)

ll calc(vector<ll>& v)
{
  int N = v.size();
  ll a = 0, b = 0;
  rep(i, N / 2) a += v[i];
  reps(i, N / 2, N) b += v[i];
  return abs(a-b);
}

