  cin >> N;
  vector<ll> v(N);
  rep(i, N) cin >> v[i];
  sort(v.begin(), v.end());
  ll res = calc(v);
  reverse(v.begin(), v.end());
  cout << max(res, calc(v)) << endl;
}

