long long cand(int c, int *a, int n) {

    long long ansl = 0, ansr = 0;
    int pl = c, pr = c;

    for (int l = 0, r = n-1; l < c || c < r; l++, r--) {
        if (l < c) {
            ansl += abs(a[pl] - a[l]);
            pl = l;
        }
        if (c < r) {
            ansl += abs(a[pl] - a[r]);
            pl = r;
        }
        if (c < r) {
            ansr += abs(a[pr] - a[r]);
            pr = r;
        }
        if (l < c) {
            ansr += abs(a[pr] - a[l]);
            pr = l;
        }
    }

    return max(ansl, ansr);

