typedef long long ll;

ll Solve(const vector<ll>& a) {
  int l = 0;
  int r = a.size() - 1;
  ll result = abs(a[r] - a[l]);
  while (r - l > 2) {
    result += abs(a[l] - a[r - 1]) + abs(a[l + 1] - a[r]);
    l++;
    r--;
  }
  if (r - l == 2) result += abs(a[l] - a[l + 1]);
  return result;
}

