long long process()
{
	int l=2,r=n,num1=0,num2=0;
	for(int i=1;i<n;i++)
	{
		//left
		if(i%2)  
		{
			num1++;
			if(num1%2) mp[-num1]=a[r--];
			else mp[-num1]=a[l++];
		}
		//right
		else
		{
			num2++;
			if(num2%2) mp[num2]=a[r--];
			else mp[num2]=a[l++];
		}
	}

	long long ans=0;
	for(int i=-num1;i<num2;i++)
		ans+=abs(mp[i]-mp[i+1]);
	return ans;
}

