  for (i=0;i<N;++i) {
    cin >> A[i];
  }
  sort(A, A+N);
  for (i=0;i<N/2;++i) {
    B[2*i+1]=A[i];
  }
  B[0]=A[N/2];
  if (N%2==1) {
    B[N-1]=A[N/2 +1];
  } else {
    B[N-2]=A[N/2 +1];
  }
  for (i=1;N/2 + i+1 < N;++i) {
    B[2*i]=A[N/2 + i+1];
  }

  for (i=0;i<N/2;++i) {
    C[2*i+1]=A[N-1-i];
  }
  C[0]=A[N-1-N/2];
  if (N%2==1) {
    C[N-1]=A[N-1-(N/2 +1)];
  } else {
    C[N-2]=A[N-1-(N/2 +1)];
  }
  for (i=1;N/2 + i+1 < N;++i) {
    C[2*i]=A[N-1-(N/2 + i+1)];
  }
  S=0;
  T=0;
  for (i=0;i<N-1;++i) {
    if (B[i+1] - B[i] > 0) {
      S+=B[i+1] - B[i];
    } else {
      S+=B[i]-B[i+1];
    }
    if (C[i+1] - C[i] > 0) {
      T+=C[i+1] - C[i];
    } else {
      T+=C[i]-C[i+1];
    }
  }
  if (S>T) {
    cout << S << endl;
  } else {
    cout << T << endl;
  }
  return 0;
}

