#include <bits/stdc++.h>

using namespace std;

long long Calc(vector<int> res) {
    long long total = 0;
    int n = res.size();
    for (int i = 1; i < n; ++i)
        total += abs(res[i] - res[i - 1]);
    return total;
}

pair<long long, vector<int>> Solve(vector<int> v) {
    int n = v.size();
    long long ret = 0;
    for (int first = n / 2 - 1; first <= n / 2 + 1; ++first) {
        for (int second = first + 1; second <= n / 2 + 1; ++second) {
            deque<int> w(v.begin(), v.end()); 
            int e1 = w[first], e2 = w[second];
            w.erase(w.begin() + second);
            w.erase(w.begin() + first);

            vector<int> res = {e1};
            for (int i = 0; i < n - 2; ++i) {
                if (i % 2 == 0) res.push_back(w.front()), w.pop_front();
                else res.push_back(w.back()), w.pop_back();
            }   
            res.push_back(e2);
            ret = max(ret, Calc(res));
            swap(res.front(), res.back());
            ret = max(ret, Calc(res));
        }
    }

    return {ret, {}};
}

int main() {
    int n; cin >> n;
    vector<int> v(n);
    for (auto& x : v) cin >> x;
    sort(v.begin(), v.end());

    pair<long long, vector<int>> best;
    for (int it = 0; it < 2; ++it) {
        best = max(best, Solve(v));
        reverse(v.begin(), v.end());
    }
    cout << best.first << endl;
}

