    vs.resize(fact(n));
    for (auto v : vs){
        v.resize(n);
    }
    std::sort(v.begin(),v.end());
    int ct = 0;
    do {
        for (auto k : v) {
            vs[ct].push_back(k);
        }
        ct++;
    }while(std::next_permutation(v.begin(), v.end()));

    long ans = 0;
