int main() {
  int N;
  cin >> N;
  deque< int > deq(N);
  for(int i = 0; i < N; i++) cin >> deq[i];
  sort(begin(deq), end(deq));


  int64 ans = 0;
  for(int _ = 0; _ < 2; _++) {
    deque< int > sa;
    auto q = deq;
    int f = _;
    int64 ret = 0;
    while(deq.size()) {
      int v;
      if(f) v = deq[0], deq.pop_front();
      else v = deq.back(), deq.pop_back();
      f ^= 1;
      if(sa.empty()) {
        sa.push_back(v);
      } else {
        if(abs(sa[0] - v) < abs(sa.back() - v)) {
          ret += abs(sa.back() - v);
          sa.push_back(v);
        } else {
          ret += abs(sa[0] - v);
          sa.push_front(v);
        }
      }
    }
    ans = max(ans, ret);
    deq = q;
  }
  cout << ans << endl;
}

