long long solve() {
  long long ans = 0, nl, nr, ans2 = 0;
  nl = a[0];
  nr = a[n - 1];
  ans += nr - nl;
  for(int i = 2; i < n; ++i) {
    long long l, r, now;
    if(i % 2 == 1)
      now = a[n - 1 - i / 2];
    else
      now = a[i / 2];
    l = max(nl - now, now - nl);
    r = max(nr - now, now - nr);
    if(l > r) {
      ans += l;
      nl = now;
    }
    else {
      ans += r;
      nr = now;
    }
  }
  nl = a[0];
  nr = a[n - 1];
  ans2 += nr - nl;
  for(int i = 2; i < n; ++i) {
    long long l, r, now;
    if(i % 2 == 0)
      now = a[n - 1 - i / 2];
    else
      now = a[i / 2];
    l = max(nl - now, now - nl);
    r = max(nr - now, now - nr);
    if(l > r) {
      ans2 += l;
      nl = now;
    }
    else {
      ans2 += r;
      nr = now;
    }
  }
  ans2 = max(ans, ans2);
  ans = 0;
  nl = a[0];
  nr = a[n - 1];
  ans += nr - nl;
  for(int i = 2; i < n; ++i) {
    long long l, r, now;
    if(i % 2 == 0)
      now = a[n - 1 - i / 2];
    else
      now = a[i / 2];
    l = max(nl - now, now - nl);
    r = max(nr - now, now - nr);
    if(l < r) {
      ans += l;
      nl = now;
    }
    else {
      ans += r;
      nr = now;
    }
  }
  ans2 = max(ans2, ans);
  ans = 0;
  nl = a[0];
  nr = a[n - 1];
  ans += nr - nl;
  for(int i = 2; i < n; ++i) {
    long long l, r, now;
    if(i % 2 == 1)
      now = a[n - 1 - i / 2];
    else
      now = a[i / 2];
    l = max(nl - now, now - nl);
    r = max(nr - now, now - nr);
    if(l < r) {
      ans += l;
      nl = now;
    }
    else {
      ans += r;
      nr = now;
    }
  }
  return max(ans, ans2);
}

