int main()
{
	int N;
	cin >> N;

	vec A(N);

	for (int i = 0; i < N; ++i)
	{
		cin >> A[i];
	}

	sort(A.begin(), A.end());

	if (N % 2 == 0)
	{
		ll ans = 0;

		for (int i = 0; i < N; ++i)
		{
			ans += 2 * ((i < N / 2) ? (-A[i]) : A[i]);
		}
		ans += A[N / 2 - 1];
		ans -= A[N / 2];

		cout << ans << endl;

		return 0;
	}


	ll ansA = 0, ansB = 0;

	for (int i = 0; i < N; ++i)
	{
		ansA += 2 * ((i < N / 2) ? (-A[i]) : A[i]);
		ansB += 2 * ((i > N / 2) ? A[i] : (-A[i]));
	}

	ansA -= A[N / 2] + A[N / 2 + 1];
	ansB += A[N / 2] + A[N / 2 - 1];

	cout << ((ansA > ansB) ? ansA : ansB) << endl;

	return 0;
}

