void solve(long long N, std::vector<long long> A) {
  sort(A.begin(), A.end());
  vector<LL> B;
  for (int i = 0; i < A.size() - 1; i++) B.push_back(A[i + 1] - A[i]);
  vector<LL> x(N - 1);
  vector<LL> y(N - 1);
  for (int i = 0; i < N - 1; i++) {
    x[i] = 2 * i + 2;
    y[i] = 2 * i + 2;
  }
  reverse(y.begin(), y.end());
  for (int i = 0; i < N - 1; i++) x[i] = min(x[i], y[i]);

  LL ans = 0;
  for (int i = 0; i < N - 1; i++) {
    ans += B[i] * x[i];
  }
  LL minim = 0;
  if (N % 2 == 0) {
    minim = B[N / 2];
  } else
    minim = min(B[N / 2], B[N / 2 - 1]);
  ans -= minim;
  cout << ans << endl;
}

int main() {
  cout << setprecision(10);
  long long N;
  scanf("%lld", &N);
  std::vector<long long> A(N);
  for (int i = 0; i < N; i++) {
    scanf("%lld", &A[i]);
  }
  solve(N, std::move(A));
  return 0;
}

