long long cand(int c, int *a, int n) {

    long long ans = 0;

    for (int l = 0, r = n-1; l < c || c < r; l++, r--) {
        if (l < c) ans += 2ll * (long long)abs(a[l] - a[c]);
        if (c < r) ans += 2ll * (long long)abs(a[r] - a[c]);
    }

    ans -= min(abs(a[c-1] - a[c]), abs(a[c+1] - a[c]));

    return ans;
}

