const int maxn = 100010;
int n, a[maxn];
deque<int> q;

int main() {
    scanf("%d", &n);
    for (int i = 1; i <= n; i++) {
        scanf("%d", &a[i]);
    }
    sort(a + 1, a + n + 1);
    q.push_back(a[n]);
    int l = 1, r = n - 1, cur = 1;
    while (l < r) {
        int cnt = 1, x, y;
        if (cur == 1) {
            x = a[l++];
            if (l < r) y = a[l++], cnt++;
        } else {
            x = a[r--];
            if (l < r) y = a[r--], cnt++;
        }
        if (cnt == 1) {
            abs(q.front() - x) < abs(q.back() - x) ? q.push_back(x) : q.push_front(x);
        } else {
            if (abs(q.front() - x) + abs(q.back() - y) < abs(q.front() - y) + abs(q.back() - x)) {
                q.push_front(y), q.push_back(x);
            } else {
                q.push_front(x), q.push_back(y);
            }
        }
        cur ^= 1;
    }
    if (l == r) {
        abs(q.front() - a[l]) < abs(q.back() - a[l]) ? q.push_back(a[l]) : q.push_front(a[l]);
    }
    int pre = q.front(); q.pop_front(); long long ans = 0;
    while (!q.empty()) {
        ans += abs(q.front() - pre), pre = q.front(), q.pop_front();
    }
    printf("%lld\n", ans);
    return 0;
}

