	sort(a.begin(), a.end());

	ll ans = 0;
	FOR(_, 2) {
		int ad = n / 2;
		int mn = n - ad;
		if (_ % 2 == 1) swap(ad, mn);

		ll cans = 0;
		FOR(i, n) {
			if (i < mn) cans -= a[i] * 2;
			else cans += a[i] * 2;
		}

		if (ad > mn) {
			cans -= a[mn];
			cans -= a[mn + 1];
		} else if(ad < mn) {
			cans += a[mn - 1];
			cans += a[mn - 2];
		} else {
			cans -= a[mn];
