int main() {

  int N;
  cin >> N;

  int A[100000];
  for(int i = 0; i < N; ++i) cin >> A[i];
  sort(A, A+N);

  int min_idx = 1;
  int max_idx = N-1;
  bool pop_max = true;
  int poped_num_small = A[0];
  int poped_num_large = A[0];
  long long sum = 0;

  //cout << A[0] << endl;

  while(min_idx <= max_idx) {
    if(min_idx == max_idx) {
      if(pop_max) {
        sum += A[max_idx] - poped_num_small;
        max_idx -= 2;
      }
      else {
        sum += poped_num_large - A[min_idx];
        min_idx += 2;
      }
    }
    else {
      if(pop_max) {
        /*
        cout << A[max_idx-1] << endl;
        cout << A[max_idx] << endl;
        //*/

        sum += A[max_idx]   - poped_num_small;
        sum += A[max_idx-1] - poped_num_large;

        poped_num_small = A[max_idx-1];
        poped_num_large = A[max_idx];

        max_idx -= 2;
      }
      else {
        /*
        cout << A[min_idx] << endl;
        cout << A[min_idx+1] << endl;
        //*/

        sum += poped_num_small - A[min_idx];
        sum += poped_num_large - A[min_idx+1];

        poped_num_small = A[min_idx];
        poped_num_large = A[min_idx+1];

        min_idx += 2;
      }
    }

    /*
    cout << "min idx:" << min_idx << endl;
    cout << "max idx:" << max_idx << endl;
    //*/
    pop_max = !pop_max;
  }

  cout << sum << endl;

}

