const int dr[]={0,1,0,-1,0};

ll fc(const VI& v){
	int n= sz(v);
	deque<int> dq = {v.front()};
	for(int i=0, l=1, r=n-1; l<=r; i++){
		if(i%2==0){
			if(l<=r) dq.push_back( v[r--]);
			if(l<=r) dq.push_front(v[r--]);
		}else{
			if(l<=r) dq.push_back( v[l++]);
			if(l<=r) dq.push_front(v[l++]);
		}
	}
	ll rtn =0;
	rep(i, n-1) rtn += abs(dq[i] - dq[i+1]);
	return rtn;
}

