deque<ll> make(vector<ll> &A) {
    deque<ll> ret;
    int N = A.size();
    int j = 0, k = N - 1;
    ret.push_back(A[j++]);
    while(1) {
        if (j > k) break;
        ret.push_back(A[k--]);
        if (j > k) break;
        ret.push_front(A[k--]);
        if (j > k) break;
        ret.push_back(A[j++]);
        if (j > k) break;
        ret.push_front(A[j++]);
    }
    return ret;
}

