const int MOD = 1000000007;
#define MAX_N 100010

enum Direction { L_S = 0, R_S = 1, L_B = 2, R_B = 3 };

signed main()
{
    ll N;
    cin >> N;
    vector<ll> A(N, 0);
    REP(i, N) { cin >> A[i]; }
    SORT(A);

    if(N == 2) {
        printf("%lld\n", abs(A[0] - A[1]));
        return 0;
    }

    // 最小が真ん中パターン
    int l_ind = 1, r_ind = A.size() - 3;
    ll cand1 = abs(A[A.size()-1] - A[0]) + abs(A[A.size()-2] - A[0]);
    ll r_val = A[A.size()-2];
    ll l_val = A[A.size()-1];

    auto Process = [&](ll& cand, int flag) {
        while(l_ind <= r_ind) {
            ll val;
            if(flag == L_S) {
                val = A[l_ind];
                l_ind++;
                cand += abs(l_val - val);
                l_val = val;
                flag = R_S;
            }
            else if(flag == R_S) {
                val = A[l_ind];
                l_ind++;
                cand += abs(r_val - val);
                r_val = val;
                flag = L_B;
            }
            else if(flag == L_B) {
                val = A[r_ind];
                r_ind--;
                cand += abs(l_val - val);
                l_val = val;
                flag = R_B;
            }
            else if(flag == R_B) {
                val = A[r_ind];
                r_ind--;
                cand += abs(r_val - val);
                r_val = val;
                flag = L_S;
            }
        }
    };
    Process(cand1, L_S);

    // 最大が真ん中パターン
    l_ind = 2, r_ind = A.size() - 2;
    ll cand2 = abs(A[A.size()-1] - A[0]) + abs(A[A.size()-1] - A[1]);
    r_val = A[0];
    l_val = A[1];
    Process(cand2, L_B);

    ll ans = max(cand1, cand2);
    printf("%lld\n", ans);
    return 0;
}

