			b[n / 2 + (i + 1)] = a[max_index];
			max_index--;
			cnt++;
			mode = false;
		}
		if (cnt == n - 1) break;
	}

	ll sum2 = 0;
	rep(i, n - 1) {
		sum2 += abs(b[i + 1] - b[i]);
	}

	cout << max(sum1, sum2) << endl;

	return 0;
}

