		ll sum0 = 0, sum1 = 0;
		for (int i = 0; i < n; ++i)
		{
			if (i<n/2) sum0 -= a[i];
			else sum0 += a[i];
		}
		sum0 *= 2;
		sum0 -= a[n/2+1] + a[n/2];
		for (int i = 0; i < n; ++i)
		{
			if (i<(n+1)/2) sum1 -= a[i];
			else sum1 += a[i];
		}
		sum1 *= 2;
		sum1 += a[(n+1)/2-1] + a[(n+1)/2-2];
		ans = max(sum0, sum1);
	}
	cout << ans << endl;
	return 0;
}

