ll solve1(int n, vi a) {
    int h = n >> 1;
    vi big, small;
    sort(RALL(a));
    fori (i, n)
        if (i < h) big.push_back(a[i]);
        else small.push_back(a[i]);

    int i = 0, j = 2;
    vi res(n);
    res[0] = small[0];
    if (small.size() > 1) res[n - 1] = small[1];
    for (int k = 1; k < n - 1; ++k)
        if (k & 1)
            res[k] = big[i++];
        else
            res[j] = small[j++];
    ll ret = 0;
    for (int i = 1; i < n; ++i) ret += abs(res[i] - res[i - 1]);
    return ret;
}

ll solve2(int n, vi a) {
    int h = n >> 1;
    vi big, small;
    sort(ALL(a));
    fori (i, n)
        if (i < h) small.push_back(a[i]);
        else big.push_back(a[i]);

    int i = 0, j = 0;
    vi res(n);
    res[0] = big.back();
    big.pop_back();
    if (big.size()) res[n - 1] = big.back();
    big.pop_back();
    for (int k = 1; k < n - 1; ++k)
        if (k & 1)
            res[k] = small[i++];
        else
            res[j] = big[j++];
    ll ret = 0;
    for (int i = 1; i < n; ++i) ret += abs(res[i] - res[i - 1]);
    return ret;
}

