  cin >> n;

  vector<int> v(n);
  REP(i,n){
    cin >> v[i];
  }

  SORTV(v);

  llong ans = 0;
  if(n == 2){
    cout << abs(v[0] - v[1]) << endl;
    return 0;
  }

  int min_idx = 1, max_idx = n - 1;
  int left = v[0], right = v[0];
  while(true){
    if(min_idx == max_idx){
      int val = v[min_idx];
      ans += max(abs(left - val), abs(right - val));
      break;
    }

    //choice min
    int val = 0;
    int choice = -1; //0:leftmin 1:rightmin 2:leftmax 3:rightmax
    if(abs(left - v[min_idx]) > val){
      val = abs(left - v[min_idx]);
      choice = 0;
    }
    if(abs(right - v[min_idx]) > val){
      val = abs(right - v[min_idx]);
      choice = 1;
    }

    //choice max
    if(abs(left - v[max_idx]) > val){
      val = abs(left - v[max_idx]);
      choice = 2;
    }

    if(abs(right - v[max_idx]) > val){
      val = abs(right - v[max_idx]);
      choice = 3;
    }

    if(choice == 0){
      left = v[min_idx];
      min_idx++;
    }else if(choice == 1){
      right = v[min_idx];
      min_idx++;
    }else if(choice == 2){
      left = v[max_idx];
      max_idx--;
    }else{
      right = v[max_idx];
      max_idx--;
    }

    ans += val;

    //cout << choice << " " << ans << endl;
  }

  cout << ans << endl;
  return 0;
}

