int n;
int a[100055];

long long solve() {
	long long ret = 0;

	int l = 0, r = n - 1;
	int valL = a[0], valR = a[n - 1];

	ret += abs(a[n - 1] - a[0]);
	l++, r--;

	while (l <= r) {
		if (max(abs(a[l] - valL), abs(a[l] - valR)) > max(abs(a[r] - valL), abs(a[r] - valR))) {
			ret += max(abs(a[l] - valL), abs(a[l] - valR));

			if (abs(a[l] - valL) > abs(a[l] - valR)) {
				valL = a[l];
			} else {
				valR = a[l];
			}

			l++;
		} else {
			ret += max(abs(a[r] - valL), abs(a[r] - valR));

			if (abs(a[r] - valL) > abs(a[r] - valR)) {
				valL = a[r];
			} else {
				valR = a[r];
			}

			r--;
		}
	}

	return ret;
}
int main() {
	cin >> n;

	for (int i = 0; i < n; i++) {
		scanf("%d", &a[i]);
	}

	if (n == 1) {
		cout << 0 << endl;
		return 0;
	}

	sort(a, a + n);

	long long res = solve();

	reverse(a, a + n);

	res = max(res, solve());

	printf("%lld\n", res);
}

