long long calc(const vector<int> &sm, const vector<int> &la) {
	long long ret = 0;
	int m = la.front();
	if (sm.size() > la.size()) {
		rep(i, sm.size()) {
			if (i + 2 >= sm.size())ret += m - sm[i];
			else ret += (m - sm[i]) * 2;
		}
		rep(i, la.size()) {
			if (i < 0)ret += la[i] - m;
			else ret += (la[i] - m) * 2;
		}
	}
	else if( sm.size() < la.size()){
		rep(i, sm.size()) {
			if (i + 0 >= sm.size())ret += m - sm[i];
			else ret += (m - sm[i]) * 2;
		}
		rep(i, la.size()) {
			if (i < 2)ret += la[i] - m;
			else ret += (la[i] - m) * 2;
		}
	}
	else {
		rep(i,sm.size()) {
			if (i + 1 >= sm.size())ret += m - sm[i];
			else ret += (m - sm[i]) * 2;
		}
		rep(i, la.size()) {
			if (i < 1)ret += la[i] - m;
			else ret += (la[i] - m) * 2;
		}
	}
	return ret;
}


