	do
	{
		for (int i = 0; i < SZ(c); ++i)
		{
			vi cur;
			for (int j = 0; j < i; ++j)
				cur.push_back(c[j]);

			vi cur2 = cur;

			for (int j = 0; j < SZ(a); ++j)
			{
