                ma--;
            }
        }else{
            q.push_front(a[mi]);
            mi++;
            if(mi<ma){
                q.push_back(a[ma]);
                ma--;
            }
        }
        turn++;
    }
    ll tmp=0;
    x=q.front(); q.pop_front();
    while(!q.empty()){
        ll y=q.front(); q.pop_front();
        ans += abs(x-y);
        x=y;
    }
    ans = max(ans,tmp);
    cout<<ans<<endl;
    return 0;
}

