// https://atcoder.jp/contests/tenka1-2018/tasks/tenka1_2018_c
#include <bits/stdc++.h>
using namespace std;
#define int long long
#define REP(i, n) FOR(i, 0, n)
#define FOR(i, s, n) for (int i = (s), i##_len = (n); i < i##_len; ++i)
#define ALL(obj) (obj).begin(), (obj).end()
#define ALLR(obj) (obj).rbegin(), (obj).rend()
#define CEIL(a, b) ((a - 1) / b + 1)

void solve() {
    int N;
    cin >> N;
    vector<int> A(N), B(N);
    for (auto &x : A) {
        cin >> x;
    }
    sort(ALL(A));
    int idxS = 0, idxE = N - 1;
    bool flag = false;
    // ソートした後に真ん中で２分割して、小さいグループと大きいグループに対して差分を取る。
    // ただし、端に寄せた2つの値同士は差分を取らないので、中央値付近の2つの値を端に寄せる。
    // Nが奇数なら、中央値との差分が小さいものを端へ寄せる。{1,[2],[3],5,6}
    // Nが偶数なら、中央値付近の2つの値は確定する。{1,[2],[3],5}
    if (N % 2 == 1) {
        if (abs(A[N / 2] - A[N / 2 + 1]) < abs(A[N / 2] - A[N / 2 - 1])) {
            B[0] = A[N / 2];
            B[N - 1] = A[N / 2 + 1];
        } else {
            B[0] = A[N / 2];
            B[N - 1] = A[N / 2 - 1];
            flag = true;
        }
    } else {
        B[0] = A[N / 2];
        B[N - 1] = A[N / 2 - 1];
    }
    FOR(i, 1, N - 1) {
        if (i % 2 != flag) {
            B[i] = A[idxS++];
        } else {
            B[i] = A[idxE--];
        }
    }
    int sum = 0;
    REP(i, N - 1) { sum += abs(B[i] - B[i + 1]); }
    cout << sum << endl;
}

signed main() {
    cin.tie(nullptr)->sync_with_stdio(false);
    solve();
}

