void solve(long long N, std::vector<long long> A) {
  sort(all(A));

  vl arr;
  arr.push_back(A[0]);
  arr.push_back(A[N - 1]);
  ll l = 1;
  ll r = N - 2;
  while (l <= r) {
    if (abs(arr[0] - A[l]) > abs(arr[arr.size() - 1] - A[l])) {
      arr.insert(arr.begin(), A[l]);
    } else {
      arr.push_back(A[l]);
    }
    l++;

    if (r < l) {
      break;
