    if (abs(arr[0] - A[r]) > abs(arr[arr.size() - 1] - A[r])) {
      arr.insert(arr.begin(), A[r]);
    } else {
      arr.push_back(A[r]);
    }
    r--;
  }

  ll ans = 0;
  for (ll i = 0; i < N - 1; i++) {
    ans += abs(arr[i] - arr[i + 1]);
  }
  print(ans);
}

