        	    else w.push_back(a[i]);
        	}
    	    ll v=accumulate(all(w),0ll)*2;
    	    ll z=accumulate(all(q),0ll)*2-q.back()-(q.size()>1?q[q.size()-2]:0);
    	    ans=max(ans,v-z);
	    }
	}
	if(ans<0)cout<<w[INF];
	cout<<ans<<endl;
	return 0;
}

