    for (int i = 0; i < n; ++i)
        cin >> a[i];
    sort(a.begin(), a.end());
    ll res = 0;
    if (n & 1) {
        ll cur = 0;
        for (int i = 0; i < n / 2; ++i) {
            cur -= 2 * a[i];
        }
        for (int i = n / 2; i < n / 2 + 2; ++i) {
            cur += a[i];
        }
        for (int i = n / 2 + 2; i < n; ++i) {
            cur += 2 * a[i];
        }
        res = max(res, cur);
        cur = 0;
        for (int i = 0; i < n / 2 - 1; ++i) {
            cur -= 2 * a[i];
        }
        for (int i = n / 2 - 1; i < n / 2 + 1; ++i) {
            cur -= a[i];
        }
        for (int i = n / 2 + 1; i < n; ++i) {
            cur += 2 * a[i];
        }
        res = max(res, cur);
    }
    else {
        ll cur = 0;
        for (int i = 0; i < n / 2 - 1; ++i) {
            cur -= 2 * a[i];
        }
        cur = cur - a[n / 2 - 1] + a[n / 2];
        for (int i = n / 2 + 1; i < n; ++i)
            cur += 2 * a[i];
        res = max(res, cur);

    }

    cout << res << endl;


}

