int solve(){
	if(N == 2) return abs(A[0]-A[1]);
	if(N == 3) return abs(A[0]-A[2])+abs(A[0]-A[1]);
	int ans = 0;
	int l, r;
	l = r = A[0];
	VI v;
	int i = 0, j = N;
	while(true){
		v.pb(A[--j]);
		if(j-i == 1) break;
		v.pb(A[--j]);
		if(j-i == 1) break;
		v.pb(A[++i]);
		if(j-i == 1) break;
		v.pb(A[++i]);
		if(j-i == 1) break;
	}
	for(int i = 0;i < N-1;i+=2){
		if(i == N-2){
			ans += max(abs(v[(size_t)i]-l), abs(v[(size_t)i]-r));
			break;
		}
		int x = v[(size_t)i];
		int y = v[(size_t)(i+1)];
		if(abs(x-l)+abs(y-r) > abs(y-l)+abs(x-r)){
			ans += abs(x-l)+abs(y-r);
			l = x;
			r = y;
		}
		else {
			ans += abs(y-l)+abs(x-r);
			l = y;
			r = x;
		}
	}
	return ans;
}


