const int MAX_N = 300002;
const int MOD = 998244353;

namespace dsu {
    int lab[MAX_N];

    void init() {
        memset(lab, -1, sizeof(lab));
    }

    int findset(int u) {
        return lab[u]<0 ? u : lab[u]=findset(lab[u]);
    }

    int len(int s) {
        return -lab[findset(s)];
    }

    bool uni(int s, int t) {
        s = findset(s);
        t = findset(t);
        if (s==t)
            return false;
        lab[t] += lab[s];
        lab[s] = t;
        return true;
    }
};

int n, a[MAX_N], nxt[MAX_N], l[MAX_N], r[MAX_N];

