int calc(int v, int k) {
    if (v<k)
        return 0;
    return v-k+1;
}

int dist(int l, int r) {
    if (l<=r)
        return r - l + 1;
    return n - l + r + 1;
}

int64_t solve() {
    a[n+1] = n;
    for (int i=n-1; i>=0; --i) {
        if (a[i]!=a[(i+1)%n])
            nxt[i] = i;
        else
            nxt[i] = nxt[i+1];
    }
    for (int i=n-1; i>=0; --i) {
        if (a[i]!=a[(i+1)%n])
            nxt[i] = i;
        else
            nxt[i] = nxt[(i+1)%n];
    }
    memset(l, -1, sizeof(l));
    memset(r, -1, sizeof(r));
    for (int i=0; i<n; ++i) {
        if (a[i]!=a[(i-1+n)%n]) {
            if (l[a[i]]!=-1)
                return 0;
            l[a[i]] = i;
            r[a[i]] = nxt[i];
        }
    }
    if (a[0]==0 && l[0]==-1) {
        int64_t res = 1;
        for (int i=1; i<=n; ++i)
            res = res * i % MOD;
        return res;
    }
    if (l[0]==-1)
        return 0;
    int k = dist(l[0], r[0]), s = 0;
    int64_t res = 1;
    dsu::init();
    for (int i=0; i<n; ++i) {
        if (l[i]==-1) {
            if (s==calc(n, k))
                res = res * (n - i) % MOD;
            else
                res = res * (s - i) % MOD;
        }
        else if (a[(l[i]-1+n)%n]>i || a[(r[i]+1)%n]>i) {

        }
        else {
            if (dist(l[i], r[i])>k)
                return 0;
            res = res * (k - dist(l[i], r[i]) + 1) % MOD;
        }
        if (l[i]==-1)
            continue;
        for (int j=l[i]; j!=r[i]; j = (j + 1) % n)
            dsu::uni(j, (j+1)%n);
        if (a[(l[i]-1+n)%n]<i) {
            s -= calc(dsu::len((l[i]-1+n)%n), k);
            dsu::uni(l[i], (l[i]-1+n)%n);
        }
        if (a[(r[i]+1)%n]<i) {
            if (dsu::findset(r[i])!=dsu::findset((r[i]+1)%n))
                s -= calc(dsu::len((r[i]+1)%n), k);
            dsu::uni(r[i], (r[i]+1)%n);
        }
        s += calc(dsu::len(l[i]), k);
    }
    return res;
}

