using namespace std;
typedef long long ll;

int main()
{
    int n;
    cin >> n;
    vector<ll> A(n, 0);
    for(int i = 0; i < n; ++i) {
        cin >> A[i];
    }
    sort(A.begin(), A.end());
    int sta = 1, end = n-1;
    ll ans = 0;
    int flag = 1;
    ll pre = A[0];
    while(sta <= end) {
        if(sta == end) {
            if(flag == 1) {
                ans += max(A[end]-pre, A[end]-A[0]);
            }else {
                ans += max(pre-A[sta], A[sta]-A[0]);
            }
            break;
        }
        if(flag == 1) {
            ans += A[end] - pre;
            pre = A[end];
            --end;
        }else {
            ans += pre - A[sta];
            pre = A[sta];
            ++sta;
        }
        flag ^= 1;
    }

    sta = 0;
    end = n-2;
    flag = 1;
    pre = A[n-1];
    ll ans1 = 0;
    while(sta <= end) {
        if(sta == end) {
            if(flag == 1) {
                ans1 += max(pre-A[sta], A[n-1]-A[sta]);
            }else {
                ans1 += max(A[end]-pre, A[n-1]-A[end]);
            }
            break;
        }
        if(flag == 1) {
            ans1 += pre - A[sta];
            pre = A[sta];
            ++sta;
        }else {
            ans1 += A[end] - pre;
            pre = A[end];
            --end;
        }
        flag ^= 1;
    }
    ans = max(ans, ans1);
    cout << ans << endl;
}

