        return a[1] - a[0];
    }
    long long res = 0;
    if (n % 2 == 1) {
        b[0] = a[n / 2];
        b[n - 1] = a[n / 2 - 1];
        int l = 0, r = n - 1;
        for (int i = 1; i + 1 < n; ++i) {
            if (i % 2 == 1) {
                b[i] = a[r--];
