  }
  int ans2 = 0;
  for (int i = 1; i < (int)s.size(); i++) {
    int tmp = t[i] - '0';
    int tmp2 = t[i - 1] - '0';
    ans2 += abs(tmp - tmp2);
  }
  cout << max(ans, ans2) << endl;
#ifdef LOCAL_DEFINE
  cerr << "Time elapsed: " << 1.0 * clock() / CLOCKS_PER_SEC << "s.\n";
  fclose(stream1);
  fclose(stream2);
#endif
  return 0;
}

