long long n;
vector<long long> a;

long long solve();

int main() {
  cin >> n;
  for(int i = 0; i < n; ++i) {
    long long x;
    cin >> x;
    a.push_back(x);
  }
  sort(a.begin(), a.end());
  if(n == 2)
    cout << a[1] - a[0] << endl;
  else
    cout << solve() << endl;
  return 0;
}

long long solve() {
  long long ans = 0, cnt = 0, now, nl, nr;
  nl = a[0];
  nr = a[n - 1];
  ans += nr - nl;
  for(int i = 2; i < n; ++i) {
    long long l, r, now;
    if(i % 2 == 1)
      now = a[n - 1 - i / 2];
    else
      now = a[i / 2];
    l = max(nl - now, now - nl);
    r = max(nr - now, now - nr);
    if(l > r) {
      ans += l;
      nl = now;
    }
    else {
      ans += r;
      nr = now;
    }
  }
  return ans;
}

