int my_get( vi&c, const vi&a, const vi&b)
{
	int ans = 0;

	do
	{
		for (int i = 0; i < SZ(c); ++i)
		{
			vi cur;
			for (int j = 0; j < i; ++j)
				cur.push_back(c[j]);

			vi cur2 = cur;

			for (int j = 0; j < SZ(a); ++j)
			{
				cur.push_back(a[j]);
				cur.push_back(b[j]);
				cur2.push_back(b[j]);
				cur2.push_back(a[j]);
			}

			for (int j = i; j < SZ(c); ++j)
			{
				cur.push_back(c[j]);
				cur2.push_back(c[j]);
			}


			ans = max(ans, my_get(cur));
			ans = max(ans, my_get(cur2));
		}
	} while (next_permutation(ALL(c)));

	return ans;
}


