vector<int> doit(const vector<int> &A)
{
    int N = A.size();
    vector<int> B(N);
    for (int i = 0; i < N/2; i++) {
        B[N/2-1-i] = A[i];
        B[N/2+i] = A[N-1-i];
        if (i % 2) swap(B[N/2-i-i], B[N/2+i]);
    }
    if (N % 2 == 1) B[N-1] = A[N/2];
    return B;
}
Int sumdiff(const vector<int> &A) 
{
    Int diff = 0;
    for (int i = 0; i < A.size()-1; i++) {
        diff += abs((Int)A[i+1] - A[i]);
    }
    return diff;
}
