ll a[N];
void solve(){
    ll n;
    cin>>n;
    for(int i =1;i<=n;i++){
        cin>>a[i];
    }
    sort(a+1,a+n+1);

    vll v;
    ll mid =(n+1)/2;
    v.pb(a[mid]);
    ll l = 1,r = n;
    while(true){
        if(l == mid && r == mid) break;
        else if(l == mid){
            v.pb(a[r]);
            r--;
        }
        else if(r == mid){
            v.pb(a[l]);
            l++;
        }
        else{
            if(abs(v.back()-a[l]) > abs(v.back()-a[r])){
                v.pb(a[l]);
                l++;
            }
            else if(abs(v.back()-a[l]) > abs(v.back()-a[r])) {
                v.pb(a[r]);
                r--;
            }
            else {
                if(abs(l-mid) > abs(r-mid)){
                    v.pb(a[l]);
                    l++;
                }
                else{
                    v.pb(a[r]);
                    r--;
                }
            }
        }

    }
    ll ans =0;
    for(int i=1;i<n;i++){
        ans += abs(v[i]-v[i-1]);
    }
    cout<<ans<<endl;



}  
