using namespace std;

struct Pair {
  Pair(int64_t a, int64_t b) : m_a(a), m_b(b) {}

  bool operator<(const Pair &rhs) const { return Value() > rhs.Value(); }

  int Value() const { return (m_a + m_b) + std::abs(m_a - m_b); }

  int64_t m_a = 0;
  int64_t m_b = 0;
};

struct Sequence {
  Sequence(int64_t left, int64_t right) : m_left(left), m_right(right) {
    m_internal.emplace(left, right);
  }

  int64_t m_left = 0;
  int64_t m_right = 0;
  priority_queue<Pair> m_internal;
};

int main() {
  ios_base::sync_with_stdio(false);

  size_t n;
  cin >> n;

  vector<int64_t> vs(n);
  for (auto &v : vs)
    cin >> v;

  sort(vs.begin(), vs.end());

  assert(vs.size() >= 2);

  Sequence sequence(vs[0], vs[1]);
  int64_t score = vs[1] - vs[0];

  for (size_t i = 2; i < vs.size(); ++i) {
    const int64_t c = vs[i];

    const auto top = sequence.m_internal.top();
    const int64_t toLeft = c - sequence.m_left;
    const int64_t toRight = c - sequence.m_right;
    const int64_t toInternal = 2 * c - top.Value();

    if (toLeft >= toRight && toLeft >= toInternal) {
      sequence.m_internal.emplace(c, sequence.m_left);
      sequence.m_left = c;
      score += toLeft;
    } else if (toRight >= toLeft && toRight >= toInternal) {
      sequence.m_internal.emplace(c, sequence.m_right);
      sequence.m_right = c;
      score += toRight;
    } else {
      sequence.m_internal.pop();
      sequence.m_internal.emplace(top.m_a, c);
      sequence.m_internal.emplace(top.m_b, c);
      score += toInternal;
    }
  }

  cout << score << endl;

  return 0;
}

