            deq.push_front(p1);
            p1++;
            if(p1 <= p2) {
                deq.push_back(p1);
                p1++;
            }
        }
        else {
            deq.push_back(p2);
            p2--;
            if(p2 >= p1) {
                deq.push_front(p2);
                p2--;
            }
        }
        t ^= 1;
    }
    int last = -1;
    ll ans = 0;
    for(auto it : deq) {
        if(last == -1) {
            last = it;
            continue;
        }
        ans += abs(arr[last] - arr[it]);
        last = it;
    }
    return ans;
}

int main() {
    //ifstream cin("A.in");
