i64 bigfirst(const vector<i64>& A) {
    i64 N = SIZE(A);

    auto is = vec_reserve<i64>(N);
    for(i64 i = 2; i < N; i += 2)
        is.emplace_back(i);
    is.emplace_back(0);
    for(i64 i = N%2==0?N-1:N-2; i >= 1; i -= 2)
        is.emplace_back(i);
    DBG(is);

    auto v = vec_make<i64>(N, 0);
    REP(i, N) {
        v[is[i]] = A[i];
    }
    DBG(v);

    i64 res = 0;
    REP(i, N-1) {
        res += abs(v[i+1] - v[i]);
    }

    return res;
}

i64 smallfirst(const vector<i64>& A) {
    i64 N = SIZE(A);

    auto is = vec_reserve<i64>(N);
    for(i64 i = 1; i < N; i += 2)
        is.emplace_back(i);
    is.emplace_back(0);
    for(i64 i = N%2==0?N-2:N-1; i >= 2; i -= 2)
        is.emplace_back(i);
    DBG(is);

    auto v = vec_make<i64>(N, 0);
    REP(i, N) {
        v[is[i]] = A[i];
    }
    DBG(v);

    i64 res = 0;
    REP(i, N-1) {
        res += abs(v[i+1] - v[i]);
    }

    return res;
}

