#define FOR(i, a, b) for(int i=(int)(a); i!=(int)(b); i++)
#define RFOR(i, a, b) for(int i=(int)(a); i!=(int)(b); i--)
#define REP(i, n) FOR(i, 0, n)
using namespace std;
using ll = long long;

ll calc(vector<ll> a, vector<ll> b, int n){
  if (n % 2 == 0){
    vector<ll> c(n);
    for(int i=0, j=0, k=0; i<n/2; i++){
      c[n-2*i-2] = a[j++];
      c[n-2*i-1] = b[k++];
    }

    ll ans = 0;
    REP(i, n-1) ans += abs(c[i+1]-c[i]);

    return ans;
  }
  else{
    vector<ll> c(n);
    if(a.size() < b.size()) swap(a, b);

    if(n == 5){
      swap(a[0], a[1]);
    }
    else if(n > 5){
      swap(a[n/2-1], a[1]);
      swap(a[n/2], a[0]);
    }

    for(int i=0, j=0, k=0; i<n; i++){
      if(i % 2){
        c[i] = b[j++];
      }
      else{
        c[i] = a[k++];
      }
    }

    ll ans = 0;
    REP(i, n-1) ans += abs(c[i+1]-c[i]);

    return ans;
  }
}

int main(){
  int n; cin >> n;
  ll a[n];
  REP(i, n) cin >> a[i];

  sort(a, a+n);

  int b = n/2;
  if(n % 2){
    if(a[n/2+1]-a[n/2] > a[n/2]-a[n/2-1]){
      b = n/2+1;
    }
    else{
      b = n/2;
    }
  }

  vector<ll> x, y;
  for(int i=0; i<n; i++){
    if(i < b){
      x.push_back(a[i]);
    }
    else{
      y.push_back(a[i]);
    }
  }

  cout << calc(x, y, n) << endl;

  return 0;
}

