using namespace std;

long long solve(deque<long long> A)
{
	long long ans = 0;
	sort(A.begin(), A.end());

	long long l = A.back();
	long long r = A.back();
	A.pop_back();

	for (;;) {
		if (A.empty()) break;
		auto a = abs(A.back() - l);
		auto b = abs(A.back() - r);
		auto c = abs(A.front() - l);
		auto d = abs(A.front() - r);

		auto m = max({ a, b, c, d });
		if (m == a) {
			ans += abs(A.back() - l);
			l = A.back();
			A.pop_back();
		}
		else if (m == b) {
			ans += abs(A.back() - r);
			r = A.back();
			A.pop_back();
		}
		else if (m == c) {
			ans += abs(A.front() - l);
			l = A.front();
			A.pop_front();
		}
		else {
			ans += abs(A.front() - r);
			r = A.front();
			A.pop_front();
		}

	}

	return ans;
}

int main()
{
	int N;
	cin >> N;
	deque<long long> A(N);
	for (auto &x : A) {
		cin >> x;
	}
	cout << solve(A) << endl;
}

