#include <algorithm>
#include <cmath>
#include <deque>
#include <iostream>
#include <vector>

int main() {
	int N;
	std::cin >> N;

	std::vector<int> a(N);
	for(int i = 0; i < N; i++) {
		std::cin >> a[i];
	}

	std::sort(a.begin(), a.end());

	int centerIndex = (N - 1) / 2;
	int center = a[centerIndex];
	if(N % 2 == 0 && N >= 4) {
		int fromBack = std::abs(center - a.back()) + std::abs(a[centerIndex + 1] - a[centerIndex - 1]);
		int fromFront = std::abs(center - a.front()) + std::abs(a[centerIndex + 1] - a[centerIndex + 2]);
		if(fromFront > fromBack) {
			std::reverse(a.begin(), a.end());
			centerIndex++;
		}
	}
	a.erase(a.begin() + centerIndex);

	std::deque<int> queue(a.begin(), a.end());

	int left = 0;
	int right = center;
	long long answer = 0;
	while(!queue.empty()) {
		left = right;
		right = queue.back();
		queue.pop_back();
		answer += std::abs(left - right);
		if(queue.empty()) {
			break;
		}
		left = right;
		right = queue.front();
		queue.pop_front();
		answer += std::abs(left - right);
		if(queue.empty()) {
			break;
		}
	}

	std::cout << answer << std::endl;

	return 0;
}

