using namespace std;
using ll = long long;

ll calc(vector<ll> a, vector<ll> b, int n){
  if (n % 2 == 0){
    vector<ll> c(n);
    for(int i=0, j=0, k=0; i<n/2; i++){
      c[n-2*i-2] = a[j++];
      c[n-2*i-1] = b[k++];
    }

    ll ans = 0;
    rep(i, n-1) ans += abs(c[i+1]-c[i]);

    return ans;
  }
  else{
    vector<ll> c(n);
    if(a.size() < b.size()) swap(a, b);

    if(n == 5){
      swap(a[0], a[1]);
    }
    else if(n > 5){
      swap(a[n/2-1], a[0]);
    }

    for(int i=0, j=0, k=0; i<n; i++){
      if(i % 2){
        c[i] = b[j++];
      }
      else{
        c[i] = a[k++];
      }
    }

    ll ans = 0;
  rep(i, n-1) ans += abs(c[i+1]-c[i]);

    return ans;
  }
}

