  vector<ll> x, y;
  for(int i=0; i<n; i++){
    if(i < b){
      x.push_back(a[i]);
    }
    else{
      y.push_back(a[i]);
    }
  }

  ll ans = calc(x, y, n);

  if(n % 2 == 0){
    cout << ans << endl;
    return 0;
  }

  x.clear(); y.clear();

  if(n % 2){
    for(int i=0; i<n; i++){
      if(i <= b){
        x.push_back(a[i]);
      }
      else{
        y.push_back(a[i]);
      }
    }
  }

  cout << max(calc(x, y, n), ans)<< endl;

  return 0;
}

