int main() {
    int N;
    cin >> N;

    ll A[N];
    for (int i = 0; i < N; ++i) {
        cin >> A[i];
    }

    sort(A, A + N);

    ll B[N];

    ll ans = 0;
    if (N % 2) {
        B[0] = A[N / 2];
        for (int i = 0; i < N / 2; ++i) {
            B[i * 2 + 1] = A[N - i - 1];
            B[i * 2 + 2] = A[i];
        }

        for (int i = 0; i < N - 1; ++i) {
            ans += abs(B[i + 1] - B[i]);
        }

        for (int i = 0; i < N / 2; ++i) {
            B[i * 2 + 1] = A[i];
            B[i * 2 + 2] = A[N - i - 1];
        }

        ll tmp = 0;
        for (int i = 0; i < N - 1; ++i) {
            tmp += abs(B[i + 1] - B[i]);
        }

        ans = max(ans, tmp);
    } else {
        B[0] = A[N / 2 - 1];
        B[N - 1] = A[N / 2];
        for (int i = 0; i < N / 2 - 1; ++i) {
            B[i * 2 + 1] = A[N - i - 1];
            B[i * 2 + 2] = A[i];
        }

        for (int i = 0; i < N - 1; ++i) {
            ans += abs(B[i + 1] - B[i]);
        }
    }

    cout << ans << endl;
    return 0;
}

