using namespace std;

int f(vector<int> v) {
	int s = 0, e = v.size() - 1;
	int res = 0;
	int flag = 1;
	int last1 = -1, last2 = -1;
	while (s <= e) {
		if (s == 0) {
			s++;
			last1 = v[0];
			last2 = v[0];
		}
		if (s == e) {
			res += max(abs(v[s] - last1), abs(v[s] - last2));
			break;
		}
		if (flag) {
			e -= 2;
			res += abs(last1 - v[e+2]) + abs(last2 - v[e+1]);
			last2 = v[e+2];
			last1 = v[e+1];
			flag = 0;
		}
		else {
			s += 2;
			res += abs(last1 - v[s-2]) + abs(last2 - v[s-1]);
			last1 = v[s-2];
			last2 = v[s-1];
			flag = 1;
		}
	}
	return res;
}

int main() {
	int n;
	cin >> n;
	vector<int> v;
	for (int i = 0; i < n; i++) {
		int temp;
		scanf("%d", &temp);
		v.push_back(temp);
	}
	sort(v.begin(), v.end());
	int res = f(v);
	// cout << res << " ";
	reverse(v.begin(), v.end());
	// cout << f(v) << " ";
	res = max(res, f(v));
	cout << res;
	return 0;
}

