			ans+=go(lo,hi,left,right,kk+1);
		}
		else if(abs(a[lo]-a[left])==abs(a[lo]-a[right]))
		{
			ans+=max(go(lo,hi,lo,right,kk+1),go(lo,hi,left,lo,kk+1));
