			ans+=go(lo,hi,left,right,kk+1);
		}
	}
	else
	{
		hi--;
		//ol(hi);on;
		ans+=max(abs(a[hi]-a[left]),abs(a[hi]-a[right]));
		if(abs(a[hi]-a[left])>abs(a[hi]-a[right]))
		{
			left=hi;
			ans+=go(lo,hi,left,right,kk+1);
