	int N;
	cin >> N;

	deque<int> A(N);
	rep(i, N) cin >> A[i];

	sort(all(A));

	deque<int> B;
	B.push_back(A[0]);
	A.pop_front();

	int ret = 0;
	while (!A.empty()) {
		int front = A.front();
		int back = A.back();

		int maxDiff = 0;
		int diffFF = abs(front - B.front());
		int diffFB = abs(front - B.back());
		int diffBB = abs(back - B.back());
		int diffBF = abs(back - B.front());

		maxDiff = max(maxDiff, diffFF);
		maxDiff = max(maxDiff, diffFB);
		maxDiff = max(maxDiff, diffBF);
		maxDiff = max(maxDiff, diffBB);

		if (maxDiff == diffFF) {
			A.pop_front();
			B.push_front(front);
			ret += diffFF;
		} else if (maxDiff == diffFB) {
			A.pop_front();
			B.push_back(front);
			ret += diffFB;
		} else if (maxDiff == diffBF) {
			A.pop_back();
			B.push_front(back);
			ret += diffBF;
		} else {
			A.pop_back();
			B.push_back(back);
			ret += diffBB;
		}
	}

	cout << ret << endl;

    return 0;
}

