void solve() {
    int N;
    cin >> N;
    vector<int> A(N), B(N);
    for (auto &x : A) {
        cin >> x;
    }
    sort(ALL(A));
    int idxS = 0, idxE = N - 1;
    bool flag = false;
    if (N % 2 == 1) {
        if (abs(A[N / 2] - A[N / 2 + 1]) < abs(A[N / 2] - A[N / 2 - 1])) {
            B[0] = A[N / 2];
            B[N - 1] = A[N / 2 + 1];
        } else {
            B[0] = A[N / 2];
            B[N - 1] = A[N / 2 - 1];
            flag = true;
        }
    } else {
        B[0] = A[N / 2];
        B[N - 1] = A[N / 2 - 1];
    }
    FOR(i, 1, N - 1) {
        if (i % 2 != flag) {
            B[i] = A[idxS++];
        } else {
            B[i] = A[idxE--];
        }
    }
    int sum = 0;
    REP(i, N - 1) { sum += abs(B[i] - B[i + 1]); }
    cout << sum << endl;
}

