	cin >> N;
	ll sum = 0;
	for (int i = 0; i < N; i++) {
		cin >> arr[i];
		sum += 2*arr[i];
	}
	sort(arr, arr+N, greater<long>());

	ll ans = -1;
	if (N&1) {
		ll cur = sum;
		for (int i = N/2+2; i < N; i++) {
