			cur -= 4*arr[i];
		}
		cur -= arr[N/2-1] + arr[N/2];
		ans = max(ans, cur);
	} else {
		ll cur = sum;
		for (int i = N/2+1; i < N; i++) {
			cur -= 4*arr[i];
		}
		cur -= arr[N/2-1] + 3*arr[N/2];
		ans = cur;
	}
