	b = a;
	deque<ll> r, l;
	r.push_back(a.front());
	a.pop_front();
	l.push_back(b.back());
	b.pop_back();
	bool flag = false;
	while (!a.empty()) {
		if (flag) {
			ll c = a.front();
			a.pop_front();
			if (abs(r.front() - c) >= abs(r.back() - c)) {
				r.push_front(c);
			}
			else {
				r.push_back(c);
			}
			c = b.back();
			b.pop_back();
			if (abs(l.front() - c) >= abs(l.back() - c)) {
				l.push_front(c);
			}
			else {
				l.push_back(c);
			}
		}
		else {
			ll c = a.back();
			a.pop_back();
			if (abs(r.front() - c) >= abs(r.back() - c)) {
				r.push_front(c);
			}
			else {
				r.push_back(c);
			}
			c = b.front();
			b.pop_front();
			if (abs(l.front() - c) >= abs(l.back() - c)) {
				l.push_front(c);
			}
			else {
				l.push_back(c);
			}
		}
