ll solve(std::vector<ll> arr) {
    std::sort(arr.begin(), arr.end());
    std::deque<ll> items;
    for (auto& it : arr) {
        items.push_back(it);
    }
    std::deque<ll> deque;
    deque.push_back(items.front());
    items.pop_front();
    while (!items.empty()) {
        auto back  = items.back();
        auto front = items.front();
        auto back_diff_front  = std::abs(deque.front()-back);
        auto back_diff_back   = std::abs( deque.back()-back);
        auto front_diff_front = std::abs(deque.front()-front);
        auto front_diff_back  = std::abs( deque.back()-front);
        auto max = std::max({
            back_diff_front  ,
            back_diff_back   ,
            front_diff_front ,
            front_diff_back  
        });
        if (max == back_diff_front) {
            items.pop_back();
            deque.push_front(back);
            continue;
        }
        if (max == back_diff_back) {
            items.pop_back();
            deque.push_back(back);
            continue;
        }
        if (max == front_diff_back) {
            items.pop_front();
            deque.push_back(front);
            continue;
        }
        if (max == front_diff_front) {
            items.pop_front();
            deque.push_front(front);
            continue;
        }
    }
    ll prev = deque.front();
    ll answ = 0;
    for (auto& it : deque) {
        answ += std::abs(prev-it);
        prev = it;
    }
    return answ;
}

