fun main(args: Array<String>) {
    val n = readLine()!!.toInt()
    val aList1 = mutableListOf<Int>()
    (1..n).forEach { aList1.add(readLine()!!.toInt()) }
    aList1.sort()
    val aList2 = mutableListOf<Int>()
    aList2.addAll(aList1)
    val l1 = mutableListOf<Int>()
    val l2 = mutableListOf<Int>()
    l1.add(aList1.removeAt(0))
    l2.add(aList2.removeAt(n - 1))
    var turn = true
    while (aList1.size > 0) {
        if (turn) {
            l1.add(0, aList1.removeAt(aList1.size - 1))
            l2.add(0, aList2.removeAt(0))
            if (aList1.size > 0) {
                l1.add(aList1.removeAt(aList1.size - 1))
                l2.add(aList2.removeAt(0))
            }
        } else {
            l1.add(0, aList1.removeAt(0))
            l2.add(0, aList2.removeAt(aList2.size - 1))
            if (aList1.size > 0) {
                l1.add(aList1.removeAt(0))
                l2.add(aList2.removeAt(aList2.size - 1))
            }
        }
        turn = !turn
    }
    val ans1 = (1 until n).map { Math.abs(l1[it] - l1[it - 1]).toLong() }.sum()
    val ans2 = (1 until n).map { Math.abs(l2[it] - l2[it - 1]).toLong() }.sum()
    println(Math.max(ans1, ans2))
}

