                a[i] = in.nextLong();

            Arrays.sort(a);

            ArrayDeque<Long> q = new ArrayDeque<>();
            for (long cn : a) q.add(cn);

            boolean f = true;
            LinkedList<Long> b1 = new LinkedList<>();
            b1.addFirst(q.poll());
            while (q.size() > 0) {
                if (f) {
                    b1.addLast(q.pollLast());
