                } else {
                    b1.addLast(q.pollFirst());
                    if (q.size() > 0) b1.addFirst(q.pollFirst());
                }
                f = !f;
            }

            LinkedList<Long> b2 = new LinkedList<>();
            for (long cn : a) q.add(cn);
            b2.addFirst(q.pollLast());
            while (q.size() > 0) {
