                    b2.addLast(q.pollLast());
                    if (q.size() > 0) b2.addFirst(q.pollLast());
                } else {
                    b2.addLast(q.pollFirst());
                    if (q.size() > 0) b2.addFirst(q.pollFirst());
                }
