            while (q.size() > 0) {
                if (!f) {
                    b4.addFirst(q.pollLast());
                    if (q.size() > 0) b4.addLast(q.pollLast());
                } else {
                    b4.addFirst(q.pollFirst());
                    if (q.size() > 0) b4.addLast(q.pollFirst());
                }
                f = !f;
            }

            long ans1 = 0;
            long ans2 = 0;
            long ans3 = 0;
