import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.Scanner;

public class Main {

     static Scanner scanner;

     public static void main(String[] args) {
         scanner = new Scanner(System.in);

         int N=gi();
         long[] b=new long[N];

         long ans=0;
         for (int i=0;i<N;i++) {
        	 b[i]=gl();
         }
         Arrays.parallelSort(b);

         Deque<Long> q=new ArrayDeque<Long>();
         for (int i=0; i<N;i++) {
        	 q.addFirst(b[i]);
         }

         boolean f=true;
         long bv=q.pollFirst();
         long nv=0;
         while(q.size()>1) {
        	 if(f) {
        		 nv=q.pollLast();
        	 } else {
        		 nv=q.pollFirst();
        	 }
    		 ans+=Math.abs(nv-bv);
    		 bv=nv;
        	 f=!f;
         }
         System.out.println(Math.max(ans+(b[N-1]-q.peek()), ans+Math.abs(bv-q.peek())));

     }

     // 文字列として入力を取得
     public static String gs() {
          return scanner.next();
     }

     // intとして入力を取得
     public static int gi() {
          return Integer.parseInt(scanner.next());
     }

     // longとして入力を取得
     public static long gl() {
          return Long.parseLong(scanner.next());
     }

     // doubleとして入力を取得
     public static double gd() {
          return Double.parseDouble(scanner.next());
     }
}

import java.util.*;
import java.io.BufferedReader;
import java.io.BufferedOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.io.OutputStream;


public class Main {
    void run() {
        Kattio io = new Kattio(System.in, System.out);
        int n = io.getInt();
        long res = 0;
        long[] array = new long[n];
        for (int i = 0; i < n; i++)
            array[i] = io.getLong();
        Arrays.sort(array);
        int l = 1, r = n - 2, front = 0, tail = n-1, cnt=1;
        res += Math.abs(array[front] - array[tail]);
        while (l <= r) {
            if (cnt % 2 == 1) {
                long a = Math.abs(array[l]-array[tail]);
                long b = Math.abs(array[l]-array[front]);
                if (a > b) {
                    res += a;
                    tail = l;
                } else {
                    res += b;
                    front = l;
                } 
                l++;
                cnt++;
            } else {
                long a = Math.abs(array[r]-array[tail]);
                long b = Math.abs(array[r]-array[front]);
                if (a > b) {
                    res += a;
                    tail = r;
                } else {
                    res += b;
                    front = r;
                } 
                cnt++;
                r--;
            }
        }
        System.out.println(res);
    }

    public static void main (String [] args) {
        new Main().run();
    }
}

class Kattio extends PrintWriter {
    public Kattio(InputStream i) {
		super(new BufferedOutputStream(System.out));
		r = new BufferedReader(new InputStreamReader(i));
    }
    public Kattio(InputStream i, OutputStream o) {
		super(new BufferedOutputStream(o));
		r = new BufferedReader(new InputStreamReader(i));
    }

    public boolean hasMoreTokens() {
		return peekToken() != null;
    }

    public int getInt() {
		return Integer.parseInt(nextToken());
    }

    public double getDouble() { 
		return Double.parseDouble(nextToken());
    }

    public long getLong() {
		return Long.parseLong(nextToken());
    }

    public String getWord() {
		return nextToken();
    }

    private BufferedReader r;
    private String line;
    private StringTokenizer st;
    private String token;

    private String peekToken() {
	if (token == null) 
	    try {
		      while (st == null || !st.hasMoreTokens()) {
		    	line = r.readLine();
		    	if (line == null) return null;
		    	st = new StringTokenizer(line);
			}
				token = st.nextToken();
	    	} catch (IOException e) { }
		return token;
    }

    private String nextToken() {
		String ans = peekToken();
		token = null;
		return ans;
    }
}

import java.util.*;

public class Main {
    static Scanner scanner = new Scanner(System.in);

    public static void main(String[]$) {
        int n = scanner.nextInt();
        Deque<Long> deque1 = new ArrayDeque<>();
        Deque<Long> deque2 = new ArrayDeque<>();
        long[] a = new long[n];
        long[] b = new long[n];
        long[] c = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = scanner.nextInt();
            deque1.add(a[i]);
            deque2.add(a[i]);
        }
        Arrays.sort(a);
        b[0] = c[0] = a[n / 2];
        b[n - 1] = c[n - 1] = n % 2 == 0 ? a[n / 2 - 1] : a[n / 2] - a[n / 2 - 1] > a[n / 2 + 1] - a[n / 2] ? a[n / 2 + 1] : a[n / 2 - 1];
        deque1.remove(b[0]);
        deque1.remove(b[n - 1]);
        deque2.remove(b[0]);
        deque2.remove(b[n - 1]);

        boolean f = true;
        for (int i = 1; i < n - 1; i++) {
            long j = f ? deque1.pollFirst() : deque1.pollLast();
            long k = f ? deque2.pollLast() : deque2.pollFirst();
            b[i] = j;
            c[i] = k;
            f = !f;
        }

        long ans1 = 0, ans2 = 0;
        for (int i = 1; i < n; i++) {
            ans1 += Math.abs(b[i - 1] - b[i]);
            ans2 += Math.abs(c[i - 1] - c[i]);
        }

        System.out.println(Math.max(ans1, ans2));
    }
}

import java.util.*;
import java.awt.*;

public class Main {
    public static void main(String args[]) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextLong();
        }

        Arrays.sort(a);

        long front = a[0];
        long back = a[0];
        int count = 1;
        int go = -1;
        int point = 0;
        long ans = 0;

        while (count < n) {
            long tmp = a[point];
            if (go == -1) {
                tmp = a[n-1-point];
            }

            if (Math.abs(tmp - front) > Math.abs(tmp - back)) {
                ans += Math.abs(tmp - front);
                front = tmp;
            } else if (Math.abs(tmp - front) < Math.abs(tmp - back)) {
                ans += Math.abs(tmp - back);
                back = tmp;
            } else {
                if (front == back) {
                    ans += Math.abs(tmp - front);
                    front = tmp;
                } else if (go == 1) {
                    if (front < back) {
                        ans += Math.abs(tmp - back);
                        back = tmp;
                    } else {
                        ans += Math.abs(tmp - front);
                        front = tmp;
                    }
                } else {
                    if (front > back) {
                        ans += Math.abs(tmp - back);
                        back = tmp;
                    } else {
                        ans += Math.abs(tmp - front);
                        front = tmp;
                    }
                }
            }

            if (go == -1) point++;
            go *= -1;
            count++;
        }

        System.out.println(ans);
    }
}

