// import java.awt.Point;

public class Main {
    InputStream is;
    PrintWriter out;
    String INPUT = "";

    static int mod = 1_000_000_007;
    long inf = Long.MAX_VALUE;

    void solve(){
        int n = ni();
        int[] a = new int[n];
        for(int i = 0; i < n; i++){
            a[i] = ni();
        }
        long ans = 0;
        Arrays.sort(a);
        if(n==2){
            out.println(Math.abs(a[1]-a[0]));
            return;
        }
        for(int i = n/2-1; i <= n/2; i++){
            int[] b = new int[n-1];
            int k = 0;
            for(int j = 0; j < n-1; j++){
                if(k==i) k++;
                b[j] = a[k];
                k++;
                // out.print(mb[j]);
            }
            Arrays.sort(b);
            long res = 0;
            res = Math.abs(a[n-1]-a[i]);
            res += func(b,n-2,n);
            ans = Math.max(ans, res);
            res = Math.abs(a[0]-a[i]);
            res += func(b,0,n);
            ans = Math.max(ans, res);
        }
        out.println(ans);
    }

    long func(int[] b, int c, int n){
        long ans = 0;
        int next = n-2;
        int prev = 0;
        boolean[] seen = new boolean[n-1];
        if(c==n-2){
            prev = n-2;
            next = 0;
        }
        seen[prev] = true;
        while(true){
            ans += Math.abs(b[next]-b[prev]);
            seen[next] = true;
            int tmp = next;
            if(next>prev){
                next = prev+1;
            }
            else{
                next = prev-1;
            }
            prev = tmp;
            // out.println(next+" "+prev+" "+ans);
            if(seen[next]) break;
        }
        return ans;
    }

    void run() throws Exception
    {
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);
        long s = System.currentTimeMillis();
        solve();
        out.flush();
        if(!INPUT.isEmpty())tr(System.currentTimeMillis()-s+"ms");
    }

    public static void main(String[] args) throws Exception { new Main().run(); }

    private byte[] inbuf = new byte[1024];
    private int lenbuf = 0, ptrbuf = 0;

    private int readByte()
    {
        if(lenbuf == -1)throw new InputMismatchException();
        if(ptrbuf >= lenbuf){
            ptrbuf = 0;
            try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
            if(lenbuf <= 0)return -1;
        }
        return inbuf[ptrbuf++];
    }

    private boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
    private int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

    private double nd() { return Double.parseDouble(ns()); }
    private char nc() { return (char)skip(); }

    private String ns()
    {
        int b = skip();
        StringBuilder sb = new StringBuilder();
        while(!(isSpaceChar(b) && b != ' ')){
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    private char[] ns(int n)
    {
        char[] buf = new char[n];
        int b = skip(), p = 0;
        while(p < n && !(isSpaceChar(b))){
            buf[p++] = (char)b;
            b = readByte();
        }
        return n == p ? buf : Arrays.copyOf(buf, p);
    }

    private char[][] nm(int n, int m)
    {
        char[][] map = new char[n][];
        for(int i = 0;i < n;i++)map[i] = ns(m);
        return map;
    }

    private int[] na(int n)
    {
        int[] a = new int[n];
        for(int i = 0;i < n;i++)a[i] = ni();
        return a;
    }

    private int ni()
    {
        int num = 0, b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private long nl()
    {
        long num = 0;
        int b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private static void tr(Object... o) { System.out.println(Arrays.deepToString(o)); }

}

import java.util.Arrays;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int N = scanner.nextInt();
        int[] A = new int[N];

        for (int i = 0; i < N; i++) {
            A[i] = scanner.nextInt();
        }
        Arrays.sort(A); // 昇順

        int[] B = new int[N];
        if (N == 3) {
            B[1] = A[0];
            B[2] = A[1];
            B[0] = A[2];
        } else {
            int temp;
            int min;
            int max;
            int prev;
            int loop;
            if (N%2 == 0) {
                // 偶数
                temp = N/2;
                loop = temp;
                min = loop - 1;
            } else {
                // 奇数
                temp = N/2;
                if (temp % 2 == 0) {
                    loop = N / 2;
                    min = loop;
                    loop++;
                } else {
                    loop = (int) Math.ceil((float)N/(float)2);
                    min = loop - 2;
                }
            }
            max = min;
            B[min] = A[0];
            prev = min;
            for (int i = 1; i < loop; i++) {
                if (min == prev) {
                    max += 2;
                    B[max] = A[i];
                    prev = max;
                } else {
                    min -= 2;
                    B[min] = A[i];
                    prev = min;
                }
            }

            if (N%2==0) {
                // 偶数
                min = temp;
                loop = (int) Math.ceil((float)N/(float)2);
            } else {
                // 奇数
                if (temp % 2 == 0) {
                    min = N/2 + 1;
                    loop = (int) Math.floor((float)N/(float)2);
                } else {
                    min = N/2;
                    loop = N / 2;
                }
            }
            max = min;
            B[min] = A[A.length - 1];
            prev = max;
            for (int i = 1; i < loop; i++) {
                if (max == prev) {
                    min -= 2;
                    B[min] = A[A.length - 1 - i];
                    prev = min;
                } else {
                    max += 2;
                    B[max] = A[A.length - 1 - i];
                    prev = max;
                }
            }
        }

        long result = 0;
        for (int i = 0; i < B.length-1; i++) {
            result += Math.abs(B[i] - B[i+1]);
        }
        System.out.println(result);
    }

}

