                ans += a[n - i - 1] - a[n / 2 - i - 1] + (i == n / 2 - 1 ? 0 : a[n - i - 1] - a[n / 2 - i - 2]);
            } else if (a[n / 2 + 1] - a[n / 2] == a[n / 2] - a[n / 2 - 1]) {
                ans += 2 * a[n - i - 1] - a[i] - a[i + 1];
            } else if (a[n / 2 + 1] - a[n / 2] > a[n / 2] - a[n / 2 - 1]) {
                ans += 2 * a[n - i - 1] - (i == 0 ? a[n / 2] : a[i - 1]) - a[i];
            } else {
                ans += -2 * a[i] + (i == 0 ? a[n - 1] : a[n / 2 + i - 1]) + a[n / 2 + i];
            }
        }
        System.out.println(ans);
    }
}

