	static class TaskX {

		public void solve(int testNumber, InputReader in, PrintWriter out) {

			int n = in.nextInt();
			int[] a = in.nextIntArray(n);
			Deque<Integer> from = new ArrayDeque<Integer>();
			Deque<Integer> to = new ArrayDeque<Integer>();

			Arrays.sort(a);
			for (int i : a) {
				from.addLast(i);
			}

			to.addFirst(from.removeFirst());

			int count = 0;
			while (!from.isEmpty()) {
				if (count % 2 == 0) {
					if (!from.isEmpty()) {
						int num = from.removeLast();
						to.addFirst(num);
					}
					if (!from.isEmpty()) {
						int num = from.removeLast();
						to.addLast(num);
					}
				} else {
					if (!from.isEmpty()) {
						int num = from.removeFirst();
						to.addFirst(num);
					}
					if (!from.isEmpty()) {
						int num = from.removeFirst();
						to.addLast(num);
					}
				}
				count++;
			}

			int[] b = new int[n];
			for (int i = 0; i < n; i++) {
				b[i] = to.removeFirst();
			}

			long ans = 0;
			for (int i = 0; i < n-1; i++) {
				ans += abs(b[i+1] - b[i]);
			}
			out.println(ans);
		}
