    System.out.println(Main.calcMax(Main.permute(arr)));
  	return 0;
  }

  public static int calcMax(ArrayList<ArrayList<Integer>> ar) {
  	int max = 0;
  	for(ArrayList<Integer> i: ar) {
      int tmp = 0;
      for(int n=0; n<i.size(); n++) {
      	if(n==0)
        	continue;
        tmp += Math.abs(i.get(n) - i.get(n - 1));
      }
      if(max < tmp)
      	max = tmp;
    }
    return max;
  }
}

