    static void getDiv(Map<Integer, Integer> map, int n) {
        int sqrt = (int) Math.sqrt(n);
        for (int i = sqrt; i >= 2; i--) {
            if (n % i == 0) {
                getDiv(map, i);
                getDiv(map, n / i);
                return;
            }
        }
        map.put(n, map.getOrDefault(n, 0) + 1);
    }

    @SuppressWarnings("unchecked")
    private static void solve() {
        int n = nextInt();
        int a[] = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = nextInt();
        }
        Arrays.sort(a);
        boolean low = false;
        int i = 1;
        int j = n - 1;
        long ans = 0;
        int last = a[0];
        int first = a[0];
        while (i <= j) {
            if (i == j) {
                ans += Math.max(Math.abs(a[i] - first), Math.abs(a[i] - last));
                break;
            }
            int l, f;
            if (!low) {
                l = a[j--];
                ans += l - last;
                f = a[j--];
                ans += f - first;
            } else {
                l = a[i++];
                ans += last - l;
                f = a[i++];
                ans += first - f;
            }
            last = l;
            first = f;
            low = !low;
        }
        System.out.println(ans);
    }

    static long gcd(long a, long b) {
        if (a < b) {
            a ^= b;
            b ^= a;
            a ^= b;
        }
        while (b != 0) {
            long tmp = a % b;
            a = b;
            b = tmp;
        }
        return a;
    }

