            long[] a = new long[n];

            for (int i = 0; i < n; i++)
                a[i] = in.nextLong();

            Arrays.sort(a);

            ArrayDeque<Long> q = new ArrayDeque<>();
            for (long cn : a) q.add(cn);

            boolean f = true;
            LinkedList<Long> b = new LinkedList<>();
            b.addFirst(q.poll());
            while (q.size() > 0) {
