    public static void solve() throws Exception {
        //longを忘れるなオーバーフローするぞ
        N = ni();
        A = nia(N);
        //奇数個
        if (N % 2 == 1) {
            revSort(A);
            long res1 = 0;
            for (int i = 0; i < N / 2 - 1; i++) {
                res1 += A[i] * 2;
            }
            res1 += A[N / 2 - 1];
            res1 += A[N / 2];
            for (int i = N / 2 + 1; i < N; i++) {
                res1 -= A[i] * 2;
            }
            long res2 = 0;
            for (int i = 0; i < N / 2; i++) {
                res2 += A[i] * 2;
            }
            sort(A);
            //小さいのはなるべく引く
            for (int i = 0; i < (N / 2 - 1); i++) {
                res2 -= A[i] * 2;
            }
            res2 -= A[N / 2 - 1];
            res2 -= A[N / 2];
            System.out.println(max(res1, res2));
        } else if (N != 2) {
            //大きくないのと、小さくないの以外２
            revSort(A);
            long res1 = 0;
            for (int i = 0; i < N / 2 - 1; i++) {
                res1 += A[i] * 2;
            }
            res1 += A[N / 2 - 1];
            sort(A);
            for (int i = 0; i < (N / 2 - 1); i++) {
                res1 -= A[i] * 2;
            }
            res1 -= A[N / 2 - 1];
            System.out.println(res1);
        } else {
            //N=2
            System.out.println(Math.abs(A[0]-A[1]));
        }
    }

