import java.util.*;
import java.io.BufferedReader;
import java.io.BufferedOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.io.OutputStream;


public class Main {
    void run() {
        Kattio io = new Kattio(System.in, System.out);
        int n = io.getInt();
        if (n == 1) {
            System.out.println(0);
            return;
        }
        long res = 0;
        long[] array = new long[n];
        for (int i = 0; i < n; i++)
            array[i] = io.getLong();
        Arrays.sort(array);
        int l = 1, r = n - 2, front = n-1, tail = 0, cnt=1;
        res += Math.abs(array[front] - array[tail]);
        while (l <= r) {
            if (cnt % 2 == 1) {
                long a = Math.abs(array[l]-array[tail]);
                long b = Math.abs(array[l]-array[front]);
                if (a > b) {
                    res += a;
                    tail = l;
                } else {
                    res += b;
                    front = l;
                }
                l++;
                cnt++;
            } else {
                long a = Math.abs(array[r]-array[tail]);
                long b = Math.abs(array[r]-array[front]);
                if (a > b) {
                    res += a;
                    tail = r;
                } else {
                    res += b;
                    front = r;
                }
                cnt++;
                r--;
            }
        }
        System.out.println(res);
    }

    public static void main (String [] args) {
        new Main().run();
    }
}

class Kattio extends PrintWriter {
    public Kattio(InputStream i) {
		super(new BufferedOutputStream(System.out));
		r = new BufferedReader(new InputStreamReader(i));
    }
    public Kattio(InputStream i, OutputStream o) {
		super(new BufferedOutputStream(o));
		r = new BufferedReader(new InputStreamReader(i));
    }

    public boolean hasMoreTokens() {
		return peekToken() != null;
    }

    public int getInt() {
		return Integer.parseInt(nextToken());
    }

    public double getDouble() { 
		return Double.parseDouble(nextToken());
    }

    public long getLong() {
		return Long.parseLong(nextToken());
    }

    public String getWord() {
		return nextToken();
    }

    private BufferedReader r;
    private String line;
    private StringTokenizer st;
    private String token;

    private String peekToken() {
	if (token == null) 
	    try {
		      while (st == null || !st.hasMoreTokens()) {
		    	line = r.readLine();
		    	if (line == null) return null;
		    	st = new StringTokenizer(line);
			}
				token = st.nextToken();
	    	} catch (IOException e) { }
		return token;
    }

    private String nextToken() {
		String ans = peekToken();
		token = null;
		return ans;
    }
}

