	static int[] mw8 = { -1, 0, 1, -1, 1, -1, 0, 1 };

	static class TaskX {

		public void solve(int testNumber, InputReader in, PrintWriter out) {

			int n = in.nextInt();
			long[] a = in.nextLongArray(n);

			Arrays.sort(a);

			long ans = 0;
			if (n % 2 == 0) {
				for (int i = 0; i < n; i++) {
					if (i < n/2) {
						ans -= a[i] * 2;
					} else {
						ans += a[i] * 2;
					}
				}
				ans += a[n/2-1];
				ans -= a[n/2];
			} else {
				long ans1 = 0, ans2 = 0;
				for (int i = 0; i < n; i++) {
					if (i <= n/2) {
						ans1 -= a[i] * 2;
					} else {
						ans1 += a[i] * 2;
					}
					if (i < n/2) {
						ans2 -= a[i] * 2;
					} else {
						ans2 += a[i] * 2;
					}
				}
				ans1 += a[n/2-1];
				ans1 += a[n/2];
				ans2 -= a[n/2];
				ans2 -= a[n/2+1];
				ans = Math.max(ans1, ans2);
			}
			out.println(ans);
		}
	}

