                ans += Math.max(Math.abs(a[i] - first), Math.abs(a[i] - last));
                break;
            }
            long l, f;
            if (!low) {
                l = a[j--];
                ans += l - last;
                f = a[j--];
                ans += f - first;
            } else {
                l = a[i++];
                ans += last - l;
                f = a[i++];
                ans += first - f;
            }
            last = l;
            first = f;
            low = !low;
        }
        System.out.println(ans);
    }

    static long gcd(long a, long b) {
        if (a < b) {
            a ^= b;
            b ^= a;
            a ^= b;
        }
        while (b != 0) {
            long tmp = a % b;
            a = b;
            b = tmp;
        }
        return a;
    }

