class Solution
{
    static long Calc(IEnumerable<long> array)
    {
        var list = new LinkedList<long>();
        var a = new LinkedList<long>(array);
        list.AddFirst(a.First());
        a.RemoveFirst();
        while (a.Count > 0)
        {
            list.AddLast(a.Last());
            a.RemoveLast();
            if (a.Count == 0)
            {
                break;
            }
            list.AddFirst(a.Last());
            a.RemoveLast();

            if (a.Count == 0)
            {
                break;
            }
            list.AddLast(a.First());
            a.RemoveFirst();
            if (a.Count == 0)
            {
                break;
            }
            list.AddFirst(a.First());
            a.RemoveFirst();
        }

        long sum = 0;
        var prev = list.First();
        foreach (var x in list.Skip(1))
        {
            sum += Math.Abs(x - prev);
            prev = x;
        }

        return sum;
    }

    static void Main()
    {
        var input = Console.In.ReadToEnd().Split(new string[] { Environment.NewLine }, StringSplitOptions.None).Where(s => s != "").Select(long.Parse).ToArray();
        var N = input[0];
        var A = input.Skip(1).ToArray();

        Array.Sort(A);
        var a = Calc(A);
        var b = Calc(A.AsEnumerable().Reverse());

        var sum = Math.Max(a, b);
        Console.WriteLine(sum);
    }
}

