class Solution
{
    static long Calc(long[] array)
    {
        long sum = 0;

        var i = 0;
        var j = array.Length - 1;
        var left = array[i];
        var right = array[i];
        i++;
        while (i <= j)
        {
            sum += Math.Abs(left - array[j]);
            left = array[j];
            j--;
            if (i > j)
            {
                break;
            }

            sum += Math.Abs(right - array[j]);
            right = array[j];
            j--;
            if (i > j)
            {
                break;
            }

            sum += Math.Abs(left - array[i]);
            left = array[i];
            i++;
            if (i > j)
            {
                break;
            }

            sum += Math.Abs(right - array[i]);
            right = array[i];
            i++;
            if (i > j)
            {
                break;
            }
        }

        return sum;
    }

