using System;
using System.Collections.Generic;
using System.Linq;

class Solution
{
    static void Main()
    {
        var N = int.Parse(Console.ReadLine());
        var A = new long[N];
        for (int i = 0; i < N; i++)
        {
            A[i] = long.Parse(Console.ReadLine());
        }

        var list = new LinkedList<long>();
        var a = new LinkedList<long>(A.OrderBy(i => i));
        list.AddFirst(a.First());
        a.RemoveFirst();
        while (a.Count > 0)
        {
            list.AddLast(a.Last());
            a.RemoveLast();
            if (a.Count == 0)
            {
                break;
            }
            list.AddFirst(a.Last());
            a.RemoveLast();

            if (a.Count == 0)
            {
                break;
            }
            list.AddLast(a.First());
            a.RemoveFirst();
            if (a.Count == 0)
            {
                break;
            }
            list.AddFirst(a.First());
            a.RemoveFirst();
        }

        long sum = 0;
        var prev = list.First();
        foreach(var x in list.Skip(1))
        {
            sum += Math.Abs(x -prev);
            prev = x;
        }

        Console.WriteLine(sum);
    }
}

