class Deque<T> :IEnumerable<T>{


	T[] arr;
	int head, tail;
	int count;
	int capacity;

	public int Capacity{
		get{ return capacity;}
	}
	public int Count{
		get{ return count;}
	}

	public T First {
		get { 
			if(count == 0) throw new Exception("empty");
			return arr[head];
		}
	}
	public T Last {
		get { 
			if(count == 0) throw new Exception("empty");
			return arr[tail]; 
		}
	}

	public T this [int pos]{
		get{
			if(pos >= count) throw new ArgumentOutOfRangeException("out of range");
			return arr[(head + pos) % arr.Length];
		}
	}

	public IEnumerator<T> GetEnumerator(){
		for(int i=0;i<count;i++){
			yield return arr[(head + i) % arr.Length];
		}
	}

	IEnumerator IEnumerable.GetEnumerator() {
		return this.GetEnumerator();
	}

	public void AddFirst(T elem){
		if(count == capacity) {
			Twice();
		}

		head = count == 0 ? head : (head - 1);
		if(head < 0) head = arr.Length - 1;
		arr[head] = elem;
		count++;

	}

	public void RemoveFirst(){
		if(count == 0) throw new Exception("empty");
		arr[head] = default(T);
		count--;
		head = count == 0 ? head : head + 1; if(head == arr.Length) head = 0;
	}

	public void AddLast(T elem){
		if(count == capacity) {
			Twice();
		}

		tail = count == 0 ? tail : (tail + 1);
		if(tail >= arr.Length) tail = 0;
		arr[tail] = elem;
		count++;

	}

	public void RemoveLast(){
		if(count == 0) throw new Exception("empty");
		arr[tail] = default(T);
		count--;
		tail = count == 0 ? tail : tail - 1; if(tail < 0) tail = arr.Length - 1;
	}

	void Twice(){

		T[] nxt = new T[arr.Length * 2];
		int nhead = arr.Length / 2;
		for(int i = 0; i < count; i++) nxt[nhead + i] = arr[(head + i) % arr.Length];
		head = nhead;
		tail = head + count - 1;
		arr = nxt; 
		capacity = arr.Length;
	}

	public Deque() {
		Init(256);
	}

	public Deque(int cap_){
		Init(cap_);
	}

	void Init(int cap){
		if(cap < 0) cap = 256;
		arr = new T[cap];
		capacity = cap;
		head = cap / 2;
		tail = cap / 2;
		count = 0;
	}


}

using System;
using System.Collections.Generic;
using System.Linq;

class Solution
{
    static long Calc(long[] array)
    {
        long sum = 0;

        var i = 0;
        var j = array.Length - 1;
        var left = array[i];
        var right = array[i];
        i++;
        while (i <= j)
        {
            sum += Math.Abs(left - array[j]);
            left = array[j];
            j--;
            if (i > j)
            {
                break;
            }

            sum += Math.Abs(right - array[j]);
            right = array[j];
            j--;
            if (i > j)
            {
                break;
            }

            sum += Math.Abs(left - array[i]);
            left = array[i];
            i++;
            if (i > j)
            {
                break;
            }

            sum += Math.Abs(right - array[i]);
            right = array[i];
            i++;
            if (i > j)
            {
                break;
            }
        }

        return sum;
    }

    static void Main()
    {
        var input = Console.In.ReadToEnd().Split(new string[] { Environment.NewLine }, StringSplitOptions.None).Where(s => s != "").Select(long.Parse).ToArray();
        var N = input[0];
        var A = input.Skip(1).ToArray();

        Array.Sort(A);
        var a = Calc(A);
        var b = Calc(A.AsEnumerable().Reverse().ToArray());

        var sum = Math.Max(a, b);
        Console.WriteLine(sum);
    }
}

