class Solution
{
    static long Calc(IEnumerable<long> array)
    {
        var list = new LinkedList<long>();
        var a = new LinkedList<long>(array);
        list.AddFirst(a.First());
        a.RemoveFirst();
        while (a.Count > 0)
        {
            list.AddLast(a.Last());
            a.RemoveLast();
            if (a.Count == 0)
            {
                break;
            }
            list.AddFirst(a.Last());
            a.RemoveLast();

            if (a.Count == 0)
            {
                break;
            }
            list.AddLast(a.First());
            a.RemoveFirst();
            if (a.Count == 0)
            {
                break;
            }
            list.AddFirst(a.First());
            a.RemoveFirst();
        }

        long sum = 0;
        var prev = list.First();
        foreach (var x in list.Skip(1))
        {
            sum += Math.Abs(x - prev);
            prev = x;
        }

        return sum;
    }

    static void Main()
    {
        var N = int.Parse(Console.ReadLine());
        var A = new long[N];
        for (int i = 0; i < N; i++)
        {
            A[i] = long.Parse(Console.ReadLine());
        }
        Array.Sort(A);
        var a = Calc(A);
        var b = Calc(A.AsEnumerable().Reverse());

        var sum = Math.Max(a, b);
        Console.WriteLine(sum);
    }
}

