        static long Solve(int N, long[] A)
        {
            var k1 = new int[N];
            var k2 = new int[N];
            for (int i = 0; i < N; ++i)
            {
                var k = (i == 0 || i == N - 1) ? 1 : 2;
                if (i % 2 == 0)
                {
                    k1[i] = -k;
                    k2[i] =  k;
                }
                else
                {
                    k1[i] =  k;
                    k2[i] = -k;
