            Array.Sort(A);
            long sum1 = 0;
            long sum2 = 0;
            for (int i = 0; i < N; ++i)
            {
                sum1 += A[i] * k1[i];
                sum2 += A[i] * k2[i];
            }
            return Math.Max(sum1, sum2);
