class Solution
{
    static void Main()
    {
        var N = int.Parse(Console.ReadLine());
        var A = new long[N];
        for (int i = 0; i < N; i++)
        {
            A[i] = long.Parse(Console.ReadLine());
        }

        var list = new List<long>();
        var a = A.OrderBy(i => i).ToList();
        list.Add(a.First());
        a.RemoveAt(0);
        while (a.Count > 0)
        {
            list.Insert(0, a.Last());
            a.RemoveAt(a.Count - 1);
            if (a.Count == 0)
            {
                break;
            }
            list.Add(a.Last());
            a.RemoveAt(a.Count - 1);

            if (a.Count == 0)
            {
                break;
            }
            list.Insert(0, a.First());
            a.RemoveAt(0);
            if (a.Count == 0)
            {
                break;
            }
            list.Add(a.First());
            a.RemoveAt(0);
        }

        long sum = 0;
        for (int i = 0; i < list.Count - 1; i++)
        {
            sum += Math.Abs(list[i] - list[i + 1]);
        }

        Console.WriteLine(sum);
    }
}

