public class Program
{
  public static void Main()
  {
    var n = int.Parse(Console.ReadLine());
    var xs = new long[n];
    for (int i = 0; i < xs.Length; i++)
    {
      xs[i] = int.Parse(Console.ReadLine());
    }

    Array.Sort(xs);
    var ys = new LinkedList<long>(xs);
    var k = new long[2];
    for (int sym = 0; sym < k.Length; sym++)
    {
      var first = ys.First.Value;
      var last = first;
      var firstIsFirst = true;
      ys.RemoveFirst();
      for (int i = 0; ys.Any(); i++)
      {
        var y = i % 2 == 0 ? ys.Last : ys.First;
        ys.Remove(y);
        var f = Math.Abs(first - y.Value);
        var l = Math.Abs(last - y.Value);
        if (f > l && (i % 2 == 0 || !firstIsFirst || !ys.Any()))
        {
          k[sym] += f;
          first = y.Value;
          firstIsFirst = i % 2 != 0;
        }
        else
        {
          k[sym] += l;
          last = y.Value;
        }
      }
      ys = new LinkedList<long>(xs.Reverse());
    }
    Console.WriteLine(k.Max());
  }

  static long Naive(int i, long[] xs)
  {
    if (i >= xs.Length - 1)
    {
      return xs.Skip(1).Zip(xs, (x, y) => Math.Abs(x - y)).Sum();
    }

    var k = 0L;
    for (int j = i; j < xs.Length; j++)
    {
      var t = xs[j];
      xs[j] = xs[i];
      xs[i] = t;
      k = Math.Max(k, Naive(i + 1, xs));
      t = xs[j];
      xs[j] = xs[i];
      xs[i] = t;
    }
    return k;
  }
}

