      answer += differences[l/2] * l;
      for(long i = (l+1)/2; i < l; i++)
      {
        answer += differences[i] * 2 * (l-i);
      }
    }else
    {
      for(long i = 0; i <= l/2 - 1; i++)
      {
        answer += differences[i] * 2 * (i+1);
      }
      answer -= Math.Min(differences[l/2 - 1], differences[l/2]);

      for(long i = l/2; i < l; i++)
      {
        answer += differences[i] * 2 * (l-i);
      }
    }

		Console.WriteLine(answer);//WriteLineをWriteとすると、改行なしで出力。
	}
}

