        int[] A = new int[N];
        for (int i = 0; i < N; i++) A[i] = NextInt();

        Array.Sort(A);

        //大きいほうから
        int L = A[N - 1];
        int R = A[N - 1];
        int max_index = N - 2;
        int min_index = 0;
        long ans1 = 0;
        for (int i = 1; i < N; i++)
        {
            if (i % 4 == 1 || i % 4 == 2)
            {
                //小さいの付与
                int _L = Math.Abs(L - A[min_index]);
                int _R = Math.Abs(R - A[min_index]);
                ans1 += Math.Max(_L, _R);
                if (_L > _R) L = A[min_index];
                else R = A[min_index];
                min_index++;
            }
            else if (i % 4 == 3 || i % 4 == 0)
            {
                //大きいの
                int _L = Math.Abs(L - A[max_index]);
                int _R = Math.Abs(R - A[max_index]);
                ans1 += Math.Max(_L, _R);
                if (_L > _R) L = A[max_index];
                else R = A[max_index];
                max_index--;
            }
        }

        L = A[0];
        R = A[0];
        max_index = N - 1;
        min_index = 1;
        long ans2 = 0;
        for (int i = 1; i < N; i++)
        {
            if (i % 4 == 3 || i % 4 == 0)
