            {
                //大きいの
                int _L = Math.Abs(L - A[max_index]);
                int _R = Math.Abs(R - A[max_index]);
                ans2 += Math.Max(_L, _R);
                if (_L > _R) L = A[max_index];
                else R = A[max_index];
                max_index--;
            }
        }

        Console.WriteLine(Math.Max(ans1, ans2));
    }
