        public Problem(bool isGCJ, Scanner scanner) : this(isGCJ, scanner, new Printer()) { }
        public Problem(bool isGCJ, Printer printer) : this(isGCJ, new Scanner(), printer) { }
        public void Solve()
        {
            if (IsGCJ) for (var i = 0; i < Repeat; i++) { Read(); pr.Write("Case #" + (i + 1) + ": "); SolveOne(); }
            else SolveOne();
        }
        public void Dispose()
        {
            sc.Dispose();
            pr.Dispose();
        }
        public int Size { get { return 1; } }
        public const long Mod = 1000000007;

        // 使用する変数をここに書く
        // string S;
        // int a;
        int n;
        int[] a, ls;
        /// <summary>
        /// 読み込み処理をここに書く
        /// </summary>
        void Read()
        {

        }
        /// <summary>
        /// メイン処理をここに書く
        /// </summary>
        void SolveOne()
        {
            n = sc.nextInt();
            a = sc.nextInt(n);
            Array.Sort(a);
            long ans = 0;
            ls = new int[n];
            if(n % 2 == 1)
            {
                ls[0] = a[n / 2];
                for (int i = 0; i < n/2; i++)
                {
                    ls[i * 2 + 1] = a[i];
                    ls[i * 2 + 2] = a[n - 1 - i];
                }
                ans = Math.Max(ans, Calc());

                for (int i = 0; i < n / 2; i++)
                {
                    ls[i * 2 + 2] = a[i];
                    ls[i * 2 + 1] = a[n - 1 - i];
                }
                ans = Math.Max(ans, Calc());

            }
            else
            {
                ls[0] = a[n / 2];
                for (int i = 0; i < n / 2; i++)
                {
                    ls[i * 2 + 1] = a[i];
                }
                for (int i = 0; i < n/2 -1; i++)
                {
                    ls[i * 2 + 2] = a[n - 1 - i];
                }
                ans = Math.Max(ans, Calc());

                ls[0] = a[n / 2 - 1];
                for (int i = 0; i < n / 2; i++)
                {
                    ls[i * 2 + 1] = a[n - 1 - i];
                }
                for (int i = 0; i < n / 2 - 1; i++)
                {
                    ls[i * 2 + 2] = a[i];
                }
                ans = Math.Max(ans, Calc());
            }

            Console.WriteLine(ans);
        }
        long Calc()
        {
            long ans = 0;
            for (int i = 0; i < n - 1; i++)
            {
                ans += Math.Abs(ls[i] - ls[i + 1]);
            }
            return ans;
        }
    }
