import (
	"container/list"
	"fmt"
	"sort"
)

func main() {
	var n int
	fmt.Scan(&n)
	a := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Scan(&a[i])
	}
	sort.Ints(a)

	l := list.New()
	for i := 0; i < n; i++ {
		l.PushBack(a[i])
	}

	bb := list.New()
	bb.PushBack((l.Front().Value).(int))
	bb.PushBack((l.Back().Value).(int))
	l.Remove(l.Front())
	l.Remove(l.Back())
	var x int
	for i := 1; i < n-1; i++ {
		var e *list.Element
		if i%2 == 1 {
			e = l.Front()
		} else {
			e = l.Back()
		}
		x = e.Value.(int)
		l.Remove(e)

		left := bb.Front().Value.(int)
		right := bb.Back().Value.(int)
		if abs(left-x) < abs(right-x) {
			bb.PushBack(x)
		} else {
			bb.PushFront(x)
		}
	}

	vs := make([]int, n)
	i := 0
	for e := bb.Front(); e != nil; e = e.Next() {
		vs[i] = e.Value.(int)
		i++
	}

	ans := 0
	for i := 0; i < n-1; i++ {
		ans += abs(vs[i] - vs[i+1])
	}
	fmt.Println(ans)
}

