auto solve( long[] as )
{
	as.sort();

	// 真ん中に1番小さいやつ、その外側に1,2番目に大きいやつ、その外側に2,3番目に小さいやつ…と並べたパターンを計算
	auto ans1 = solve2( as, true );

	// 真ん中に1番大きいやつ、その外側に1,2番目に小さいやつ、その外側に2,3番目に大きいやつ…と並べたパターンを計算
	auto ans2 = solve2( as, false );

	return max( ans1, ans2 );
}

auto solve2( long[] as, bool f )
{
	// 並べ替える
	auto bs = new long[ as.length ];
	auto ci = bs.length.signed / 2;
	if( f )
	{
		bs[ ci ] = as.front;
		as.popFront;
	}
	else
	{
		bs[ ci ] = as.back;
		as.popBack;
	}
	for( auto i = 1L;; i++ )
	{
		f = !f;
		if( f )
		{
			bs[ ci - i ] = as.front;
			as.popFront;
			if( as.empty ) break;
			bs[ ci + i ] = as.front;
			as.popFront;
			if( as.empty ) break;
		}
		else
		{
			bs[ ci - i ] = as.back;
			as.popBack;
			if( as.empty ) break;
			bs[ ci + i ] = as.back;
			as.popBack;
			if( as.empty ) break;
		}
	}

	// 差の合計を計算
	auto dt = 0L;
	auto p = bs.front;
	foreach( b; bs )
	{
		dt += ( p - b ).abs;
		p = b;
	}
	return dt;
}

