  int n;
  rd(n);
  auto a = new long[](n);
  foreach (i; 0 .. n)
    rd(a[i]);

  a.sort.reverse;
  long mx = 0;
  if (n & 1) {
    long sub1 = 0;
    foreach (i; 0 .. n) {
      if (i < n / 2 - 1) {
        sub1 += a[i] * 2;
      } else if (i < n / 2 + 1) {
        sub1 += a[i];
      } else {
        sub1 -= a[i] * 2;
      }
    }
    long sub2 = 0;
    foreach (i; 0 .. n) {
      if (i < n / 2) {
        sub2 += a[i] * 2;
      } else if (i < n / 2 + 2) {
        sub2 -= a[i];
      } else {
        sub2 -= a[i] * 2;
      }
    }
    mx = max(sub1, sub2);
  } else {
    foreach (i; 0 .. n) {
      if (i < n / 2 - 1) {
        mx += a[i] * 2;
      } else if (i == n / 2 - 1) {
        mx += a[i];
      } else if (i == n / 2) {
        mx -= a[i];
      } else {
        mx -= a[i] * 2;
      }
    }
  }
  writeln(mx);
}

