def solve():
    N = int(input())
    A = sorted([int(input()) for _ in (None,)*N])
    if N == 1:
        return str(0)
    if N == 2:
        return str(abs(A[0]-A[1]))
    m = -(N>>1)
    b = N&1
    c1 = 2*sum(A[m+(1-b):]) - sum(A[m-1-b:m]) - 2*sum(A[:m-1-b]) + (1-b)*A[m]
    A = A[::-1]
    c2 = -2*sum(A[m+(1-b):]) + sum(A[m-1-b:m]) + 2*sum(A[:m-1-b]) - (1-b)*A[m]
    return str(max(c1,c2))

