fn go(a: &[u64]) -> u64 {
    let n = a.len();
    let mut a = VecDeque::from(a.to_vec());
    let m = n / 2;
    let mut v = vec![0; n];
    for i in 0..n {
        match i % 4 {
            0 => v[m + (i / 2)] = a.pop_front().unwrap(),
            1 => v[m - ((i + 1) / 2)] = a.pop_back().unwrap(),
            2 => v[m + (i / 2)] = a.pop_back().unwrap(),
            3 => v[m - ((i + 1) / 2)] = a.pop_front().unwrap(),
            _ => unreachable!(),
        }
    }
    count(&v)
}

fn count(xs: &[u64]) -> u64 {
    let (mut c, mut r) = (xs[0], 0);
    for &x in &xs[1..] {
        r += if c < x { x - c } else { c - x };
        c = x;
    }
    r
}

