fn main() {
    let n: usize = read();
    let mut v: Vec<i64> = Vec::new();
    for _ in 0..n {
        v.push(read());
    }
    v.sort();
    let mut ascend_order: VecDeque<_> = v.iter().collect();
    let mut descend_order: VecDeque<_> = v.iter().rev().collect();

    let mut array_result = std::collections::VecDeque::new();

    let mut cnt = 0;
    array_result.push_back(ascend_order.pop_front().unwrap());
    // println!("a {:?}", ascend_order);
    // println!("d {:?}", descend_order);

    loop {
        if cnt % 2 == 1 {
            array_result.push_front(ascend_order.pop_front().unwrap());
            if array_result.len() == n {
                break;
            }
            array_result.push_back(ascend_order.pop_front().unwrap());
            if array_result.len() == n {
                break;
            }
        } else {
            array_result.push_front(descend_order.pop_front().unwrap());
            if array_result.len() == n {
                break;
            }
            array_result.push_back(descend_order.pop_front().unwrap());
            if array_result.len() == n {
                break;
            }
        }
        cnt += 1
    }
    // println!("{:?}", array_result);

    let mut ans: i64 = 0;
    let mut past = array_result.pop_front().unwrap();
    while !array_result.is_empty() {
        let cur = array_result.pop_front().unwrap();
        ans += (cur - past).abs();
        past = cur;
    }
    println!("{:?}", ans);
}

