        $next().parse::<$t>().expect("Parse error")
    };
}

fn main() {
    input!{
        n: usize,
        v: [i64; n]
    }
    let mut w = v;
    w.sort();
    let ans1 = solve(&w);
    w.reverse();
    let ans2 = solve(&w);
    println!("{}", std::cmp::max(ans1,ans2));
}

fn solve(v: &Vec<i64>) -> i64 {
    let n = v.len();
    let mut ret = 0;
    let mut i = 1;
    let mut j = n-1;
    let mut l = v[0];
    let mut r = v[0];
    while i <= j {
        ret += (v[j] - r).abs();
        r = v[j];
        j -= 1;
        if i > j {
            break;
        }

        ret += (v[j] - l).abs();
        l = v[j];
        j -= 1;
        if i > j {
            break;
        }

        ret += (v[i] - r).abs();
        r = v[i];
        i += 1;
        if i > j {
            break;
        }

        ret += (v[i] - l).abs();
        l = v[i];
        i += 1;
    }
    ret
}

