fn main() {
    input!(n: usize, a: [usize; n]);

    let mut a = a;
    a.sort();

    if n % 2 == 1 {
        let min_num = (n - 1) / 2;
        let mut minus = 0;
        for i in 0..min_num {
            minus += a[i] * 2;
        }
        let mut plus = a[min_num] + a[min_num + 1];
        for i in (min_num + 2)..n {
            plus += a[i] * 2;
        }
        assert!(plus >= minus);
        let ans1 = plus - minus;

        a.reverse();
        let mut plus = 0;
        for i in 0..min_num {
            plus += a[i] * 2;
        }
        let mut minus = a[min_num] + a[min_num + 1];
        for i in (min_num + 2)..n {
            minus += a[i] * 2;
        }
        assert!(plus >= minus);
        let ans2 = plus - minus;
        println!("{}", cmp::max(ans1, ans2));
    } else {
        let mut plus = 0;
        let mut minus = 0;
        for i in 0..(n / 2) {
            minus += a[i] * 2;
        }
        minus -= a[(n / 2) - 1];

        for i in (n / 2)..n {
            plus += a[i] * 2;
        }
        plus -= a[n / 2];
        println!("{}", plus - minus);
    }
}

