fn trial(A: &Vec<i64>, b: bool) -> i64 {
    let mut A = A.to_owned();
    A.sort();

    let mut li = 0;
    let mut ri = A.len();
    let mut s;

    let (mut front, mut back, mut t) = if b {
        s = -2 * A[li];
        li += 1;
        (-A[li - 1], -A[li - 1], 0)
    } else {
        ri -= 1;
        s = 2 * A[ri];
        (A[ri], A[ri], 2)
    };

    debug!(A);
    while li < ri {
        debug!((t, li, ri, front, back, s));
        if t <= 1 {
            ri -= 1;

            s += 2 * A[ri];
            back = front;
            front = A[ri];
        } else {
            s -= 2 * A[li];
            back = front;
            front = -A[li];

            li += 1;
        }
        t = (t + 1) % 4;
    }

    s - front - back
}

fn main() {
    let N = read![usize];
    let A = read![i64; N];
    println!("{}", max(trial(&A, true), trial(&A, false)));
}

