fn go(a: &[u64]) -> u64 {
    fn pop_front(v: &mut Vec<u64>) -> Option<u64> {
        let rest = v.split_off(1);
        let popped = v.get(0).cloned();
        *v = rest;
        popped
    }

    let mut a = a.to_vec();
    let n = a.len();
    let m = n / 2;
    let mut v = vec![0; n];
    for i in 0..n {
        match i % 4 {
            0 => v[m + (i / 2)] = pop_front(&mut a).unwrap(),
            1 => v[m - ((i + 1) / 2)] = a.pop().unwrap(),
            2 => v[m + (i / 2)] = a.pop().unwrap(),
            3 => v[m - ((i + 1) / 2)] = pop_front(&mut a).unwrap(),
            _ => unreachable!(),
        }
    }
    count(&v)
}

fn count(xs: &[u64]) -> u64 {
    xs.windows(2)
        .map(|w| cmp::max(w[0], w[1]) - cmp::min(w[0], w[1]))
        .sum()
}

