fn run<R: BufRead, W: Write>(i: R, o: &mut W) {
    let mut i = CpReader::new(i);
    let n = i.read::<usize>();
    let mut a = Vec::new();
    for _ in 0..n {
        a.push(i.read::<isize>());
    }

    writeln!(o, "{}", solve(a)).unwrap();
}
fn solve(mut a: Vec<isize>) -> isize {
    a.sort();

    let v = a[0];
    let mut v = (v, v);
    let mut i = (1, a.len() - 1);

    let mut result = 0;

    while i.0 <= i.1 {
        let d = ((v.0 - a[i.1]).abs(), (v.1 - a[i.0]).abs());

        if d.0 >= d.1 {
            v.0 = a[i.1];
            i.1 -= 1;
            result += d.0;
        } else {
            v.1 = a[i.0];
            i.0 += 1;
            result += d.1;
        }
        v = (min(v.0, v.1), max(v.0, v.1));
    }
    result
}

